Here’s a compact, production‑ready example of an Express .js **POST /login** handler that:

* expects a JSON body `{ email, password }`
* looks up the user in a PostgreSQL `users` table with the already‑created `pool`
* verifies the password (using **bcrypt** – you can swap it for any other hash check)
* returns **200** with a safe user object on success, or **401** on failure

```js
// ---------------------------------------------------------------
//  login.js  –  Express route for POST /login
// ---------------------------------------------------------------

const express = require('express');
const router = express.Router();
const bcrypt = require('bcrypt');   // npm i bcrypt
// `pool` is assumed to be created elsewhere and imported here
// const { pool } = require('./db');   // <-- example import

/**
 * Helper: pick only the fields you want to expose back to the client.
 * Never send password hashes or other sensitive columns.
 */
function sanitizeUser(userRow) {
  const { id, email, name, created_at, updated_at } = userRow;
  return { id, email, name, created_at, updated_at };
}

/**
 * POST /login
 * Body: { email: string, password: string }
 */
router.post('/login', async (req, res) => {
  const { email, password } = req.body;

  // Basic validation – you can replace this with a proper schema validator
  if (!email || !password) {
    return res.status(400).json({ error: 'Email and password are required.' });
  }

  try {
    // 1️⃣  Fetch the user by e‑mail
    const queryText = `
      SELECT id, email, password_hash, name, created_at, updated_at
      FROM users
      WHERE email = $1
      LIMIT 1
    `;
    const { rows } = await pool.query(queryText, [email]);

    if (rows.length === 0) {
      // No user with that e‑mail → authentication fails
      return res.sendStatus(401);
    }

    const user = rows[0];

    // 2️⃣  Compare supplied password with stored hash
    const passwordMatches = await bcrypt.compare(password, user.password_hash);
    if (!passwordMatches) {
      // Wrong password
      return res.sendStatus(401);
    }

    // 3️⃣  Authentication succeeded – send back a safe user object
    const safeUser = sanitizeUser(user);
    return res.status(200).json({ user: safeUser });

  } catch (err) {
    // Log the error (avoid leaking details to the client)
    console.error('Login error:', err);
    return res.status(500).json({ error: 'Internal server error.' });
  }
});

module.exports = router;
```

