// ---------------------------------------------------------------

const express = require('express');
const router = express.Router();   // you can also use app.post(...) directly

// Assume a pg Pool instance has already been created elsewhere and exported.
// Example: const { pool } = require('./db');
const { pool } = require('./db'); // <-- adjust the path to where your pool lives

/**
 * POST /login
 * Body: { email: string, password: string }
 */
router.post('/login', async (req, res) => {
  // 1️⃣  Validate request payload
  const { email, password } = req.body;

  if (!email || !password) {
    return res.status(400).json({ error: 'Email and password are required.' });
  }

  try {
    // 2️⃣  Query the user by email
    const queryText = `
      SELECT id, email, password, name, created_at, updated_at
      FROM users
      WHERE email = $1
      LIMIT 1;
    `;
    const { rows } = await pool.query(queryText, [email]);

    // 3️⃣  If no user found → unauthorized
    if (rows.length === 0) {
      return res.status(401).json({ error: 'Invalid email or password.' });
    }

    const user = rows[0];

    // 4️⃣  Verify password (plain‑text for demo; use bcrypt/scrypt in prod)
    if (user.password !== password) {
      return res.status(401).json({ error: 'Invalid email or password.' });
    }

    // 5️⃣  Remove sensitive fields before sending back
    const { password: _pwd, ...safeUser } = user;

    // 6️⃣  Success
    return res.status(200).json({ user: safeUser });
  } catch (err) {
    // 7️⃣  Unexpected error – log & respond with generic message
    console.error('Error during login:', err);
    return res.status(500).json({ error: 'Internal server error.' });
  }
});

