3. Looks up the user in a table called **`users`** (the table is assumed to have at least `id`, `username` and `password_hash` columns – the password column should store a hash created with `password_hash()`).
4. Verifies the password with `password_verify()`.
5. Starts a session, stores the user’s id (or any data you need) and redirects to `dashboard.php` on success.
6. On failure it redirects back to `login.php` and passes an error message (you can also store the error in a session “flash” variable if you prefer).

```php
<?php
/* --------------------------------------------------------------
 * login.php
 * --------------------------------------------------------------
 * Handles the login form (POST) and redirects the user.
 * --------------------------------------------------------------
 */

/* -----------------------------------------------------------------
 * 1️⃣  Configuration – change these values to match your environment
 * ----------------------------------------------------------------- */
$dbHost = 'localhost';          // MySQL host
$dbName = 'your_database_name'; // Database name
$dbUser = 'your_db_user';        // DB user
$dbPass = 'your_db_password';    // DB password

// Optional: define where to redirect after login
$successRedirect = 'dashboard.php';
$failureRedirect = 'login.php'; // We'll add a query string for the error

/* -----------------------------------------------------------------
 * 2️⃣  Helper: send the user to a given URL and stop execution
 * ----------------------------------------------------------------- */
function redirect($url)
{
    header('Location: ' . $url);
    exit;
}

/* -----------------------------------------------------------------
 * 3️⃣  Only accept POST requests – otherwise just show the login form
 * ----------------------------------------------------------------- */
if ($_SERVER['REQUEST_METHOD'] !== 'POST') {
    // If you have a separate HTML form, you could include it here.
    // For the purpose of this script we simply stop.
    redirect($failureRedirect);
}

/* -----------------------------------------------------------------
 * 4️⃣  Grab and validate the submitted fields
 * ----------------------------------------------------------------- */
$username = trim($_POST['username'] ?? '');
$password = $_POST['password'] ?? '';

if ($username === '' || $password === '') {
    // Missing fields – send back with an error
    $err = urlencode('Please fill in both username and password.');
    redirect("$failureRedirect?error=$err");
}

/* -----------------------------------------------------------------
 * 5️⃣  Connect to MySQL using PDO (with exception mode & proper charset)
 * ----------------------------------------------------------------- */
$dsn = "mysql:host=$dbHost;dbname=$dbName;charset=utf8mb4";

try {
    $pdo = new PDO(
        $dsn,
        $dbUser,
        $dbPass,
        [
            PDO::ATTR_ERRMODE            => PDO::ERRMODE_EXCEPTION,
            PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,
        ]
    );
} catch (PDOException $e) {
    // In production you would log this error instead of showing it.
    $err = urlencode('Database connection failed.');
    redirect("$failureRedirect?error=$err");
}

/* -----------------------------------------------------------------
 * 6️⃣  Look up the user – use a prepared statement to avoid injection
 * ----------------------------------------------------------------- */
$sql = "SELECT id, username, password_hash FROM users WHERE username = :username LIMIT 1";
$stmt = $pdo->prepare($sql);
$stmt->execute([':username' => $username]);
$user = $stmt->fetch();

if (!$user) {
    // No such user
    $err = urlencode('Invalid username or password.');
    redirect("$failureRedirect?error=$err");
}

/* -----------------------------------------------------------------
 * 7️⃣  Verify the password
 * ----------------------------------------------------------------- */
if (!password_verify($password, $user['password_hash'])) {
    // Wrong password
    $err = urlencode('Invalid username or password.');
    redirect("$failureRedirect?error=$err");
}

/* -----------------------------------------------------------------
 * 8️⃣  Password is correct → start a session and store user data
 * ----------------------------------------------------------------- */
session_start();

/* Regenerate the session ID to prevent session fixation attacks */
session_regenerate_id(true);

/* Store whatever you need – commonly the user id and maybe the name */
$_SESSION['user_id']   = $user['id'];
$_SESSION['username'] = $user['username'];

/* Optional: you can store a "flash" success message */
$_SESSION['flash_success'] = 'You have logged in successfully.';

/* -----------------------------------------------------------------
 * 9️⃣  Redirect to the dashboard (or any protected page)
 * ----------------------------------------------------------------- */
redirect($successRedirect);
```

