Below is a **complete, ready‑to‑drop‑in** example that shows:

1. **How to set a “remember‑me” cookie** when a user successfully logs‑in.  
2. **A middleware** that runs on every request, reads that cookie, looks the user up in the database and populates `req.user`.  
3. **Security‑focused cookie options** (signed, httpOnly, SameSite, Secure when you run over HTTPS).  

> **Assumptions**  
> * You already have an Express app (`app = express()`).  
> * `cookie-parser` is installed (`npm i cookie‑parser`).  
> * Your data‑access layer exposes `db.getUserById(id)` that returns a user object (or `null` if not found).  
> * You have a login route that validates credentials and knows the user’s `id`.

---

## 1. Install the required package

```bash
npm install cookie-parser
```

---

## 2. Set up the Express app (basic skeleton)

```js
// app.js
const express = require('express');
const cookieParser = require('cookie-parser');
const db = require('./db');            // <-- your DB helper (must export getUserById)
const auth = require('./auth-middleware'); // <-- the middleware we will create

const app = express();

app.use(express.json());               // for parsing JSON bodies
app.use(cookieParser('your‑very‑secret‑signing‑key')); // <-- sign cookies
app.use(auth.restoreUser);             // <‑‑ the middleware that restores req.user

// -------------------------------------------------------------------
//  Login route – sets the remember‑me cookie when credentials are OK
// -------------------------------------------------------------------
app.post('/login', async (req, res) => {
  const { email, password, rememberMe } = req.body;

  // ---- 1️⃣  Verify credentials (pseudo‑code) --------------------
  const user = await db.authenticate(email, password); // returns user or null
  if (!user) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  // ---- 2️⃣  Store user in the session (if you also use sessions) --
  // req.session.userId = user.id;   // optional, not required for remember‑me

  // ---- 3️⃣  If “remember me” was requested, set a long‑lived cookie
  if (rememberMe) {
    // The cookie value is just the user’s id – it will be signed by cookie‑parser
    // (you could also store a random token that maps to the user, see the note below)
    const cookieOptions = {
      httpOnly: true,                // not accessible via JS
      signed: true,                  // will be signed with the secret above
      maxAge: 30 * 24 * 60 * 60 * 1000, // 30 days in ms
      sameSite: 'lax',               // protects against CSRF in most cases
      // secure: true,               // uncomment when you serve over HTTPS
    };
    res.cookie('remember_me', user.id, cookieOptions);
  }

  // ---- 4️⃣  Respond ------------------------------------------------
  res.json({ message: 'Logged in', user: { id: user.id, name: user.name } });
});

// -------------------------------------------------------------------
//  Logout route – clears the remember‑me cookie
// -------------------------------------------------------------------
app.post('/logout', (req, res) => {
  // If you also keep a session, destroy it here
  // req.session.destroy();

  // Remove the remember‑me cookie
  res.clearCookie('remember_me');
  res.json({ message: 'Logged out' });
});

// -------------------------------------------------------------------
//  Example protected route – `req.user` is populated by the middleware
// -------------------------------------------------------------------
app.get('/profile', (req, res) => {
  if (!req.user) {
    return res.status(401).json({ error: 'Not authenticated' });
  }
  res.json({ profile: req.user });
});

// -------------------------------------------------------------------
//  Start the server
// -------------------------------------------------------------------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`🚀 Server listening on ${PORT}`));
