    // 4a️⃣  Find the user by email (or whatever unique field you use)
    // ----------------------------------------------------------------
    const user = await db.getUserByEmail(email);
    if (!user) {
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    // ----------------------------------------------------------------
    // 4b️⃣  Verify password (example using bcrypt)
    // ----------------------------------------------------------------
    const passwordMatches = await bcrypt.compare(password, user.passwordHash);
    if (!passwordMatches) {
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    // ----------------------------------------------------------------
    // 4c️⃣  At this point the user is authenticated.  Set req.user.
    // ----------------------------------------------------------------
    req.user = user; // optional – useful if you have session logic later

    // ----------------------------------------------------------------
    // 4d️⃣  If the UI asked for “remember‑me”, write a signed cookie that lives 30 days
    // ----------------------------------------------------------------
    if (rememberMe) {
      const cookieOptions = {
        maxAge: 30 * 24 * 60 * 60 * 1000, // 30 days in ms
        httpOnly: true,                  // not accessible via JS
        signed: true,                    // will be signed with COOKIE_SECRET
        sameSite: 'lax',                 // mitigates CSRF
        // Only send over HTTPS in production
        secure: process.env.NODE_ENV === 'production',
        // Optional: you can add `path: '/'` or a custom path if you like
      };

      // Store only the user id – never store the password or other sensitive data
      res.cookie('remember_me', String(user.id), cookieOptions);
    }

    // ----------------------------------------------------------------
    // 4e️⃣  Respond (you may also create a normal session token here)
    // ----------------------------------------------------------------
    res.json({ message: 'Logged in successfully', user: { id: user.id, email: user.email } });
  } catch (err) {
    console.error('Login error:', err);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// ------------------------------------------------------------------
// 5️⃣  Logout route – clears the remember‑me cookie
// ------------------------------------------------------------------
app.post('/logout', (req, res) => {
  // Clear the cookie by setting an immediate expiration
  res.clearCookie('remember_me', {
    httpOnly: true,
    signed: true,
    sameSite: 'lax',
    secure: process.env.NODE_ENV === 'production',
  });

  // If you also keep a session, destroy it here
  // req.session.destroy(...)

  res.json({ message: 'Logged out' });
});

// ------------------------------------------------------------------
// 6️⃣  Example of a protected endpoint that uses req.user
// ------------------------------------------------------------------
app.get('/profile', (req, res) => {
  if (!req.user) {
    return res.status(401).json({ error: 'Not authenticated' });
  }

  // Return whatever profile data you want
  res.json({ id: req.user.id, email: req.user.email, name: req.user.name });
});

// ------------------------------------------------------------------
// 7️⃣  Start the server
// ------------------------------------------------------------------
