## 1️⃣  `rememberMe.js` – the middleware & helper

```js
// rememberMe.js
const cookieParser = require('cookie-parser'); // just for TS/IDE hinting – already required in app
const ms = require('ms'); // optional, for a readable maxAge (npm i ms)

/**
 * Middleware that restores req.user from a signed remember_me cookie.
 *
 * @param {Object}   options
 * @param {function(string):Promise<Object>} options.getUserById
 *        Async function that receives a user‑id (string) and returns the user object
 *        or null/undefined if the user does not exist.
 * @param {string}   [options.cookieName='remember_me']
 * @param {number}   [options.maxAge=30*24*60*60*1000] // 30 days in ms
 *
 * @returns {function(req, res, next)} Express middleware
 */
function rememberMe(options) {
  const {
    getUserById,
    cookieName = 'remember_me',
    maxAge = 30 * 24 * 60 * 60 * 1000, // 30 days
  } = options;

  if (typeof getUserById !== 'function')
    throw new Error('rememberMe middleware: options.getUserById must be a function');

  return async function (req, res, next) {
    // If the request is already authenticated (e.g. session), skip
    if (req.user) return next();

    // The cookie is signed, so we read it from req.signedCookies
    const signedVal = req.signedCookies[cookieName];
    if (!signedVal) return next(); // No remember‑me cookie → continue unauthenticated

    // The value we stored is the user id (as a string)
    const userId = signedVal;

    try {
      const user = await getUserById(userId);
      if (!user) {
        // User no longer exists – clean up the stale cookie
        res.clearCookie(cookieName, cookieOptions(req));
        return next();
      }

      // Attach the user object to the request – now the rest of the app sees a logged‑in user
      req.user = user;

      // Optional: refresh the cookie expiration on every request (sliding expiration)
      // Comment out if you prefer a fixed 30‑day window.
      res.cookie(cookieName, userId, {
        ...cookieOptions(req),
        maxAge,
      });
    } catch (err) {
      // DB error – we don't want to crash the whole request pipeline
      console.error('rememberMe middleware error:', err);
    }

    return next();
  };
}

/**
 * Helper that you call after a successful login to set the remember‑me cookie.
 *
 * @param {Object}   res          Express response object
 * @param {string}   userId       The id of the logged‑in user (as a string)
 * @param {Object}   opts
 * @param {boolean}  [opts.rememberMe]   If falsey, the cookie is not set.
 * @param {string}   [opts.cookieName='remember_me']
 * @param {number}   [opts.maxAge=30*24*60*60*1000] // 30 days
 * @param {Object}   [opts.res]            The Express response (required)
 * @param {function} [opts.isProduction]   Function that returns true in prod (default: NODE_ENV === 'production')
 */
function setRememberMeCookie(res, userId, opts = {}) {
  const {
    rememberMe = true,
    cookieName = 'remember_me',
    maxAge = 30 * 24 * 60 * 60 * 1000, // 30 days
    isProduction = () => process.env.NODE_ENV === 'production',
  } = opts;

  if (!rememberMe) {
    // Caller explicitly said "do not remember"
    res.clearCookie(cookieName, cookieOptions(res.req));
    return;
  }

  const options = {
    ...cookieOptions(res.req),
    maxAge,
    // Signed cookie – the secret is defined when you call cookieParser()
    signed: true,
  };

  // We store the raw userId (signed by cookie‑parser).  In a production app you would
  // probably store a random token instead.
  res.cookie(cookieName, String(userId), options);
}

/**
 * Common cookie options used both for setting and clearing the cookie.
 *
 * @param {Object} req Express request (used to detect HTTPS)
 * @returns {Object}
 */
function cookieOptions(req) {
  const secure = req.secure || req.headers['x-forwarded-proto'] === 'https';
  return {
    httpOnly: true,
    secure,               // true in production (HTTPS)
    sameSite: 'strict',   // or 'lax' if you need cross‑site navigation
    path: '/',            // cookie valid for the whole site
  };
}

/**
 * Helper to clear the remember‑me cookie (e.g. on logout)
 *
 * @param {Object} res Express response
 */
function clearRememberMeCookie(res, cookieName = 'remember_me') {
  res.clearCookie(cookieName, cookieOptions(res.req));
}

/* -------------------------------------------------------------------------- */
/* Export -------------------------------------------------------------------- */
module.exports = {
  rememberMe,
  setRememberMeCookie,
  clearRememberMeCookie,
};
```

