## 4️⃣ **Remember‑Me Middleware** – restores `req.user`

```js
/**
 * rememberMeMiddleware
 *
 * 1. If the request already has a logged‑in user (e.g. via session) – do nothing.
 * 2. If a signed cookie named "rememberMe" exists, verify its JWT.
 * 3. On successful verification, load the user from DB and attach it to req.user.
 * 4. If verification fails (tampered, expired, DB miss) – clear the cookie.
 */
async function rememberMeMiddleware(req, res, next) {
  try {
    // 1️⃣ Already logged‑in via session? → skip.
    if (req.session && req.session.userId) {
      // Optionally, you can also attach the user object here:
      // req.user = await db.getUserById(req.session.userId);
      return next();
    }

    // 2️⃣ No signed cookie → nothing to do.
    const token = req.signedCookies.rememberMe;
    if (!token) return next();

    // 3️⃣ Verify JWT (throws if invalid/expired)
    const payload = jwt.verify(token, process.env.JWT_SECRET);
    const userId = payload.userId;

    // 4️⃣ Load the user from DB
    const user = await db.getUserById(userId);
    if (!user) {
      // User no longer exists → clean up cookie
      res.clearCookie('rememberMe');
      return next();
    }

    // 5️⃣ Success – attach user to request
    req.user = user;

    // (Optional) create a fresh session so the rest of the app can treat it like a normal login
    if (req.session) {
      req.session.userId = user.id;
    }

    next();
  } catch (err) {
    // Any error (invalid token, expired, DB error…) → clear cookie & continue unauthenticated
    console.warn('Remember‑Me cookie error:', err.message);
    res.clearCookie('rememberMe');
    next();
  }
}

// Register the middleware **before** any route that needs req.user
app.use(rememberMeMiddleware);
```

