 * POST /login
 *
 * Expected body: { email, password, rememberMe }   // rememberMe is a boolean (checkbox)
 *
 * On success:
 *   • Store user id in the session (normal login)
 *   • If rememberMe === true → issue a signed JWT cookie that lives 30 days
 */
app.post('/login', async (req, res) => {
  const { email, password, rememberMe } = req.body;

  // ---- 1️⃣ Authenticate the user (replace with your own logic) ----
  const user = await db.getUserByCredentials(email, password); // <- you must implement this
  if (!user) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  // ---- 2️⃣ Normal session login ----
  req.session.userId = user.id;

  // ---- 3️⃣ Remember‑Me cookie (if requested) ----
  if (rememberMe) {
    // Create a JWT that contains the user id and expires in 30 days
    const token = jwt.sign(
      { userId: user.id },
      process.env.JWT_SECRET,
      { expiresIn: '30d' } // 30 days
    );

    // Set the cookie – signed, HttpOnly, Secure (in prod), SameSite=Lax
    res.cookie('rememberMe', token, {
      maxAge: 30 * 24 * 60 * 60 * 1000, // 30 days in ms
      httpOnly: true,
      signed: true,
      secure: process.env.NODE_ENV === 'production', // only over HTTPS
      sameSite: 'lax',
    });
  }

  // ---- 4️⃣ Respond ----
  res.json({ message: 'Logged in successfully', user: { id: user.id, email: user.email } });
});
