// rememberMe.js
// Express middleware that issues and consumes a signed "remember_me" cookie.
// The cookie stores the user id and keeps the user logged in for 30 days.

const express = require('express');
const cookieParser = require('cookie-parser');
const db = require('./db'); // db.getUserById(id) → Promise<User>

const COOKIE_NAME = 'remember_me';
