**Key points**

* The cookie is signed (`signed: true`) with a secret, preventing tampering.
* It expires after 30 days (`maxAge`).
* On each request the middleware checks the signed cookie, loads the user from `db.getUserById`, and populates `req.user`.
* Login route sets the cookie when the client asks for “remember me”.
* Logout route clears the cookie.

```js
// app.js
const express = require('express');
const cookieParser = require('cookie-parser');
const crypto = require('crypto'); // for token generation
const db = require('./db'); // assume db.getUserById(id) returns a user object

const app = express();
app.use(express.json());
app.use(cookieParser());

// ---------- Remember‑Me Middleware ----------
/**
 * Checks for a signed "remember_me" cookie.
 * If present, validates the token, loads the user and attaches it to req.user.
 * The token format: base64(userId):base64(signature)
 * Signature = HMAC_SHA256(userId + secret)
 */
const REMEMBER_ME_COOKIE = 'remember_me';
const COOKIE_MAX_AGE = 30 * 24 * 60 * 60 * 1000; // 30 days in ms
const SECRET = process.env.REMEMBER_ME_SECRET || 'change_this_secret';

function signToken(userId) {
  const payload = Buffer.from(String(userId)).toString('base64');
  const hmac = crypto.createHmac('sha256', SECRET);
  hmac.update(payload);
  const signature = hmac.digest('base64');
  return `${payload}.${signature}`;
}

function verifyToken(token) {
  const [payloadB64, signatureB64] = token.split('.');
  if (!payloadB64 || !signatureB64) return null;
  const hmac = crypto.createHmac('sha256', SECRET);
  hmac.update(payloadB64);
  const expectedSig = hmac.digest('base64');
  if (!crypto.timingSafeEqual(Buffer.from(signatureB64), Buffer.from(expectedSig))) {
    return null;
  }
  const userId = Buffer.from(payloadB64, 'base64').toString('utf8');
  return userId;
}

// Middleware to restore user from remember‑me cookie
async function rememberMe(req, res, next) {
  if (req.user) return next(); // already authenticated (e.g., session)

  const token = req.signedCookies[REMEMBER_ME_COOKIE];
  if (!token) return next();

  const userId = verifyToken(token);
  if (!userId) {
    // Invalid token → clear cookie
    res.clearCookie(REMEMBER_ME_COOKIE);
    return next();
  }

  try {
    const user = await db.getUserById(userId);
    if (user) {
      req.user = user; // attach user to request
    } else {
      // User no longer exists → clear cookie
      res.clearCookie(REMEMBER_ME_COOKIE);
    }
  } catch (err) {
    console.error('Remember‑me error:', err);
  }
  next();
}

// ---------- Login Route ----------
app.post('/login', async (req, res) => {
  const { email, password, rememberMe } = req.body;

  // Replace with your real authentication logic
  const user = await db.authenticate(email, password);
  if (!user) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  // Example: set a session (not shown) here...
  req.session.userId = user.id;

  // If "remember me" was requested, set a signed cookie
  if (rememberMe) {
    const token = signToken(user.id);
    res.cookie(REMEMBER_ME_COOKIE, token, {
      maxAge: COOKIE_MAX_AGE,
      httpOnly: true,
      signed: true,
      sameSite: 'lax',
      // secure: true, // enable in production with HTTPS
    });
  }

  res.json({ success: true, user: { id: user.id, email: user.email } });
});

// ---------- Protected Route Example ----------
app.get('/profile', rememberMe, (req, res) => {
  if (!req.user) {
    return res.status(401).json({ error: 'Not authenticated' });
  }
  res.json({ profile: req.user });
});

// ---------- Logout ----------
app.post('/logout', (req, res) => {
  // destroy session if using one
  req.session?.destroy(() => {});
  // clear remember‑me cookie
  res.clearCookie(REMEMBER_ME_COOKIE);
  res.json({ success: true });
});

module.exports = app;
```

