## 3️⃣ Express app – setup

```js
// app.js
const express = require('express');
const cookieParser = require('cookie-parser');
const { v4: uuidv4 } = require('uuid');
const db = require('./db');

const app = express();

// ------------------------------------------------------------------
// 1️⃣ Middleware that parses JSON bodies (adjust if you use something else)
// ------------------------------------------------------------------
app.use(express.json());

// ------------------------------------------------------------------
// 2️⃣ cookie‑parser – give it a secret so we can sign cookies
// ------------------------------------------------------------------
const COOKIE_SECRET = process.env.COOKIE_SECRET || 'change‑me‑to‑a‑strong‑random‑string';
app.use(cookieParser(COOKIE_SECRET));

// ------------------------------------------------------------------
// 3️⃣ Remember‑Me middleware (runs on every request)
// ------------------------------------------------------------------
app.use(async (req, res, next) => {
  // If the request already has a user (e.g. from a session) we skip the cookie check.
  if (req.user) return next();

  // Look for the signed remember‑me cookie
  const token = req.signedCookies['remember_me'];
  if (!token) return next(); // No cookie → anonymous request

  try {
    // 1️⃣ Verify the token exists and is not expired
    const userId = await db.findUserIdByRememberMeToken(token);
    if (!userId) {
      // Token invalid/expired → clear it from the client
      res.clearCookie('remember_me');
      return next();
    }

    // 2️⃣ Load the user from DB
    const user = await db.getUserById(userId);
    if (!user) {
      // User disappeared → also clear cookie
      await db.deleteRememberMeToken(token);
      res.clearCookie('remember_me');
      return next();
    }

    // 3️⃣ Attach the user to the request
    req.user = user;

    // OPTIONAL: refresh the cookie expiration (sliding window)
    // Uncomment if you want a “rolling” 30‑day window.
    // const newExpires = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000);
    // res.cookie('remember_me', token, cookieOptions(newExpires));

  } catch (err) {
    // Something went wrong → log & continue as anonymous
    console.error('Remember‑Me middleware error:', err);
  }

  next();
});

// ------------------------------------------------------------------
// Helper to build cookie options (used both on login & refresh)
// ------------------------------------------------------------------
function cookieOptions(expires) {
  const opts = {
    httpOnly: true,               // not readable by JS
    signed: true,                 // signed with COOKIE_SECRET
    maxAge: 30 * 24 * 60 * 60 * 1000, // 30 days in ms
    sameSite: 'lax',              // adjust to 'strict' or 'none' as needed
    // secure: true,              // uncomment when serving over HTTPS
    path: '/',                    // cookie sent on all routes
    expires: expires || new Date(Date.now() + 30 * 24 * 60 * 60 * 1000)
  };
  return opts;
}

// ------------------------------------------------------------------
// 4️⃣ Login route – issues the remember‑me cookie when requested
// ------------------------------------------------------------------
app.post('/login', async (req, res) => {
  const { username, password, rememberMe } = req.body;

  // --------------------------------------------------------------
  // 👉 Replace this with your real authentication logic
  // --------------------------------------------------------------
  const fakeUserId = username === 'alice' && password === 'secret' ? 1 : null;
  if (!fakeUserId) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  const user = await db.getUserById(fakeUserId);
  req.user = user; // attach for this request (e.g. to generate a session token)

  // --------------------------------------------------------------
  // 👉 If the client asked for “remember‑me”, create a long‑lived cookie
  // --------------------------------------------------------------
  if (rememberMe) {
    const token = uuidv4(); // cryptographically random opaque token
    const expiresAt = Date.now() + 30 * 24 * 60 * 60 * 1000; // 30 days

    // Persist the token so we can look it up later
    await db.storeRememberMeToken(user.id, token, expiresAt);

    // Send the signed cookie
    res.cookie('remember_me', token, cookieOptions(new Date(expiresAt)));
  }

  // --------------------------------------------------------------
  // 👉 You probably also set a short‑lived session/JWT here.
  // --------------------------------------------------------------
  // Example: res.json({ token: createJwt(user) });

  res.json({ message: 'Logged in', user: { id: user.id, username: user.username } });
});

// ------------------------------------------------------------------
// 5️⃣ Logout route – clears the remember‑me cookie and revokes token
// ------------------------------------------------------------------
app.post('/logout', async (req, res) => {
  // Remove the token from DB if we have one
  const token = req.signedCookies['remember_me'];
  if (token) {
    await db.deleteRememberMeToken(token);
  }

  // Clear the cookie on the client
  res.clearCookie('remember_me', { path: '/' });

  // Also clear any session/JWT you may have created
  // e.g. req.session.destroy();

  res.json({ message: 'Logged out' });
});

// ------------------------------------------------------------------
// 6️⃣ A protected route example – only reachable when req.user exists
// ------------------------------------------------------------------
