```js
// rememberMe.js
// Express middleware that issues a signed "remember_me" cookie on login
// and restores req.user from that cookie on subsequent requests.

const cookieParser = require('cookie-parser');
const express = require('express');
const db = require('./db'); // db.getUserById(id) => Promise<User|null>

const COOKIE_NAME = 'remember_me';
const COOKIE_MAX_AGE = 30 * 24 * 60 * 60 * 1000; // 30 days in ms

/**
 * Initialize cookie‑parser with a secret.
 * Must be added to the app before the remember‑me middleware.
 */
function initCookieParser(secret) {
  return cookieParser(secret);
}

/**
 * Middleware that checks for a signed remember_me cookie.
 * If present, loads the user from the DB and attaches it to req.user.
 * Calls next() regardless of outcome (fails silently).
 */
function rememberMeMiddleware() {
  return async (req, res, next) => {
    // If user already authenticated (e.g., session) skip.
    if (req.user) return next();

    const signedId = req.signedCookies[COOKIE_NAME];
    if (!signedId) return next();

    try {
      const user = await db.getUserById(signedId);
      if (user) {
        req.user = user; // restore user on request
      } else {
        // Invalid user – clear the cookie
        res.clearCookie(COOKIE_NAME);
      }
    } catch (err) {
      // DB error – log and continue without user
      console.error('Remember‑me DB error:', err);
    }
    next();
  };
}

/**
 * Call this after a successful login to issue the remember‑me cookie.
 * Pass the user object (must contain an `id` property) and a boolean
 * indicating whether the user opted‑in for "remember me".
 */
function setRememberMeCookie(user, remember) {
  return (req, res, next) => {
    if (!remember) return next();

    // Sign the user id; cookie-parser will sign it automatically.
    res.cookie(COOKIE_NAME, user.id, {
      maxAge: COOKIE_MAX_AGE,
      httpOnly: true,
      signed: true,
      // In production you should enable `secure: true` and `sameSite: 'strict'`
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'lax',
    });
    next();
  };
}

/* ------------------------------------------------------------------ */
/* Example usage in an Express app ----------------------------------- */

const app = express();

// secret used for signing cookies
const COOKIE_SECRET = 'your‑very‑strong‑secret‑here';

// parse JSON bodies, cookies, etc.
app.use(express.json());
app.use(initCookieParser(COOKIE_SECRET));

// restore user from remember‑me cookie (runs before protected routes)
app.use(rememberMeMiddleware());

// ----- Login route -------------------------------------------------
app.post('/login', async (req, res, next) => {
  const { email, password, rememberMe } = req.body;

  // ...authenticate user (e.g., compare password hash)...
  const user = await db.authenticate(email, password);
  if (!user) return res.status(401).json({ error: 'Invalid credentials' });

  // store user in session (if you use sessions)
  req.session.userId = user.id;
  req.user = user; // make it available immediately

  // issue remember‑me cookie if requested
  setRememberMeCookie(user, rememberMe)(req, res, () => {
    res.json({ success: true });
  });
});

// ----- Protected route example ------------------------------------
app.get('/profile', (req, res) => {
  if (!req.user) return res.status(401).json({ error: 'Unauthenticated' });
  res.json({ profile: req.user });
});

// ----- Logout ------------------------------------------------------
app.post('/logout', (req, res) => {
  // clear session & remember‑me cookie
  req.session.destroy(() => {});
  res.clearCookie(COOKIE_NAME);
  res.json({ success: true });
});

module.exports = {
  initCookieParser,
  rememberMeMiddleware,
  setRememberMeCookie,
};
