// rememberMe.js
// Express middleware for "remember‑me" functionality using cookie‑parser.
// The cookie is signed, HTTP‑only and lasts 30 days.

const cookieParser = require('cookie-parser');
const crypto = require('crypto');

// 30 days in milliseconds
const REMEMBER_ME_MAX_AGE = 30 * 24 * 60 * 60 * 1000;

// name of the signed cookie
const COOKIE_NAME = 'remember_me';

// -------------------------------------------------------------------
// 1️⃣ Middleware that must be added early (after cookieParser) to
//    restore req.user from the remember‑me cookie, if present.
function restoreUserFromCookie(db) {
  return async function (req, res, next) {
    // If user is already authenticated, skip
    if (req.user) return next();

    const token = req.signedCookies[COOKIE_NAME];
    if (!token) return next();

    try {
      // token format: <userId>:<randomString>
      const [userId] = token.split(':');
      const user = await db.getUserById(userId);
      if (!user) return next();

      // Optionally verify the random part (e.g., compare with a DB‑stored
      // token for revocation). Skipped here for brevity.
      req.user = user;               // attach user to request
      req.session = req.session || {}; // ensure a session object exists
      req.session.userId = user.id;   // optional: create a session entry
    } catch (err) {
      // On any error, just ignore the cookie – it will be cleared later.
    }
    next();
  };
}

// -------------------------------------------------------------------
// 2️⃣ Helper to be called after a successful login (e.g., inside a
//    POST /login handler). Pass `res` and the logged‑in `user` object.
function setRememberMeCookie(res, user, rememberMe) {
  if (!rememberMe) return; // user didn't tick "remember me"

  // Create a simple token; you could store a hash in DB for extra security.
  const random = crypto.randomBytes(16).toString('hex');
  const token = `${user.id}:${random}`;

  // Set a signed, HTTP‑only cookie that lasts 30 days.
  res.cookie(COOKIE_NAME, token, {
    maxAge: REMEMBER_ME_MAX_AGE,
    httpOnly: true,
    signed: true,
    // secure: true,   // enable in production with HTTPS
    // sameSite: 'lax',
  });
}

// -------------------------------------------------------------------
// 3️⃣ Middleware to clear the cookie on logout or when authentication fails.
function clearRememberMeCookie(res) {
  res.clearCookie(COOKIE_NAME, { httpOnly: true, signed: true });
}

// -------------------------------------------------------------------
// Export utilities
module.exports = {
  cookieParserMiddleware: cookieParser('your-secret-here'), // use a strong secret
  restoreUserFromCookie,
  setRememberMeCookie,
  clearRememberMeCookie,
};
