  res.cookie(COOKIE_NAME, userId, {
    maxAge: COOKIE_AGE,
    httpOnly: true,   // not accessible via client‑side JS
    signed: true,     // sign to prevent tampering
    // secure: true,  // enable in production (HTTPS)
    sameSite: 'lax',
  });
}

/**
 * Middleware that checks the remember‑me cookie and populates req.user.
 * Should be placed early in the middleware chain (after cookieParser).
 */
async function rememberMeMiddleware(req, res, next) {
  // If the request already has a user (e.g., from a session) skip.
  if (req.user) return next();

  // Retrieve signed cookie value; undefined if missing or tampered.
  const userId = req.signedCookies[COOKIE_NAME];
  if (!userId) return next();

