// rememberMe.js
// Express middleware for "remember‑me" functionality.
// - Sets a signed cookie (30‑day expiry) after a successful login.
// - Reads the cookie on subsequent requests and populates req.user.
// Requires: express, cookie-parser, and a db module exposing getUserById(id).

const cookieParser = require('cookie-parser');

// 30 days in milliseconds
const REMEMBER_ME_MAX_AGE = 30 * 24 * 60 * 60 * 1000;

// ---------------------------------------------------------------------------
// 1️⃣ Middleware to initialise cookie‑parser with a secret.
//    Place this near the top of your middleware chain (e.g. app.use(...)).
function initCookieParser(secret) {
  return cookieParser(secret);
}

// ---------------------------------------------------------------------------
// 2️⃣ Middleware to restore req.user from the signed remember‑me cookie.
//    Should run after initCookieParser and after any session/auth middleware.
function rememberMeMiddleware(req, res, next) {
  // If user is already authenticated (e.g. via session) skip.
  if (req.user) return next();

  // Signed cookie name
  const cookieName = 'remember_me';

  // The cookie is signed, so we read it from req.signedCookies
  const signedUserId = req.signedCookies?.[cookieName];
  if (!signedUserId) return next();

  // Verify that the cookie value looks like a numeric ID (optional)
  const userId = parseInt(signedUserId, 10);
  if (Number.isNaN(userId)) return next();

  // Fetch the user from DB and attach to the request.
  // Assume db.getUserById returns a Promise that resolves to a user object
  // or null/undefined if not found.
  db.getUserById(userId)
    .then(user => {
      if (user) {
        req.user = user;               // make user available downstream
        // Optionally, you may also create a session here:
        // req.session.userId = user.id;
      }
      next();
    })
    .catch(err => {
      // Log the error and continue without a user
      console.error('rememberMeMiddleware error:', err);
      next();
    });
}

// ---------------------------------------------------------------------------
// 3️⃣ Helper to set the remember‑me cookie after a successful login.
//    Call this from your login route after you have validated credentials.
function setRememberMeCookie(res, userId, rememberMe = false) {
  if (!rememberMe) return; // client did not ask for persistent login

  // Signed cookie with 30‑day maxAge
  res.cookie('remember_me', String(userId), {
    maxAge: REMEMBER_ME_MAX_AGE,
    httpOnly: true,      // not accessible via JavaScript
    secure: process.env.NODE_ENV === 'production', // send only over HTTPS
    signed: true,        // sign the cookie to prevent tampering
    sameSite: 'lax'      // adjust to your CSRF strategy
  });
}

// ---------------------------------------------------------------------------
// Export all utilities
module.exports = {
  initCookieParser,
  rememberMeMiddleware,
  setRememberMeCookie
};
