// rememberMe.js
// Express middleware for "remember‑me" functionality.
// Requires: cookie-parser middleware installed earlier in the app.

const crypto = require('crypto'); // for generating a signed token
const COOKIE_NAME = 'remember_me';
const COOKIE_MAX_AGE = 30 * 24 * 60 * 60 * 1000; // 30 days in ms

/**
 * Generate a signed token that can be verified later.
 * Here we simply sign the user id; in a real app you might also
 * include a random secret stored in the DB to allow revocation.
 */
function signToken(userId) {
  const secret = process.env.REMEMBER_ME_SECRET || 'fallback-secret';
  const payload = `${userId}:${Date.now()}`;
  return `${payload}.${crypto.createHmac('sha256', secret).update(payload).digest('hex')}`;
}

/**
 * Verify a token and return the embedded userId if valid,
 * otherwise return null.
 */
function verifyToken(token) {
  const secret = process.env.REMEMBER_ME_SECRET || 'fallback-secret';
  const [payload, sig] = token.split('.');
  if (!payload || !sig) return null;
  const expectedSig = crypto.createHmac('sha256', secret).update(payload).digest('hex');
  if (!crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expectedSig))) return null;
  const [userId] = payload.split(':');
  return userId;
}

/**
 * Middleware to restore req.user from the remember‑me cookie.
 * Should be placed early in the request pipeline (after cookie‑parser).
 */
async function restoreUser(req, res, next) {
  // If the request already has a logged‑in user, skip.
  if (req.user) return next();

  const token = req.cookies[COOKIE_NAME];
  if (!token) return next();

  const userId = verifyToken(token);
  if (!userId) {
    // Invalid token – clear the cookie.
    res.clearCookie(COOKIE_NAME);
    return next();
  }

  try {
    const user = await db.getUserById(userId);
    if (user) {
      req.user = user; // attach user to request
    } else {
      // User no longer exists – clear cookie.
      res.clearCookie(COOKIE_NAME);
    }
  } catch (err) {
    // DB error – just continue without user.
    console.error('Error restoring user from remember‑me cookie:', err);
  }
  return next();
}

/**
 * Helper to be called after a successful login.
 * Sets the remember‑me cookie if the client requested it.
 *
 * @param {Object} res   Express response object
 * @param {string} userId  ID of the authenticated user
 * @param {boolean} rememberMe  Whether the user opted‑in for remember‑me
 */
function setRememberMeCookie(res, userId, rememberMe) {
  if (!rememberMe) {
    // Ensure any stale cookie is removed.
    res.clearCookie(COOKIE_NAME);
    return;
  }

  const token = signToken(userId);
  res.cookie(COOKIE_NAME, token, {
    maxAge: COOKIE_MAX_AGE,
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production', // only over HTTPS in prod
    sameSite: 'lax',
  });
}

// Export both middleware and helper
module.exports = {
  restoreUser,
  setRememberMeCookie,
};
