// rememberMe.js
// Express middleware to issue and verify a "remember-me" cookie (30‑day lifespan)

const cookieParser = require('cookie-parser');
const crypto = require('crypto');

// secret used to sign the cookie value (keep it safe!)
const COOKIE_SECRET = process.env.COOKIE_SECRET || 'change_this_secret';

// name of the cookie
const COOKIE_NAME = 'remember_me';

// ---------------------------------------------------
// Helper: generate a signed token containing the user ID
function createToken(userId) {
  // token = base64(userId) + '.' + HMAC(userId, secret)
  const payload = Buffer.from(String(userId)).toString('base64');
  const sig = crypto
    .createHmac('sha256', COOKIE_SECRET)
    .update(payload)
    .digest('hex');
  return `${payload}.${sig}`;
}

// Helper: verify a token and return the original userId (or null)
function verifyToken(token) {
  const [payload, sig] = token.split('.');
  if (!payload || !sig) return null;
  const expectedSig = crypto
    .createHmac('sha256', COOKIE_SECRET)
    .update(payload)
    .digest('hex');
  if (!crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expectedSig))) {
    return null;
  }
  const userId = Buffer.from(payload, 'base64').toString('utf8');
  return userId;
}

// ---------------------------------------------------
// Middleware to attach to routes that handle login
// Call `req.login(user)` after successful authentication.
function loginHandler(req, res, next) {
  // Attach a helper to the request so the login route can call it
  req.login = async function (user, rememberMe = false) {
    // Store user in session (if you use sessions)
    if (req.session) req.session.userId = user.id;

    // If "remember me" is requested, set a persistent cookie
    if (rememberMe) {
      const token = createToken(user.id);
      // 30 days = 30 * 24 * 60 * 60 * 1000 ms
      res.cookie(COOKIE_NAME, token, {
        maxAge: 30 * 24 * 60 * 60 * 1000,
        httpOnly: true,
        secure: process.env.NODE_ENV === 'production',
        sameSite: 'lax',
      });
    }
  };
  next();
}

// ---------------------------------------------------
// Middleware to run on every request (after cookieParser)
async function rememberMeMiddleware(req, res, next) {
  // If session already has a user, nothing to do
  if (req.session && req.session.userId) {
    // Optionally load the full user object
    req.user = await db.getUserById(req.session.userId);
    return next();
  }

  // No session – try to restore from remember‑me cookie
  const token = req.cookies[COOKIE_NAME];
  if (!token) return next();

  const userId = verifyToken(token);
  if (!userId) {
    // Invalid/tempered cookie – clear it
    res.clearCookie(COOKIE_NAME);
    return next();
  }

  // Load user from DB and attach to request
  const user = await db.getUserById(userId);
  if (user) {
    // Populate session so subsequent requests are fast
    if (req.session) req.session.userId = user.id;
    req.user = user;
  } else {
    // User no longer exists – remove cookie
    res.clearCookie(COOKIE_NAME);
  }
  next();
}

// ---------------------------------------------------
// Export for use in your Express app
module.exports = {
  cookieParserMiddleware: cookieParser(COOKIE_SECRET),
  loginHandler,
  rememberMeMiddleware,
};
