// Express middleware for "remember me" functionality using a signed cookie.
// The cookie lasts 30 days and stores a signed token (user ID) that is used
// to re‑populate req.user on subsequent requests.

const cookieParser = require('cookie-parser');
const crypto = require('crypto');

// Secret used to sign the remember‑me cookie (must be the same as used for
// cookie‑parser). In a real app keep this in an env variable.
const COOKIE_SECRET = process.env.COOKIE_SECRET || 'change_this_secret';
const COOKIE_NAME   = 'remember_me';
const COOKIE_MAX_AGE = 30 * 24 * 60 * 60 * 1000; // 30 days in ms

/**
 * Helper to create a signed token for the cookie.
 * Here we simply sign the user ID; you could embed a random token and store it
 * server‑side for extra security.
 */
function signToken(userId) {
  const hmac = crypto.createHmac('sha256', COOKIE_SECRET);
  hmac.update(String(userId));
  return `${userId}.${hmac.digest('hex')}`;
}

/**
 * Verify a token from the cookie and return the userId if valid.
 */
function verifyToken(token) {
  const [userId, sig] = token.split('.');
  if (!userId || !sig) return null;
  const expected = signToken(userId);
  return crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(token))
    ? userId
    : null;
}

/**
 * Middleware to be used after a successful login.
 * Call `req.login(user, rememberMe)` where `rememberMe` is a boolean.
 */
function loginHandler(db) {
  return async function (req, res, next) {
    // Assume a previous auth step set req.authenticatedUser
    const user = req.authenticatedUser;
    if (!user) return next();

    // Attach user to request for this request cycle
    req.user = user;

    // If "remember me" was requested, set a persistent signed cookie
    if (req.body.rememberMe) {
      const token = signToken(user.id);
      res.cookie(COOKIE_NAME, token, {
        maxAge: COOKIE_MAX_AGE,
        httpOnly: true,
        signed: false, // we already sign the value ourselves
        sameSite: 'lax',
        // secure: true, // uncomment when using HTTPS
      });
    }
    next();
  };
}

/**
 * Middleware that runs on every request to restore req.user from the cookie.
 */
function rememberMeMiddleware(db) {
  return async function (req, res, next) {
    // If user is already set (e.g., session auth), skip
    if (req.user) return next();

    const token = req.cookies[COOKIE_NAME];
    if (!token) return next();

    const userId = verifyToken(token);
    if (!userId) {
      // Invalid token – clear the cookie
      res.clearCookie(COOKIE_NAME);
      return next();
    }

    try {
      const user = await db.getUserById(userId);
      if (user) {
        req.user = user; // restore user for this request
        // Optionally refresh the cookie expiration
        res.cookie(COOKIE_NAME, token, {
          maxAge: COOKIE_MAX_AGE,
          httpOnly: true,
          sameSite: 'lax',
          // secure: true,
        });
      } else {
        // User no longer exists – clear cookie
        res.clearCookie(COOKIE_NAME);
      }
    } catch (err) {
      // DB error – proceed without user, but don't expose details
      console.error('Remember‑me DB error:', err);
    }
    next();
  };
}

