// rememberMe.js
// Express middleware that issues a signed "remember_me" cookie on login
// and restores req.user from it on subsequent requests.
// Cookie expires in 30 days.

const crypto = require('crypto');
const cookieParser = require('cookie-parser');

// secret used for signing cookies – should be the same as your app's secret
const COOKIE_SECRET = process.env.COOKIE_SECRET || 'change_this_secret';

// name of the cookie
const COOKIE_NAME = 'remember_me';

// -------------------------------------------------------------------
// Helper: generate a random token to store in the cookie
function generateToken() {
  return crypto.randomBytes(32).toString('hex');
}

// -------------------------------------------------------------------
// Middleware to attach to login route.
// Call `issueRememberMe(res, userId)` after successful authentication.
function issueRememberMe(res, userId) {
  const token = generateToken();

  // You may want to store the token in DB to allow revocation.
  // For simplicity we embed the userId directly (signed cookie prevents tampering).
  const payload = { userId, token };

  // Set a signed cookie that lasts 30 days
  res.cookie(COOKIE_NAME, payload, {
    maxAge: 30 * 24 * 60 * 60 * 1000, // 30 days in ms
    httpOnly: true,
    signed: true,
    sameSite: 'lax',
    // secure: true, // enable in production (HTTPS)
  });
}

// -------------------------------------------------------------------
// Middleware to restore req.user from the remember‑me cookie
function rememberMeMiddleware(db) {
  // `db` must expose a method `getUserById(id)` returning a Promise<User>
  return async function (req, res, next) {
    // If user already authenticated, skip
    if (req.user) return next();

    // Ensure cookie‑parser middleware ran before this
    const signedCookie = req.signedCookies && req.signedCookies[COOKIE_NAME];
    if (!signedCookie) return next();

    const { userId } = signedCookie;

    try {
      const user = await db.getUserById(userId);
      if (user) {
        req.user = user;               // attach user to request
        // Optionally refresh the cookie expiration on each hit
        issueRememberMe(res, userId);
      }
    } catch (err) {
      // If DB lookup fails, just ignore and continue unauthenticated
      console.error('Remember‑me lookup error:', err);
    }
    next();
  };
}

// -------------------------------------------------------------------
// Export helpers for use in your app
module.exports = {
  issueRememberMe,
  rememberMeMiddleware,
  cookieParser: cookieParser(COOKIE_SECRET), // export configured parser
};
```

Below is a **self‑contained example** that shows:

1. **How to generate a one‑time‑display API key** for a customer, store a **hashed version** in a PostgreSQL table (`api_keys`), and return the plain key only once.
2. **How to verify** a presented API key by hashing it the same way and checking the hash against the stored rows.

The code uses the official **`pg`** driver and Node’s built‑in **`crypto`** module.  
Feel free to copy‑paste it into a file (e.g. `apiKeyService.js`) and adapt the connection details, table schema, or error handling to your project.

