## 2️⃣ Node.js implementation (uses `pg`)

```js
// apiKeyService.js
const { Pool } = require('pg');
const crypto = require('crypto');

// -----------------------------------------------------
// 1️⃣ Configure the PostgreSQL connection pool
// -----------------------------------------------------
const pool = new Pool({
  // You can also use a DATABASE_URL env var or any other pg Pool options
  user:     process.env.PGUSER,
  host:     process.env.PGHOST,
  database: process.env.PGDATABASE,
  password: process.env.PGPASSWORD,
  port:     process.env.PGPORT ? Number(process.env.PGPORT) : 5432,
  // optional: ssl: { rejectUnauthorized: false } // for cloud providers
});

// -----------------------------------------------------
// 2️⃣ Helper: create a random API key (plain text)
// -----------------------------------------------------
/**
 * Generates a random, URL‑safe API key.
 * Length: 32 bytes → 43‑character Base64URL string.
 *
 * @returns {string} plain API key
 */
function generatePlainKey() {
  // 32 random bytes = 256 bits of entropy (more than enough for an API key)
  const buffer = crypto.randomBytes(32);
  // Base64URL (replace +/ with -_ and strip = padding)
  return buffer.toString('base64')
               .replace(/\+/g, '-')
               .replace(/\//g, '_')
               .replace(/=+$/g, '');
}

// -----------------------------------------------------
// 3️⃣ Helper: hash a key with a per‑key random salt
// -----------------------------------------------------
/**
 * Returns a string that contains both the salt and the hash.
 * Format: `${saltHex}:${hashHex}`
 *
 * @param {string} plainKey
 * @returns {string} salted hash
 */
function hashKey(plainKey) {
  const salt = crypto.randomBytes(16); // 128‑bit salt
  const hash = crypto.createHash('sha256')
                     .update(salt)
                     .update(plainKey)
                     .digest();
  return `${salt.toString('hex')}:${hash.toString('hex')}`;
}

/**
 * Re‑creates the hash for a presented key using the stored salt.
 *
 * @param {string} plainKey
 * @param {string} storedHash   // format `${saltHex}:${hashHex}`
 * @returns {boolean}
 */
function verifyHash(plainKey, storedHash) {
  const [saltHex, hashHex] = storedHash.split(':');
  if (!saltHex || !hashHex) return false;
  const salt = Buffer.from(saltHex, 'hex');
  const expectedHash = Buffer.from(hashHex, 'hex');

  const actualHash = crypto.createHash('sha256')
                           .update(salt)
                           .update(plainKey)
                           .digest();

  // Use timing‑safe comparison
  return crypto.timingSafeEqual(actualHash, expectedHash);
}

// -----------------------------------------------------
// 4️⃣ Public API: generate a new key for a customer
// -----------------------------------------------------
/**
 * Generates a new API key for the given customer, stores only the hash,
 * and returns the plain key **once**.
 *
 * @param {number|string} customerId   // whatever type you use for customers
 * @returns {Promise<string>} the plain API key that you can show to the user
 */
async function createApiKeyForCustomer(customerId) {
  const plainKey = generatePlainKey();
  const storedHash = hashKey(plainKey);

  const client = await pool.connect();
  try {
    await client.query('BEGIN');

    const insertText = `
      INSERT INTO api_keys (customer_id, key_hash)
      VALUES ($1, $2)
      RETURNING id, created_at
    `;
    const res = await client.query(insertText, [customerId, storedHash]);

    await client.query('COMMIT');

    // You could also return the inserted row id if you need it
    return plainKey; // **only ever show this once!**
  } catch (err) {
    await client.query('ROLLBACK');
    console.error('Error inserting API key:', err);
    throw err;
  } finally {
    client.release();
  }
}

// -----------------------------------------------------
// 5️⃣ Public API: validate a presented key
// -----------------------------------------------------
/**
 * Checks whether a supplied API key belongs to an active (not revoked) row.
 *
 * @param {string} presentedKey   // the key the client sent in a header, query, etc.
 * @returns {Promise<{valid: boolean, customerId?: number, keyId?: number}>}
 */
async function validateApiKey(presentedKey) {
  const client = await pool.connect();
  try {
    const selectText = `
      SELECT id, customer_id, key_hash
      FROM api_keys
      WHERE revoked_at IS NULL
    `;
    const { rows } = await client.query(selectText);

    // Linear scan – for a production system with many keys you would
    // store the hash in a separate indexed column (e.g., `hash_only`)
    // and query `WHERE key_hash = $1`. Because we use a per‑key salt,
    // we cannot compute the hash in SQL, so we have to fetch all rows
    // (or store a secondary deterministic hash like HMAC‑SHA256 with a
    // server‑wide secret). The simple approach below works fine for a
    // modest number of keys.
    for (const row of rows) {
      if (verifyHash(presentedKey, row.key_hash)) {
        return { valid: true, customerId: row.customer_id, keyId: row.id };
      }
    }

    return { valid: false };
  } catch (err) {
    console.error('Error validating API key:', err);
    throw err;
  } finally {
    client.release();
  }
}

// -----------------------------------------------------
// 6️⃣ Optional helper: revoke a key
// -----------------------------------------------------
/**
 * Marks a key as revoked so it can no longer be used.
 *
 * @param {number} keyId   // primary key of the row in api_keys
 * @returns {Promise<void>}
 */
async function revokeApiKey(keyId) {
  await pool.query(
    `UPDATE api_keys SET revoked_at = now() WHERE id = $1`,
    [keyId]
  );
}

// -----------------------------------------------------
// 7️⃣ Export the functions you need elsewhere
// -----------------------------------------------------
module.exports = {
  createApiKeyForCustomer,
  validateApiKey,
  revokeApiKey,
  // (the helpers are not exported on purpose – keep them internal)
};
```

