## 2️⃣ Node.js module (`apiKeyService.js`)

```js
/**
 * apiKeyService.js
 *
 * Functions:
 *   - generateApiKey(customerId) → Promise<string>
 *   - verifyApiKey(presentedKey) → Promise<{ valid: boolean, customerId?: number }>
 *
 * Uses:
 *   - pg  (npm i pg)
 *   - crypto (built‑in)
 *
 * Environment variables (example):
 *   PGHOST, PGPORT, PGDATABASE, PGUSER, PGPASSWORD
 */

const { Pool } = require('pg');
const crypto = require('crypto');

// ---------------------------------------------------
// 1️⃣  PostgreSQL connection pool
// ---------------------------------------------------
const pool = new Pool({
  // pg will read connection details from the environment variables
  // (PGHOST, PGPORT, PGDATABASE, PGUSER, PGPASSWORD, etc.)
  // You can also pass them explicitly here if you prefer.
});

// ---------------------------------------------------
// 2️⃣  Helper: hash the raw API key (SHA‑256)
// ---------------------------------------------------
/**
 * Returns a Buffer containing the SHA‑256 hash of the key.
 * Using a simple hash is fine for API keys because the key itself is
 * already a high‑entropy random secret. If you want extra hardening you
 * could use HMAC‑SHA256 with a server‑side pepper.
 *
 * @param {string} rawKey
 * @returns {Buffer}
 */
function hashKey(rawKey) {
  return crypto.createHash('sha256').update(rawKey).digest(); // 32‑byte Buffer
}

// ---------------------------------------------------
// 3️⃣  generateApiKey(customerId)
// ---------------------------------------------------
/**
 * Generates a new API key for a given customer, stores its hash,
 * and returns the plain key (once) so you can display it to the user.
 *
 * @param {number|string} customerId   – the identifier of the customer
 * @param {object} [options]          – optional overrides
 * @param {number} [options.byteLength=32] – length of random bytes (default 32 → 64‑char hex)
 * @returns {Promise<string>} plain API key
 */
async function generateApiKey(customerId, options = {}) {
  const byteLength = options.byteLength ?? 32; // 256‑bit entropy

  // 1️⃣  Create a cryptographically‑secure random key
  const rawKey = crypto.randomBytes(byteLength).toString('hex'); // e.g. 64‑char hex

  // 2️⃣  Hash it before persisting
  const keyHash = hashKey(rawKey); // Buffer

  // 3️⃣  Insert into DB
  const client = await pool.connect();
  try {
    const insertQuery = `
      INSERT INTO api_keys (customer_id, key_hash)
      VALUES ($1, $2)
      RETURNING id, created_at
    `;
    const values = [customerId, keyHash];
    await client.query(insertQuery, values);
  } finally {
    client.release();
  }

  // 4️⃣  Return the **plain** key – this is the only time the server knows it!
  return rawKey;
}

// ---------------------------------------------------
// 4️⃣  verifyApiKey(presentedKey)
// ---------------------------------------------------
/**
 * Checks whether a presented API key exists (and is not revoked).
 *
 * @param {string} presentedKey – the raw key supplied by the caller (e.g. in an Authorization header)
 * @returns {Promise<{ valid: boolean, customerId?: number, error?: string }>}
 */
async function verifyApiKey(presentedKey) {
  const keyHash = hashKey(presentedKey); // Buffer

  const client = await pool.connect();
  try {
    const selectQuery = `
      SELECT customer_id
      FROM api_keys
      WHERE key_hash = $1
        AND revoked_at IS NULL
      LIMIT 1
    `;
    const { rows } = await client.query(selectQuery, [keyHash]);

    if (rows.length === 0) {
      return { valid: false };
    }

    const customerId = rows[0].customer_id;

    // OPTIONAL: update last_used_at for audit / rate‑limit
    const updateQuery = `
      UPDATE api_keys
      SET last_used_at = now()
      WHERE key_hash = $1
    `;
    await client.query(updateQuery, [keyHash]);

    return { valid: true, customerId };
  } catch (err) {
    // In production you may want to log the error and return a generic failure
    console.error('Error verifying API key:', err);
    return { valid: false, error: 'internal_error' };
  } finally {
    client.release();
  }
}

// ---------------------------------------------------
// 5️⃣  Export the two functions (and optionally the pool)
// ---------------------------------------------------
module.exports = {
  generateApiKey,
  verifyApiKey,
  // Exporting the pool can be handy for other queries in the same service
  pool,
};
```

