// apiKeyService.js
// Node.js service for generating and verifying API keys using PostgreSQL (pg)

const crypto = require('crypto');
const { Pool } = require('pg');

// Configure the PostgreSQL connection pool
const pool = new Pool({
  connectionString: process.env.DATABASE_URL, // e.g. postgres://user:pw@host/db
  // ssl: { rejectUnauthorized: false }, // uncomment for Heroku etc.
});

/**
 * Generate a new API key for a given customer.
 * Stores a hash of the key in the `api_keys` table and returns the plain key once.
 *
 * @param {string|number} customerId - Identifier of the customer.
 * @returns {Promise<string>} The newly generated API key (plain text).
 */
async function generateApiKey(customerId) {
  // 32‑byte (256‑bit) random value, encoded URL‑safe base64 (43 chars)
  const plainKey = crypto.randomBytes(32).toString('base64url');

  // Store only a SHA‑256 hash of the key for security
  const keyHash = crypto.createHash('sha256').update(plainKey).digest('hex');

  const query = `
    INSERT INTO api_keys (customer_id, key_hash, created_at)
    VALUES ($1, $2, NOW())
    RETURNING id
  `;

  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    await client.query(query, [customerId, keyHash]);
    await client.query('COMMIT');
    return plainKey; // show this once to the customer
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release();
  }
}

/**
 * Verify a presented API key.
 *
 * @param {string} presentedKey - The API key supplied by a client.
 * @returns {Promise<boolean>} True if the key exists and is valid.
 */
async function verifyApiKey(presentedKey) {
  const keyHash = crypto.createHash('sha256').update(presentedKey).digest('hex');

  const query = `
    SELECT 1 FROM api_keys
    WHERE key_hash = $1
    LIMIT 1
  `;

  const { rows } = await pool.query(query, [keyHash]);
  return rows.length > 0;
}

/**
 * OPTIONAL: Retrieve the customer ID associated with a valid API key.
 *
 * @param {string} presentedKey
 * @returns {Promise<string|null>} Customer ID or null if key invalid.
 */
async function getCustomerIdByKey(presentedKey) {
  const keyHash = crypto.createHash('sha256').update(presentedKey).digest('hex');

  const query = `
    SELECT customer_id FROM api_keys
    WHERE key_hash = $1
    LIMIT 1
  `;

  const { rows } = await pool.query(query, [keyHash]);
  return rows[0]?.customer_id ?? null;
}

// Export functions for use elsewhere
module.exports = {
  generateApiKey,
  verifyApiKey,
  getCustomerIdByKey,
};
