## 2️⃣  Node.js implementation

```js
// ---------------------------------------------------------------
// apiKeyService.js
// ---------------------------------------------------------------

import { Pool } from 'pg';
import { randomBytes, createHash, timingSafeEqual } from 'crypto';

// ---------------------------------------------------------------
// 1️⃣  PostgreSQL connection pool
// ---------------------------------------------------------------
const pool = new Pool({
  // 👉 Replace these values with your own connection details
  user:     process.env.PGUSER     || 'postgres',
  host:     process.env.PGHOST     || 'localhost',
  database: process.env.PGDATABASE || 'mydb',
  password: process.env.PGPASSWORD || 'secret',
  port:     Number(process.env.PGPORT) || 5432,
  // optional: ssl, connection timeout, etc.
});

// ---------------------------------------------------------------
// 2️⃣  Helper: hash a raw API key
// ---------------------------------------------------------------
/**
 * Returns a hex‑encoded SHA‑256 hash of the supplied key.
 * Using SHA‑256 is fast and sufficient for a secret that is
 * already high‑entropy (generated with crypto.randomBytes).
 *
 * @param {string} rawKey - The plain API key (as shown to the customer)
 * @returns {string} Hex‑encoded hash
 */
function hashKey(rawKey) {
  return createHash('sha256').update(rawKey).digest('hex');
}

// ---------------------------------------------------------------
// 3️⃣  Generate a new API key for a given customer
// ---------------------------------------------------------------
/**
 * Generates a one‑time API key, stores its hash, and returns the raw key.
 *
 * @param {number|string} customerId - Identifier of the customer (FK to your customers table)
 * @param {object} [options] - Optional settings
 * @param {number} [options.byteLength=32] - Length of the random key in bytes (default = 32 → 256‑bit)
 * @returns {Promise<string>} The raw API key that you should show to the customer once
 *
 * @throws Will throw if the INSERT fails (e.g., DB down)
 */
export async function generateApiKey(customerId, options = {}) {
  const { byteLength = 32 } = options;

  // 1️⃣  Create a high‑entropy random value
  const rawKey = randomBytes(byteLength).toString('base64url'); // URL‑safe, no padding

  // 2️⃣  Hash it before storage
  const keyHash = hashKey(rawKey);

  // 3️⃣  Insert the hash into the DB
  const client = await pool.connect();
  try {
    const insertQuery = `
      INSERT INTO api_keys (customer_id, key_hash)
      VALUES ($1, $2)
      RETURNING id, created_at;
    `;
    const { rows } = await client.query(insertQuery, [customerId, keyHash]);

    // rows[0] contains the newly‑created row info (id, created_at, …)
    console.log(`✅  API key generated for customer ${customerId} (row id ${rows[0].id})`);
    return rawKey; // <-- this is the only time the raw key is ever known
  } finally {
    client.release();
  }
}

// ---------------------------------------------------------------
// 4️⃣  Verify a presented API key
// ---------------------------------------------------------------
/**
 * Checks whether a supplied API key exists (and is not revoked) in the DB.
 *
 * @param {string} presentedKey - The API key the client sent (e.g., in an Authorization header)
 * @returns {Promise<{ valid: boolean, customerId?: number, keyId?: number }>}
 *          `valid` is true when the key matches a non‑revoked row.
 *          When valid, the row’s `customer_id` and primary‑key `id` are also returned.
 */
export async function verifyApiKey(presentedKey) {
  const presentedHash = hashKey(presentedKey);

  const client = await pool.connect();
  try {
    const selectQuery = `
      SELECT id, customer_id, key_hash
      FROM api_keys
      WHERE key_hash = $1
        AND revoked_at IS NULL
      LIMIT 1;
    `;
    const { rows } = await client.query(selectQuery, [presentedHash]);

    if (rows.length === 0) {
      // No matching (or it’s revoked)
      return { valid: false };
    }

    // Even though we already matched on the hash, we do a constant‑time compare
    // to protect against any exotic timing attacks on the DB driver.
    const storedHashBuffer = Buffer.from(rows[0].key_hash, 'hex');
    const presentedHashBuffer = Buffer.from(presentedHash, 'hex');

    const hashesMatch = timingSafeEqual(storedHashBuffer, presentedHashBuffer);

    if (!hashesMatch) {
      // Should never happen because the DB query filtered on the same hash,
      // but we keep the check for completeness.
      return { valid: false };
    }

    return {
      valid: true,
      customerId: rows[0].customer_id,
      keyId: rows[0].id,
    };
  } finally {
    client.release();
  }
}

// ---------------------------------------------------------------
// 5️⃣  Optional: revoke a key (e.g., when a customer cancels)
// ---------------------------------------------------------------
/**
 * Marks an API key as revoked.
 *
 * @param {number} keyId - Primary‑key `id` from the api_keys table
 * @returns {Promise<boolean>} `true` if a row was updated, `false` otherwise
 */
export async function revokeApiKey(keyId) {
  const client = await pool.connect();
  try {
    const result = await client.query(
      `UPDATE api_keys SET revoked_at = now() WHERE id = $1 AND revoked_at IS NULL`,
      [keyId]
    );
    return result.rowCount === 1;
  } finally {
    client.release();
  }
}

// ---------------------------------------------------------------
// 6️⃣  Graceful shutdown helper (useful for serverless / CLI)
// ---------------------------------------------------------------
export async function shutdown() {
  await pool.end();
}
```

