## 1️⃣  Table definition (PostgreSQL)

```sql
-- Run this once (or add it to your migration system)
CREATE TABLE IF NOT EXISTS api_keys (
    id           BIGSERIAL PRIMARY KEY,
    customer_id  UUID NOT NULL,               -- or whatever type you use for customers
    key_hash     TEXT NOT NULL,               -- bcrypt hash of the key
    created_at   TIMESTAMP WITH TIME ZONE DEFAULT now(),
    revoked_at   TIMESTAMP WITH TIME ZONE NULL,
    description  TEXT NULL                    -- optional free‑form note
);

-- An index that makes look‑ups fast (only non‑revoked keys)
CREATE INDEX IF NOT EXISTS idx_api_keys_hash_active
    ON api_keys (key_hash)
    WHERE revoked_at IS NULL;
```

*Why store a **hash**?*  
If your database ever gets compromised, the attacker will only see the one‑way hash, not the usable secret. `bcrypt` is deliberately slow, which makes brute‑forcing a stolen hash much harder than a plain SHA‑256 hash.

---

## 2️⃣  Node.js implementation

> **Prerequisites**  
> ```bash
> npm i pg bcrypt
> ```
> (Node ≥ 14 is fine; the example uses native ES‑modules – you can switch to CommonJS if you prefer.)

```js
// file: apiKeyService.mjs
import { Pool } from 'pg';
import crypto from 'crypto';
import bcrypt from 'bcrypt';

// ---------------------------------------------------------------------
// 1️⃣  PG connection pool – configure via environment variables
// ---------------------------------------------------------------------
const pool = new Pool({
  connectionString: process.env.DATABASE_URL, // e.g. postgres://user:pw@host/db
  // optional: max, idleTimeoutMillis, etc.
});

// ---------------------------------------------------------------------
// 2️⃣  Helper: generate a cryptographically‑random key string
// ---------------------------------------------------------------------
/**
 * Returns a base64‑url‑safe string (e.g. 32‑byte => 43 characters)
 * You can change the length if you want longer/shorter keys.
 */
function makePlainKey(byteLength = 32) {
  const raw = crypto.randomBytes(byteLength);
  // base64url: replace +/ with -_ and strip trailing '='
  return raw.toString('base64')
            .replace(/\+/g, '-')
            .replace(/\//g, '_')
            .replace(/=+$/g, '');
}

// ---------------------------------------------------------------------
// 3️⃣  Generate & store a new API key for a customer
// ---------------------------------------------------------------------
/**
 * @param {string|number} customerId   – whatever identifier you use for customers
 * @param {Object} [options]
 * @param {string}   [options.description] – optional note stored with the key
 * @returns {Promise<string>} the **plain‑text** API key (show it once!)
 */
export async function generateApiKey(customerId, options = {}) {
  const plainKey = makePlainKey();               // 1️⃣ generate random secret
  const saltRounds = 12;                         // bcrypt cost factor (adjust as needed)
  const hash = await bcrypt.hash(plainKey, saltRounds); // 2️⃣ hash it

  const client = await pool.connect();
  try {
    const query = `
      INSERT INTO api_keys (customer_id, key_hash, description)
      VALUES ($1, $2, $3)
      RETURNING id, created_at;
    `;
    const values = [customerId, hash, options.description || null];
    await client.query(query, values);
  } finally {
    client.release();
  }

  // Return the *only* time we ever expose the raw key
  return plainKey;
}

// ---------------------------------------------------------------------
// 4️⃣  Validate a presented API key
// ---------------------------------------------------------------------
/**
 * @param {string} presentedKey   – the key supplied by the client (e.g. in a header)
 * @returns {Promise<{ valid: boolean, customerId?: string, keyId?: number }>}
 */
export async function checkApiKey(presentedKey) {
  // 1️⃣ Pull *all* active hashes – we could also add a dedicated lookup table
  //    if you want to avoid scanning many rows. For modest volumes this is fine.
  const client = await pool.connect();
  try {
    const query = `
      SELECT id, customer_id, key_hash
      FROM api_keys
      WHERE revoked_at IS NULL;
    `;
    const { rows } = await client.query(query);

    // 2️⃣ Test the presented key against each hash (bcrypt is safe to compare)
    for (const row of rows) {
      const match = await bcrypt.compare(presentedKey, row.key_hash);
      if (match) {
        return { valid: true, customerId: row.customer_id, keyId: row.id };
      }
    }

    // No match found
    return { valid: false };
  } finally {
    client.release();
  }
}

// ---------------------------------------------------------------------
// 5️⃣  Optional: revoke a key (soft‑delete)
// ---------------------------------------------------------------------
/**
 * @param {number} keyId
 * @returns {Promise<void>}
 */
export async function revokeApiKey(keyId) {
  const client = await pool.connect();
  try {
    const query = `
      UPDATE api_keys
      SET revoked_at = now()
      WHERE id = $1 AND revoked_at IS NULL;
    `;
    await client.query(query, [keyId]);
  } finally {
    client.release();
  }
}

// ---------------------------------------------------------------------
// 6️⃣  Graceful shutdown helper (if you run this in a server)
// ---------------------------------------------------------------------
export async function closePool() {
  await pool.end();
}
```

