  (async () => {
    const custId = '3fa85f64-5717-4562-b3fc-2c963f66afa6';
    const key = await generateApiKey(custId, { description: 'demo key' });
    console.log('Generated key (show once):', key);

    const check1 = await checkApiKey(key);
    console.log('Check 1 →', check1);

    await revokeApiKey(check1.keyId);
    const check2 = await checkApiKey(key);
    console.log('Check after revocation →', check2);

    await closePool();
  })().catch(e => {
    console.error(e);
    process.exit(1);
  });
}
