## 1️⃣ Table definition (PostgreSQL)

```sql
-- Run this once (or adapt it to your existing schema)
CREATE EXTENSION IF NOT EXISTS "pgcrypto";   -- needed for gen_random_bytes

CREATE TABLE IF NOT EXISTS api_keys (
    id            BIGSERIAL PRIMARY KEY,
    customer_id   BIGINT NOT NULL,               -- FK to your customers table (optional)
    key_hash      BYTEA NOT NULL,                -- bcrypt/argon2/sha256 hash of the key
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    last_used_at  TIMESTAMPTZ,
    revoked_at    TIMESTAMPTZ,
    CONSTRAINT uq_customer_active_key UNIQUE (customer_id, revoked_at)   -- optional: one active key per customer
);
```

*You can replace `BYTEA` with `TEXT` if you prefer storing the hash as a base‑64 string; the code below works with either.*

---

## 2️⃣ Node.js implementation (using **pg** and **crypto**)

> **Prerequisites**  
> ```bash
> npm i pg bcrypt   # bcrypt is used for a strong, salted hash (you could also use argon2)
> ```

```js
// apiKeyService.js
'use strict';

const { Pool } = require('pg');
const crypto = require('crypto');
const bcrypt = require('bcrypt');   // bcrypt v5+ supports async/await

// ---------------------------------------------------------------------
// 1️⃣  PG pool – configure with your connection details (env vars are typical)
const pool = new Pool({
  connectionString: process.env.DATABASE_URL, // e.g. postgres://user:pw@host/db
  // ssl: { rejectUnauthorized: false } // uncomment for Heroku, Render, etc.
});

// ---------------------------------------------------------------------
// 2️⃣  Helper – generate a random, URL‑safe API key
function createRawKey(byteLength = 32) {
  // 32 bytes => 256 bits of entropy → 43‑44 base64url chars
  const raw = crypto.randomBytes(byteLength);
  // Convert to URL‑safe base64 (replace +/ with -_ and strip padding)
  return raw.toString('base64')
            .replace(/\+/g, '-')
            .replace(/\//g, '_')
            .replace(/=+$/g, '');
}

// ---------------------------------------------------------------------
// 3️⃣  Generate a new key for a customer
/**
 * @param {number|string} customerId   Identifier of the customer (FK)
 * @returns {Promise<string>}          The **plain** API key (show it once!)
 */
async function generateApiKey(customerId) {
  const client = await pool.connect();
  try {
    // 1️⃣ Create the raw key that we will give to the caller
    const rawKey = createRawKey();          // e.g. "fJ3-..." (≈44 chars)

    // 2️⃣ Hash it before persisting (bcrypt automatically salts)
    const saltRounds = 12;                  // adjust: higher = slower but more secure
    const hash = await bcrypt.hash(rawKey, saltRounds); // string hash

    // 3️⃣ Store the hash (and optionally the customer id) in the DB
    const insertSQL = `
      INSERT INTO api_keys (customer_id, key_hash)
      VALUES ($1, $2)
      RETURNING id, created_at
    `;
    const { rows } = await client.query(insertSQL, [customerId, hash]);

    // 4️⃣ Return the plain key – **never store or log it again**
    return rawKey;
  } finally {
    client.release();
  }
}

// ---------------------------------------------------------------------
// 4️⃣  Verify a presented key
/**
 * @param {string} presentedKey   The key supplied by the caller (e.g. in a header)
 * @returns {Promise<{valid: boolean, keyId?: number, customerId?: number}>}
 */
async function verifyApiKey(presentedKey) {
  const client = await pool.connect();
  try {
    // Grab all *non‑revoked* keys – we compare each hash with bcrypt.compare()
    // (bcrypt is deliberately slow, but the number of rows should be small;
    //   you can add an index on (revoked_at) and/or store a short prefix for fast lookup)
    const sql = `
      SELECT id, customer_id, key_hash
      FROM api_keys
      WHERE revoked_at IS NULL
    `;
    const { rows } = await client.query(sql);

    // Iterate until we find a match
    for (const row of rows) {
      const match = await bcrypt.compare(presentedKey, row.key_hash);
      if (match) {
        // Optional: update last_used_at (fire‑and‑forget)
        client.query(
          `UPDATE api_keys SET last_used_at = now() WHERE id = $1`,
          [row.id]
        ).catch(() => {}); // ignore errors – not critical for auth

        return { valid: true, keyId: row.id, customerId: row.customer_id };
      }
    }

    // No match found
    return { valid: false };
  } finally {
    client.release();
  }
}

// ---------------------------------------------------------------------
// 5️⃣  Helper – revoke a key (optional)
async function revokeApiKey(keyId) {
  const client = await pool.connect();
  try {
    const sql = `UPDATE api_keys SET revoked_at = now() WHERE id = $1`;
    await client.query(sql, [keyId]);
  } finally {
    client.release();
  }
}

// ---------------------------------------------------------------------
// Export the public API
module.exports = {
  generateApiKey,
  verifyApiKey,
  revokeApiKey,
  // expose the pool if you need it elsewhere (e.g. migrations)
  pool,
};
```

### How it works

| Step | What happens |
|------|--------------|
| **Generate** | `createRawKey()` → 256‑bit random string → `bcrypt.hash()` → INSERT hash into `api_keys`. Only the **plain** key is returned once. |
| **Verify** | Pull all *active* rows, `bcrypt.compare(presentedKey, storedHash)` for each. If a match is found we know the key is valid and we can optionally record `last_used_at`. |
| **Revoke** | Set `revoked_at` – future `verifyApiKey` calls will ignore it. |

> **Performance tip** – If you expect **many** keys, store a short, deterministic prefix (e.g. first 8 characters of a SHA‑256 of the raw key) in a separate column and index it. Then you can filter on that prefix before doing the expensive bcrypt compare.

