// apiKeyService.js
// Node.js service for generating and validating API keys using PostgreSQL (pg)

const { Pool } = require('pg');
const crypto = require('crypto');
const bcrypt = require('bcrypt'); // for hashing stored keys

// ---- PostgreSQL connection pool ----
const pool = new Pool({
  connectionString: process.env.DATABASE_URL, // e.g. postgres://user:pw@host/db
  // ssl: { rejectUnauthorized: false } // uncomment for Heroku etc.
});

// ---- Helper: generate a random URL‑safe string ----
function createRawKey(length = 32) {
  return crypto.randomBytes(length).toString('base64url'); // 43‑char string
}

// ---- Generate a new API key for a customer -------------------------
/**
 * @param {string|number} customerId - Identifier of the customer
 * @returns {Promise<string>} - The raw API key (shown to the customer once)
 */
async function generateApiKey(customerId) {
  const rawKey = createRawKey();               // plaintext key to give to the user
  const hash = await bcrypt.hash(rawKey, 12); // store a salted hash

  const query = `
    INSERT INTO api_keys (customer_id, key_hash, created_at, revoked)
    VALUES ($1, $2, NOW(), FALSE)
    RETURNING id;
  `;

  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    await client.query(query, [customerId, hash]);
    await client.query('COMMIT');
    return rawKey;
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release();
  }
}

// ---- Validate a presented API key ------------------------------------
/**
 * @param {string} presentedKey - The API key supplied by the caller
 * @returns {Promise<{valid: boolean, customerId?: string|number}>}
 */
async function checkApiKey(presentedKey) {
  const query = `
    SELECT id, customer_id, key_hash
    FROM api_keys
    WHERE revoked = FALSE;
  `;

  const { rows } = await pool.query(query);
  for (const row of rows) {
    const match = await bcrypt.compare(presentedKey, row.key_hash);
    if (match) {
      return { valid: true, customerId: row.customer_id };
    }
  }
  return { valid: false };
}

// ---- Optional: revoke a key -------------------------------------------
/**
 * @param {string} keyId - Primary key of the api_keys row to revoke
 * @returns {Promise<void>}
 */
async function revokeApiKey(keyId) {
  const q = `UPDATE api_keys SET revoked = TRUE, revoked_at = NOW() WHERE id = $1;`;
  await pool.query(q, [keyId]);
}

// Export functions
module.exports = {
  generateApiKey,
  checkApiKey,
  revokeApiKey,
};
