  connectionString: process.env.DATABASE_URL, // e.g. postgres://user:pw@host/db
  // or use individual params: user, host, database, password, port
});

// -----------------------------------------------------
// Helper: hash a raw key before storing it.
// -----------------------------------------------------
function hashKey(rawKey) {
  // SHA‑256 is fast and sufficient for API‑key look‑ups.
  return crypto.createHash('sha256').update(rawKey).digest('hex');
