      VALUES ($1, $2, NOW())
    `;
    await client.query(insertText, [customerId, hashed]);
    await client.query('COMMIT');
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release();
  }

  return rawKey; // give the plain key to the customer once
