async function generateApiKey(customerId) {
  // Create a cryptographically‑secure random key (e.g., 32‑byte hex string)
  const apiKey = crypto.randomBytes(32).toString('hex');

  // Store a hash of the key in the database (never store the plain key)
  const hash = crypto.createHash('sha256').update(apiKey).digest('hex');

  const query = `
    INSERT INTO api_keys (customer_id, key_hash, created_at, revoked)
    VALUES ($1, $2, NOW(), FALSE)
    RETURNING id;
  `;

  await pool.query(query, [customerId, hash]);

  // Return the plain key once so the customer can record it
  return apiKey;
}

