Below is a **self‑contained, reusable** PHP function that does exactly what you asked for.  
It:

* reads `page`, `sort` and an optional `q` (search term) from `$_GET`  
* validates the page number and the sort column (so no one can inject arbitrary SQL)  
* builds a safe, parameterised query with **mysqli prepared statements**  
* applies pagination (`LIMIT … OFFSET …`)  
* returns the fetched rows as a plain PHP array (or an empty array on error)

```php
<?php
/**
 * Get a list of products for a product‑listing page.
 *
 * Expected GET parameters:
 *   - page : integer (defaults to 1)
 *   - sort : string  (allowed values: id, name, price, created_at)
 *   - q    : string  (optional search term, matches product name or description)
 *
 * @param mysqli $mysqli   An already‑connected mysqli instance.
 * @return array           List of product rows (associative arrays). Empty on error.
 */
function getProductList(mysqli $mysqli): array
{
    /* -------------------------------------------------
     * 1️⃣  Read & sanitise the incoming GET parameters
     * ------------------------------------------------- */
    // Page number – must be a positive integer, default to 1
    $page = isset($_GET['page']) && ctype_digit($_GET['page']) && (int)$_GET['page'] > 0
        ? (int)$_GET['page']
        : 1;

    // Sort field – whitelist to avoid injection
    $allowedSort = ['id', 'name', 'price', 'created_at'];
    $sort = isset($_GET['sort']) && in_array($_GET['sort'], $allowedSort, true)
        ? $_GET['sort']
        : 'id';                     // default sort

    // Optional search term – trim whitespace, allow empty string
    $search = isset($_GET['q']) ? trim($_GET['q']) : '';

    // Pagination constants
    $pageSize = 20;                  // rows per page (adjust as needed)
    $offset   = ($page - 1) * $pageSize;

    /* -------------------------------------------------
     * 2️⃣  Build the SQL – using placeholders only for data
     * ------------------------------------------------- */
    $sql = "SELECT id, name, description, price, created_at
            FROM products ";

    $params = [];      // values that will be bound
    $types  = '';      // corresponding type string for bind_param()

    // Add a WHERE clause only when a search term is supplied
    if ($search !== '') {
        $sql .= "WHERE (name LIKE ? OR description LIKE ?) ";
        $searchWildcard = '%' . $search . '%';
        $params[] = $searchWildcard;
        $params[] = $searchWildcard;
        $types  .= 'ss';
    }

    // Add ORDER BY – the column name is safe because we whitelisted it
    $sql .= "ORDER BY {$sort} ASC ";

    // Finally add LIMIT / OFFSET
    $sql .= "LIMIT ? OFFSET ?";

    $params[] = $pageSize;
    $params[] = $offset;
    $types  .= 'ii';

    /* -------------------------------------------------
     * 3️⃣  Prepare, bind and execute
     * ------------------------------------------------- */
    $stmt = $mysqli->prepare($sql);
    if ($stmt === false) {
        error_log('MySQL prepare failed: ' . $mysqli->error);
        return [];   // caller can decide what to do on empty result
    }

    // Bind parameters dynamically
    if ($params) {
        // mysqli_stmt::bind_param requires references
        $bindNames = [];
        $bindNames[] = $types;
        foreach ($params as $key => $value) {
            $bindNames[] = &$params[$key];
        }
        call_user_func_array([$stmt, 'bind_param'], $bindNames);
    }

    if (!$stmt->execute()) {
        error_log('MySQL execute failed: ' . $stmt->error);
        $stmt->close();
        return [];
    }

    // Fetch results as an associative array
    $result = $stmt->get_result();
    $rows   = $result ? $result->fetch_all(MYSQLI_ASSOC) : [];

    $stmt->close();

    return $rows;
}

/* -------------------------------------------------
 * Example usage
 * ------------------------------------------------- */
$mysqli = new mysqli('localhost', 'db_user', 'db_pass', 'db_name');

if ($mysqli->connect_errno) {
    die('Failed to connect to MySQL: ' . $mysqli->connect_error);
}

$products = getProductList($mysqli);

// Now $products holds an array of rows you can loop over in your template:
foreach ($products as $product) {
    echo '<h3>' . htmlspecialchars($product['name']) . '</h3>';
    echo '<p>' . nl2br(htmlspecialchars($product['description'])) . '</p>';
    echo '<p>Price: $' . number_format($product['price'], 2) . '</p>';
    echo '<hr>';
}
?>
