```php
<?php
/**
 * Fetch a page of products from the database.
 *
 * Expected GET parameters:
 *   - page : (int)   page number, 1‑based. Default = 1.
 *   - sort : (string) column to sort by. Default = 'name'.
 *   - q    : (string) optional search term (matches product name or description).
 *
 * @param mysqli $mysqli   An already‑connected mysqli instance.
 * @param int    $perPage  Number of rows per page (default 20).
 *
 * @return array  List of product rows (associative arrays). Empty array on error.
 */
function getProductList(mysqli $mysqli, int $perPage = 20): array
{
    /* -------------------------------------------------
     * 1️⃣  Read & validate GET parameters
     * ------------------------------------------------- */
    // page – must be a positive integer
    $page = isset($_GET['page']) ? (int)$_GET['page'] : 1;
    if ($page < 1) {
        $page = 1;
    }

    // sort – whitelist of columns we allow to be used for ordering
    $allowedSortColumns = ['name', 'price', 'created_at', 'category_id'];
    $sort = $_GET['sort'] ?? 'name';
    if (!in_array($sort, $allowedSortColumns, true)) {
        $sort = 'name';
    }

    // optional search term
    $search = $_GET['q'] ?? null;
    $hasSearch = is_string($search) && $search !== '';

    // calculate LIMIT & OFFSET for pagination
    $limit  = $perPage;
    $offset = ($page - 1) * $perPage;

    /* -------------------------------------------------
     * 2️⃣  Build the SQL (prepared statement)
     * ------------------------------------------------- */
    $sql = "SELECT *
            FROM products
            WHERE 1=1";                     // dummy condition to simplify appending

    // If a search term is supplied we search in name & description (case‑insensitive)
    if ($hasSearch) {
        $sql .= " AND (name LIKE ? OR description LIKE ?)";
    }

    // Append ORDER BY – column name is safe because we validated it against a whitelist
    $sql .= " ORDER BY `$sort` ASC";

    // Finally add pagination
    $sql .= " LIMIT ? OFFSET ?";

    $stmt = $mysqli->prepare($sql);
    if ($stmt === false) {
        // Log the error in a real app, then return empty set
        error_log('mysqli prepare failed: ' . $mysqli->error);
        return [];
    }

    /* -------------------------------------------------
     * 3️⃣  Bind parameters
     * ------------------------------------------------- */
    // Types string:
    //   s – search term (twice if present)
    //   i – limit, offset (both integers)
    if ($hasSearch) {
        // `%term%` for a LIKE search
        $like = '%' . $search . '%';
        $stmt->bind_param('ssii', $like, $like, $limit, $offset);
    } else {
        $stmt->bind_param('ii', $limit, $offset);
    }

    /* -------------------------------------------------
     * 4️⃣  Execute & fetch results
     * ------------------------------------------------- */
    if (!$stmt->execute()) {
        error_log('mysqli execute failed: ' . $stmt->error);
        $stmt->close();
        return [];
    }

    $result = $stmt->get_result();
    if ($result === false) {
        error_log('mysqli get_result failed: ' . $stmt->error);
        $stmt->close();
        return [];
    }

    $rows = $result->fetch_all(MYSQLI_ASSOC);

    $stmt->close();

    return $rows;
}

