        'price'       => 'price',
        'created_at'  => 'created_at',
        'updated_at'  => 'updated_at',
        // add more columns as needed
    ];

    $sort = $_GET['sort'] ?? 'name';
    $sort = strtolower($sort);
    $orderBy = $allowedSortColumns[$sort] ?? $allowedSortColumns['name']; // fallback

    // --- search term ---------------------------------------------
    $search = $_GET['q'] ?? '';
    $search = trim($search);   // strip surrounding whitespace

    /* --------------------------------------------------------------
       2️⃣  Calculate LIMIT/OFFSET for pagination
       -------------------------------------------------------------- */
    // Clamp per‑page to a reasonable range
    $perPage = max(1, min($perPage, 100));

    $offset = ($page - 1) * $perPage;

    /* --------------------------------------------------------------
       3️⃣  Build the SQL (prepared statement)
       -------------------------------------------------------------- */
    // Base query
    $sql = "
        SELECT
            id,
            name,
            description,
            price,
            created_at,
            updated_at
        FROM products
    ";

    $types = '';          // type string for bind_param()
    $params = [];         // values for bind_param()

    // Add a WHERE clause only when a search term is supplied
    if ($search !== '') {
        $sql .= " WHERE (name LIKE ? OR description LIKE ?)";
        $like = '%' . $search . '%';
        $types .= 'ss';
        $params[] = $like;
        $params[] = $like;
    }

    // Append ORDER BY, LIMIT and OFFSET
    $sql .= " ORDER BY {$orderBy} ASC LIMIT ? OFFSET ?";

    $types .= 'ii';
    $params[] = $perPage;
    $params[] = $offset;

    // --------------------------------------------------------------
    // Prepare & execute
    // --------------------------------------------------------------
    $stmt = $mysqli->prepare($sql);
    if ($stmt === false) {
        // Log the error in a real app – here we just return false
        error_log('MySQL prepare error: ' . $mysqli->error);
        return false;
    }

    // Bind parameters dynamically
    if ($types) {
        // The ...$params syntax "unpacks" the array into separate arguments
        $stmt->bind_param($types, ...$params);
    }

    if (!$stmt->execute()) {
        error_log('MySQL execute error: ' . $stmt->error);
        $stmt->close();
        return false;
    }

    // Fetch all rows as an associative array
    $result = $stmt->get_result();
    $rows   = $result->fetch_all(MYSQLI_ASSOC);

    // Clean up
    $stmt->close();

    return $rows;
}

