    $order = ($order === 'desc') ? 'DESC' : 'ASC';

    // Optional search term
    $search = trim($_GET['search'] ?? '');

    // Calculate LIMIT offset
    $offset = ($page - 1) * $perPage;

    /* -------------------------------------------------
     * 2. Build the SQL with placeholders only for data
     * ------------------------------------------------- */
    $sql = "SELECT *
            FROM products
            WHERE 1";                     // dummy condition makes appending easier

    $params   = [];   // values that will be bound
    $types    = '';   // type string for bind_param()

