    // Append ORDER BY – note that column name and direction are *not* bound,
    // they have been white‑listed above, so they are safe to inject directly.
    $sql .= " ORDER BY {$sort} {$order}";

    // Finally add pagination
    $sql .= " LIMIT ? OFFSET ?";
    $params[] = $perPage;
    $params[] = $offset;
    $types   .= 'ii';

    /* -------------------------------------------------
     * 3. Prepare, bind and execute
     * ------------------------------------------------- */
    $stmt = $mysqli->prepare($sql);
