Below is a self‑contained Node.js helper that creates a thumbnail with **ImageMagick** (`convert`).  
It receives the three values that normally come from a request body (`inputPath`, `outputPath`, `width`) and returns a **Promise** that resolves when the conversion finishes (or rejects on error).

```js
// thumbnail.js
const { spawn } = require('child_process');
const path = require('path');
const fs = require('fs');

/**
 * Creates a thumbnail of an image using ImageMagick's `convert`.
 *
 * @param {string} inputPath   Absolute or relative path to the source image.
 * @param {string} outputPath  Desired path for the thumbnail image.
 * @param {number|string} width Desired width of the thumbnail (height is scaled proportionally).
 *
 * @returns {Promise<void>} Resolves when the thumbnail has been written,
 *                          rejects with an Error if something goes wrong.
 *
 * @example
 * // Express route handler
 * app.post('/thumb', async (req, res) => {
 *   const { inputPath, outputPath, width } = req.body;
 *   try {
 *     await createThumbnail(inputPath, outputPath, width);
 *     res.json({ success: true, thumbnail: outputPath });
 *   } catch (err) {
 *     res.status(500).json({ success: false, message: err.message });
 *   }
 * });
 */
function createThumbnail(inputPath, outputPath, width) {
  return new Promise((resolve, reject) => {
    // -----------------------------------------------------------------
    // 1️⃣  Basic validation / sanitisation
    // -----------------------------------------------------------------
    if (typeof inputPath !== 'string' || typeof outputPath !== 'string') {
      return reject(new Error('inputPath and outputPath must be strings'));
    }

    // Ensure width is a positive integer (ImageMagick will reject non‑numeric values)
    const w = Number(width);
    if (!Number.isInteger(w) || w <= 0) {
      return reject(new Error('width must be a positive integer'));
    }

    // Resolve to absolute paths – helps avoid path‑traversal attacks
    const absIn  = path.resolve(inputPath);
    const absOut = path.resolve(outputPath);

    // Optional: check that the source file actually exists before spawning the process
    fs.access(absIn, fs.constants.R_OK, (err) => {
      if (err) {
        return reject(new Error(`Cannot read input file: ${absIn}`));
      }

      // -----------------------------------------------------------------
      // 2️⃣  Build the ImageMagick command
      // -----------------------------------------------------------------
      //   convert <input> -thumbnail <width> <output>
      //   -thumbnail automatically maintains the aspect ratio.
      const args = [
        absIn,
        '-thumbnail',
        `${w}`,          // width – height is auto‑scaled
        absOut
      ];

      // -----------------------------------------------------------------
      // 3️⃣  Spawn the process
      // -----------------------------------------------------------------
      const proc = spawn('convert', args);

      // Capture any stderr output (ImageMagick writes errors there)
      let stderr = '';
      proc.stderr.on('data', (chunk) => {
        stderr += chunk.toString();
      });

      proc.on('error', (spawnErr) => {
        // This fires if the executable cannot be started (e.g., not installed)
        reject(new Error(`Failed to start ImageMagick: ${spawnErr.message}`));
      });

      proc.on('close', (code) => {
        if (code === 0) {
          // Success – the thumbnail file should now exist.
          resolve();
        } else {
          reject(new Error(`ImageMagick exited with code ${code}: ${stderr.trim()}`));
        }
      });
    });
  });
}

module.exports = { createThumbnail };
```

### How it works

| Step | What happens |
|------|--------------|
| **1️⃣ Validation** | Makes sure the inputs are the right type, that `width` is a positive integer, and that the source file is readable. Converting everything to absolute paths mitigates path‑traversal attacks. |
| **2️⃣ Build command** | Calls `convert <input> -thumbnail <width> <output>`. The `-thumbnail` flag keeps the original aspect ratio while scaling the width to the requested value. |
| **3️⃣ Spawn** | Uses `child_process.spawn` (instead of `exec`) so we don’t hit the 200 KB command‑line length limit and we can stream `stderr` safely. |
| **4️⃣ Resolve / reject** | The returned `Promise` resolves when the process exits with code 0, otherwise it rejects with a helpful error message (including any stderr output from ImageMagick). |

