 *     res.json({ success: true, message: 'Thumbnail created' });
 *   } catch (err) {
 *     res.status(500).json({ success: false, error: err.message });
 *   }
 * });
 */
function createThumbnail(inputPath, outputPath, width) {
  return new Promise((resolve, reject) => {
    // ---- basic validation -------------------------------------------------
    if (!inputPath || typeof inputPath !== 'string')
      return reject(new Error('Invalid inputPath'));
    if (!outputPath || typeof outputPath !== 'string')
      return reject(new Error('Invalid outputPath'));
    const w = Number(width);
    if (!Number.isFinite(w) || w <= 0)
      return reject(new Error('Width must be a positive number'));

    // Ensure the output directory exists (optional but helpful)
    const outDir = path.dirname(outputPath);
    const fs = require('fs');
    if (!fs.existsSync(outDir)) {
