        fs.mkdirSync(outDir, { recursive: true });
      } catch (e) {
        return reject(new Error(`Cannot create output directory: ${e.message}`));
      }
    }

    // ---- Build the ImageMagick command ------------------------------------
    //   convert <input> -thumbnail <width> <output>
    //   The `-thumbnail` flag keeps the aspect ratio.
    const args = [
      inputPath,
      '-thumbnail',
      `${w}`,               // width only – height auto‑scaled
      outputPath,
    ];

    const convert = spawn('convert', args);

    // Capture any stderr output – useful for debugging
    let stderr = '';
    convert.stderr.on('data', (data) => {
      stderr += data.toString();
    });

    convert.on('error', (err) => {
      // This fires if the `convert` binary cannot be started
      reject(new Error(`Failed to start ImageMagick: ${err.message}`));
