    convert.on('close', (code) => {
      if (code === 0) {
        resolve(); // success
      } else {
        reject(
          new Error(
            `ImageMagick exited with code ${code}. ` +
            `Stderr: ${stderr.trim()}`.trim()
          )
        );
      }
    });
  });
}

