**download‑signer.js** – a tiny, dependency‑free Node.js module that can **sign** a download URL and later **verify** it.  
It uses the built‑in `crypto` module and HMAC‑SHA‑256, so the signature is cryptographically strong and resistant to tampering.

```js
/**
 * download-signer.js
 *
 * A small utility for creating signed, time‑limited download URLs.
 *
 *   const { sign, verify, setSecret } = require('./download-signer');
 *
 *   // 1️⃣  Sign a URL
 *   const qs = sign('/files/report.pdf', Date.now() + 10 * 60 * 1000); // 10 min from now
 *   // → "path=%2Ffiles%2Freport.pdf&expires=1728144573000&sig=..."
 *
 *   // 2️⃣  Verify a request (e.g. inside an Express handler)
 *   if (!verify(req.url)) {
 *       res.status(403).send('Invalid or expired link');
 *       return;
 *   }
 *
 * The secret key is required – you can set it once at startup or let the module
 * read it from the environment variable `DOWNLOAD_SIGNER_SECRET`.
 *
 * -------------------------------------------------------------------------
 * SECURITY NOTES
 * -------------------------------------------------------------------------
 * • The secret must be at least 32 random bytes (e.g. `crypto.randomBytes(32)`).
 * • Never expose the secret to the client or store it in source control.
 * • The signature is compared with `crypto.timingSafeEqual` to avoid timing attacks.
 */

const crypto = require('crypto');
const { URLSearchParams } = require('url');

// -------------------------------------------------------------------------
// Configuration
// -------------------------------------------------------------------------

let _secret = process.env.DOWNLOAD_SIGNER_SECRET || null;

/**
 * Set (or replace) the secret used for HMAC signing.
 * @param {string|Buffer} secret - A cryptographically‑random secret.
 */
function setSecret(secret) {
  if (!secret) {
    throw new Error('A non‑empty secret is required');
  }
  _secret = Buffer.isBuffer(secret) ? secret : Buffer.from(secret, 'utf8');
}

/**
 * Retrieve the secret, throwing a helpful error if it hasn't been set.
 * @private
 */
function _getSecret() {
  if (!_secret) {
    throw new Error(
      'Download‑signer secret not configured. Call setSecret(secret) ' +
        'or define the environment variable DOWNLOAD_SIGNER_SECRET.'
    );
  }
  return _secret;
}

// -------------------------------------------------------------------------
// Helper – HMAC generation
// -------------------------------------------------------------------------

/**
 * Compute the HMAC‑SHA‑256 signature for the given data.
 * @param {string} data - The string that will be signed.
 * @returns {string} Hex‑encoded signature.
 * @private
 */
function _signData(data) {
  const hmac = crypto.createHmac('sha256', _getSecret());
  hmac.update(data);
  return hmac.digest('hex');
}

/**
 * Constant‑time comparison of two hex strings.
 * @param {string} a
 * @param {string} b
 * @returns {boolean}
 * @private
 */
function _constantTimeEqual(a, b) {
  // Convert hex strings to Buffers of equal length.
  const bufA = Buffer.from(a, 'hex');
  const bufB = Buffer.from(b, 'hex');

  // If lengths differ, they can't be equal – but we still run the comparison
  // on buffers of the same length to keep timing characteristics uniform.
  if (bufA.length !== bufB.length) {
    // Create a dummy buffer of the same size as the longer one.
    const dummy = Buffer.alloc(Math.max(bufA.length, bufB.length));
    return crypto.timingSafeEqual(dummy, dummy) && false;
  }

  return crypto.timingSafeEqual(bufA, bufB);
}

// -------------------------------------------------------------------------
// Public API – sign
// -------------------------------------------------------------------------

/**
 * Create a signed query string for a download URL.
 *
 * The returned string **does not** contain the leading `?`.  It can be appended
 * to any base URL, e.g.:
 *
 *   const qs = sign('/files/report.pdf', Date.now() + 5 * 60 * 1000);
 *   const url = `https://example.com/download?${qs}`;
 *
 * @param {string} path        - The path that will be served (e.g. "/files/foo.pdf").
 * @param {number|Date} expiresAt - Expiration moment (timestamp in ms or a Date).
 * @returns {string} URL‑encoded query string: `path=…&expires=…&sig=…`
 */
function sign(path, expiresAt) {
  if (typeof path !== 'string' || path.length === 0) {
    throw new Error('path must be a non‑empty string');
  }

  const expires =
    expiresAt instanceof Date ? expiresAt.getTime() : Number(expiresAt);

  if (!Number.isFinite(expires) || expires <= 0) {
    throw new Error('expiresAt must be a valid timestamp or Date');
  }

  // Normalise the data that will be signed.
  // Using a simple colon separator keeps the format deterministic.
  const dataToSign = `${path}:${expires}`;
  const signature = _signData(dataToSign);

  const params = new URLSearchParams();
  params.set('path', path); // URLSearchParams will encode automatically
  params.set('expires', String(expires));
  params.set('sig', signature);

  return params.toString(); // e.g. "path=%2Ffiles%2Ffoo.pdf&expires=1728144573000&sig=ab12..."
}

// -------------------------------------------------------------------------
// Public API – verify
// -------------------------------------------------------------------------

/**
 * Verify a signed query string.
 *
 * The function expects either the raw query string (with or without the leading
 * `?`) or a full URL (anything after the `?` will be extracted).  It returns
 * **true** only when:
 *
 *   1. All three parameters (`path`, `expires`, `sig`) are present.
 *   2. The signature matches the HMAC of `path:expires`.
 *   3. The current time is **before** the supplied `expires` timestamp.
 *
 * @param {string} query - Query part of a URL (e.g. "?path=…&expires=…&sig=…").
 * @returns {boolean} `true` if the URL is authentic and still valid.
 */
function verify(query) {
  if (typeof query !== 'string' || query.length === 0) {
    return false;
  }

  // Strip leading '?' if present.
  const clean = query.startsWith('?') ? query.slice(1) : query;

  // If the caller passed a full URL, extract the part after the first '?'.
  const qs = clean.includes('://')
    ? clean.split('?')[1] || ''
    : clean;

  const params = new URLSearchParams(qs);

  const path = params.get('path');
  const expiresStr = params.get('expires');
  const receivedSig = params.get('sig');

  // All three fields must exist.
  if (!path || !expiresStr || !receivedSig) {
    return false;
  }

  const expires = Number(expiresStr);
  if (!Number.isFinite(expires) || expires <= 0) {
    return false;
  }

  // 1️⃣  Check expiry.
  if (Date.now() > expires) {
    return false; // expired
  }

  // 2️⃣  Re‑create the signature.
  const dataToSign = `${path}:${expires}`;
  const expectedSig = _signData(dataToSign);

  // 3️⃣  Constant‑time compare.
  return _constantTimeEqual(expectedSig, receivedSig);
}

// -------------------------------------------------------------------------
// Export
// -------------------------------------------------------------------------

module.exports = {
  sign,
  verify,
  setSecret,
  // expose the secret getter for advanced use‑cases (e.g. testing)
  _getSecret,
};
```

---

## How to use it

```js
// server.js (example with Express)
const express = require('express');
const { sign, verify, setSecret } = require('./download-signer');

const app = express();

// ---------------------------------------------------------------------
// 1️⃣  Initialise the secret (once, at startup)
// ---------------------------------------------------------------------
setSecret(process.env.DOWNLOAD_SIGNER_SECRET || 'my‑super‑secret‑32‑byte‑key');

// ---------------------------------------------------------------------
// 2️⃣  Endpoint that creates a signed download link
// ---------------------------------------------------------------------
app.get('/generate', (req, res) => {
  const filePath = '/files/report.pdf';
  const expiresInMs = 15 * 60 * 1000; // 15 minutes
  const qs = sign(filePath, Date.now() + expiresInMs);
  const downloadUrl = `${req.protocol}://${req.get('host')}/download?${qs}`;
  res.json({ downloadUrl });
});

// ---------------------------------------------------------------------
// 3️⃣  Endpoint that serves the file after verifying the signature
// ---------------------------------------------------------------------
app.get('/download', (req, res) => {
  if (!verify(req.originalUrl)) {
    return res.status(403).send('Invalid or expired link');
  }

  // The path is trusted now – you can safely locate the file.
  const params = new URLSearchParams(req.query);
  const filePath = params.get('path');

  // Example: serve a static file from a folder called "public"
  res.sendFile(filePath, { root: __dirname + '/public' }, err => {
    if (err) res.status(404).send('File not found');
  });
});

app.listen(3000, () => console.log('Server listening on http://localhost:3000'));
```

---

### Why this works

* **HMAC‑SHA‑256** guarantees that only someone who knows the secret can produce a valid signature.
* The signature covers **both** the resource (`path`) **and** the expiration timestamp (`expires`).  
  Changing either value invalidates the signature.
* `crypto.timingSafeEqual` prevents attackers from learning anything from the time it takes to compare signatures.
* The module is **stateless** – all information needed to verify a request travels with the URL, making it perfect for CDN‑backed or distributed environments.

Feel free to adapt the separator (`:`), add extra fields (e.g., user ID, IP address), or switch to a different hash algorithm – just keep the signing and verification logic symmetrical. Happy coding!

**download‑url‑signer.js** – a tiny, self‑contained Node.js module that can **sign** a download URL and later **verify** that the URL is still valid and untampered.  
It only uses the built‑in `crypto` module and works with plain CommonJS (`require`) so it can be dropped into any existing project.

```js
/**
 * download-url-signer.js
 *
 * Sign & verify download URLs using an HMAC‑SHA256 signature.
 *
 * API
 * ----
 *   setSecret(secret)               – set the secret key (once) or rely on
 *                                     process.env.DOWNLOAD_URL_SECRET.
 *
 *   sign(path, expiresAt)           – returns a query string:
 *                                     "?path=…&expires=…&sig=…"
 *
 *   verify(queryString)             – returns true only when the signature
 *                                     matches *and* the expiration time has
 *                                     not passed.
 *
 * The module purposefully does **not** construct a full URL – it only deals
 * with the query part.  This keeps it flexible (you can prepend any base URL
 * you like).
 */

const crypto = require('crypto');
const querystring = require('querystring');

let _secret = process.env.DOWNLOAD_URL_SECRET;

/**
 * Set the secret key used for HMAC generation.
 * Must be a non‑empty string.
 *
 * @param {string} secret
 */
function setSecret(secret) {
  if (typeof secret !== 'string' || secret.length === 0) {
    throw new Error('Secret must be a non‑empty string');
  }
  _secret = secret;
}

/**
 * Internal helper – returns the secret or throws if it has not been set.
 */
function _getSecret() {
  if (!_secret) {
    throw new Error(
      'Secret key not set. Call setSecret(secret) or define DOWNLOAD_URL_SECRET env var.'
    );
  }
  return _secret;
}

/**
 * Create an HMAC‑SHA256 signature from the supplied data.
 *
 * @param {string} data – the string to sign (e.g. `${path}:${expires}`)
 * @returns {string}   – hex‑encoded signature
 */
function _signData(data) {
  const hmac = crypto.createHmac('sha256', _getSecret());
  hmac.update(data);
  return hmac.digest('hex');
}

/**
 * Sign a download URL.
 *
 * @param {string} path          – the path part of the resource (e.g. "/files/report.pdf")
 * @param {number|Date} expiresAt – Unix timestamp (seconds) or a Date object after which the URL becomes invalid
 *
 * @returns {string} – query string ready to be appended to a URL, e.g.
 *                     "?path=%2Ffiles%2Freport.pdf&expires=1735689600&sig=ab12…"
 */
function sign(path, expiresAt) {
  if (typeof path !== 'string' || path.length === 0) {
    throw new Error('path must be a non‑empty string');
  }

  // Normalise expiresAt to a numeric Unix timestamp (seconds)
  let expires;
  if (expiresAt instanceof Date) {
    expires = Math.floor(expiresAt.getTime() / 1000);
  } else if (typeof expiresAt === 'number') {
    expires = Math.floor(expiresAt);
  } else {
    throw new Error('expiresAt must be a Date or a Unix timestamp (number)');
  }

  const dataToSign = `${path}:${expires}`;
  const signature = _signData(dataToSign);

  // Build the query string – encode each component safely
  const qs = querystring.stringify({
    path,
    expires,
    sig: signature,
  });

