 * Verify a signed query string.
 *
 * @param {string} queryString – the part after the "?" (it may also contain the leading "?")
 *
 * @returns {boolean} – true if the signature matches *and* the URL has not expired
 */
function verify(queryString) {
  if (typeof queryString !== 'string' || queryString.length === 0) {
    return false;
