  const expiresNum = parseInt(expires, 10);
  if (Number.isNaN(expiresNum)) {
    return false;
  }

  // Expiration check – current time in seconds
  const now = Math.floor(Date.now() / 1000);
  if (now > expiresNum) {
    return false; // URL has expired
  }

