  const expectedSig = _signData(`${path}:${expiresNum}`);

  // Use timing‑safe comparison to avoid side‑channel attacks
  const sigBuf = Buffer.from(sig, 'hex');
  const expectedBuf = Buffer.from(expectedSig, 'hex');

  // If the buffers are of different length, they can't be equal – return false
  if (sigBuf.length !== expectedBuf.length) {
    return false;
  }

  return crypto.timingSafeEqual(sigBuf, expectedBuf);
}

// Export the public API
module.exports = {
  setSecret,
  sign,
  verify,
};
