Below is a **self‑contained Node.js module** that can be dropped into any project.  
It exports two functions:

| Function | Description |
|----------|-------------|
| `sign(path, expiresAt)` | Returns a URL‑encoded query string that contains the original `path`, an `expires` timestamp, and a cryptographic `sig` (signature). |
| `verify(query)` | Takes a raw query string (the part after `?`) and returns `true` only when <br>• the required fields are present, <br>• the signature matches the data, **and** <br>• the current time is **before** the supplied expiry. |

The implementation relies only on Node’s built‑in `crypto` module and uses an HMAC‑SHA‑256 signature.  
A secret key is read from the environment variable `URL_SIGNING_SECRET`; if it is missing the module will throw at load time – this prevents you from accidentally running in an insecure state.

```js
/**
 * download-url-signer.js
 *
 * Simple URL signing / verification for downloadable resources.
 *
 *   const { sign, verify } = require('./download-url-signer');
 *
 *   // Create a signed link that expires in 15 minutes:
 *   const qs = sign('/files/report.pdf', Date.now() + 15 * 60 * 1000);
 *   // → "?path=%2Ffiles%2Freport.pdf&expires=1700000000&sig=..."
 *
 *   // Later, when a request arrives:
 *   const ok = verify(req.url.split('?')[1]);   // true / false
 *
 * The module deliberately does **not** expose the secret key.
 * It uses crypto.timingSafeEqual to avoid timing attacks.
 */

const crypto = require('crypto');
const { URLSearchParams } = require('url');

/**
 * -------------------------------------------------------------------------
 * Configuration
 * -------------------------------------------------------------------------
 * The secret key used for HMAC signing must be supplied via an environment
 * variable.  Keep it long (at least 32 random bytes) and never commit it to
 * source control.
 */
const SECRET = process.env.URL_SIGNING_SECRET;
if (!SECRET) {
  throw new Error(
    'Missing URL_SIGNING_SECRET environment variable – required for URL signing.'
  );
}

/**
 * Helper: create an HMAC‑SHA256 digest of the supplied data.
 *
 * @param {string} data   The string to sign (e.g. "path:expires").
 * @returns {string}      Hex‑encoded digest.
 */
function hmac(data) {
  return crypto.createHmac('sha256', SECRET).update(data).digest('hex');
}

/**
 * -------------------------------------------------------------------------
 * sign()
 * -------------------------------------------------------------------------
 *
 * @param {string} path        The original download path (e.g. "/files/foo.pdf").
 * @param {number|Date} expiresAt
 *          Either a UNIX timestamp in **seconds** or a Date object that
 *          represents when the URL should stop being valid.
 *
 * @returns {string}          A URL‑encoded query string, **including** the leading "?".
 *
 * Example:
 *   sign('/files/report.pdf', Date.now() + 10_000);
 *   // "?path=%2Ffiles%2Freport.pdf&expires=1700000000&sig=..."
 */
function sign(path, expiresAt) {
  // Normalise expiry to a UNIX timestamp (seconds)
  const expires =
    expiresAt instanceof Date
      ? Math.floor(expiresAt.getTime() / 1000)
      : Math.floor(Number(expiresAt) / 1000);

  if (!Number.isFinite(expires) || expires <= 0) {
    throw new TypeError('expiresAt must be a valid timestamp or Date');
  }

  // Ensure the path is a string (empty string is allowed – some APIs use it)
  if (typeof path !== 'string') {
    throw new TypeError('path must be a string');
  }

  // Data that will be signed – keep ordering deterministic
  const dataToSign = `${path}:${expires}`;
  const sig = hmac(dataToSign);

  const params = new URLSearchParams({
    path,
    expires: String(expires),
    sig,
  });

  // Returning with a leading "?" makes it easy to concatenate:
  //   `${baseUrl}${sign(...)}`
  return `?${params.toString()}`;
}

/**
 * -------------------------------------------------------------------------
 * verify()
 * -------------------------------------------------------------------------
 *
 * @param {string} queryString
 *          The raw query string (the part after the "?").
 *
 * @returns {boolean} true if the signature is valid **and** the URL has not
 *                    expired; otherwise false.
 *
 * Example:
 *   const ok = verify('path=%2Ffiles%2Freport.pdf&expires=1700000000&sig=...');
 */
function verify(queryString) {
  // Parse the query string – URLSearchParams tolerates a leading "?" as well.
  const params = new URLSearchParams(queryString.startsWith('?')
    ? queryString.slice(1)
    : queryString);

  const path = params.get('path');
  const expires = params.get('expires');
  const sig = params.get('sig');

  // Basic sanity checks
  if (!path || !expires || !sig) {
    return false;
  }

  // 1️⃣ Expiry check – treat the timestamp as seconds since epoch
  const expiresNum = Number(expires);
  if (!Number.isFinite(expiresNum) || expiresNum <= 0) {
    return false;
  }
  const now = Math.floor(Date.now() / 1000);
  if (now > expiresNum) {
    // URL is stale
    return false;
  }

  // 2️⃣ Re‑create the expected signature
  const expectedSig = hmac(`${path}:${expiresNum}`);

  // 3️⃣ Timing‑safe comparison
  // Convert both signatures to Buffers of the same length.
  const sigBuf = Buffer.from(sig, 'hex');
  const expectedBuf = Buffer.from(expectedSig, 'hex');

  // If lengths differ, signatures cannot match – avoid throwing.
  if (sigBuf.length !== expectedBuf.length) {
    return false;
  }

  return crypto.timingSafeEqual(sigBuf, expectedBuf);
}

/**
 * -------------------------------------------------------------------------
 * Export API
 * -------------------------------------------------------------------------
 */
module.exports = {
  sign,
  verify,
};
