/**
 * download-url-signer.js
 *
 * Sign and verify download URLs.
 *
 *   const { sign, verify } = require('./download-url-signer');
 *
 *   // Create a signed URL that expires in 10 minutes
 *   const query = sign('/files/report.pdf', Date.now() + 10 * 60 * 1000);
 *   // → "path=%2Ffiles%2Freport.pdf&expires=1696515600000&sig=..."
 *
 *   // Later, when a request arrives:
 *   if (verify(req.url.split('?')[1])) {
 *     // serve the file …
 *   } else {
 *     // reject – bad signature or expired
 *   }
 *
 * The implementation uses an HMAC‑SHA‑256 over the string
 *   `${path}:${expires}`
 * with a secret key that **must** be kept private.
 *
 * The secret can be supplied through the environment variable
 *   URL_SIGNING_SECRET
 * or, for quick testing, a hard‑coded fallback is used.
 */

const crypto = require('crypto');

/**
 * Secret key used for HMAC generation.
 * In production you should **never** commit a real secret to source control.
 * Set it via the environment variable `URL_SIGNING_SECRET`.
 */
const SECRET =
  process.env.URL_SIGNING_SECRET ||
  'CHANGE_ME_TO_A_RANDOM_LONG_STRING_IN_PRODUCTION';

/**
 * Create a signed query string for a given path and expiry time.
 *
 * @param {string} path       The resource path you want to protect (e.g. "/files/a.pdf").
 * @param {number|Date} expiresAt
 *        Either a Unix‑epoch timestamp in **milliseconds** or a Date object.
 *
 * @returns {string} A URL‑encoded query string (without the leading "?").
 *                   Example:
 *                     path=%2Ffiles%2Fa.pdf&expires=1696515600000&sig=ab12…
 */
function sign(path, expiresAt) {
  if (typeof path !== 'string') {
    throw new TypeError('path must be a string');
  }

  // Normalise expiresAt to a numeric millisecond timestamp
  const expires =
    expiresAt instanceof Date ? expiresAt.getTime() : Number(expiresAt);

  if (!Number.isFinite(expires) || expires <= 0) {
    throw new TypeError('expiresAt must be a valid timestamp (ms) or Date');
  }

  // Build the string that will be signed: "path:expires"
  const dataToSign = `${path}:${expires}`;

  // HMAC‑SHA‑256, output as hex
  const signature = crypto
    .createHmac('sha256', SECRET)
    .update(dataToSign, 'utf8')
    .digest('hex');

  // Encode each component so the resulting string can be safely appended to a URL
  const params = new URLSearchParams({
    path,
    expires: expires.toString(),
    sig: signature,
  });

  return params.toString(); // e.g. "path=%2Ffiles%2Fa.pdf&expires=1696515600000&sig=..."
}

/**
 * Verify a signed query string.
 *
 * @param {string|URLSearchParams} query
 *        The raw query part of the URL (the part after "?").
 *        It can be a string (e.g. "path=%2Ffiles%2Fa.pdf&expires=…")
 *        or an already‑constructed URLSearchParams instance.
 *
 * @returns {boolean} true if:
 *          • the required parameters are present,
 *          • the signature matches the data, and
 *          • the current time is **not** past the expiry timestamp.
 *          Otherwise false.
 */
function verify(query) {
  // Normalise to URLSearchParams
  const params =
    typeof query === 'string' ? new URLSearchParams(query) : query;

  const path = params.get('path');
  const expiresStr = params.get('expires');
  const sig = params.get('sig');

  // Missing any field → instantly invalid
  if (!path || !expiresStr || !sig) {
    return false;
  }

  const expires = Number(expiresStr);
  if (!Number.isFinite(expires) || expires <= 0) {
    return false;
  }

  // Expired?
  if (Date.now() > expires) {
    return false;
  }

  // Re‑create the data that should have been signed
  const dataToSign = `${path}:${expires}`;

  // Compute the expected signature
  const expectedSig = crypto
    .createHmac('sha256', SECRET)
    .update(dataToSign, 'utf8')
    .digest('hex');

  // Compare signatures in constant‑time to avoid timing attacks.
  // crypto.timingSafeEqual works on Buffers of equal length.
  const sigBuf = Buffer.from(sig, 'hex');
  const expBuf = Buffer.from(expectedSig, 'hex');

  if (sigBuf.length !== expBuf.length) {
    // Different length → definitely not equal
    return false;
  }

  return crypto.timingSafeEqual(sigBuf, expBuf);
}

/* -------------------------------------------------------------------------- */
/* Export the public API                                                       */

module.exports = {
  sign,
  verify,
};

