// urlSigner.js
// Simple URL signing / verification using HMAC‑SHA256.
//   sign(path, expiresAt) -> query string: ?path=...&expires=...&sig=...
//   verify(query)        -> true if signature matches and not expired.

const crypto = require('crypto');
const { URLSearchParams } = require('url');

// Secret key for HMAC – should be set in the environment for production use.
const SECRET = process.env.URL_SIGNING_SECRET || 'default-insecure-secret';

// Helper: create HMAC‑SHA256 digest and return a URL‑safe Base64 string.
function hmacDigest(data) {
  const hmac = crypto.createHmac('sha256', SECRET);
  hmac.update(data);
  // Base64 URL‑safe (replace +/ with -_ and strip padding)
  return hmac.digest('base64')
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=+$/g, '');
}

/**
 * Generate a signed URL query string.
 * @param {string} path       – Resource path (e.g., "/files/report.pdf")
 * @param {number|string} expiresAt – Unix timestamp (seconds) when the URL expires
 * @returns {string} Query string without leading '?'
 */
function sign(path, expiresAt) {
  const expires = String(expiresAt);
  const dataToSign = `${path}:${expires}`;
  const sig = hmacDigest(dataToSign);

  const params = new URLSearchParams({
    path,
    expires,
    sig,
  });

  return params.toString(); // e.g., "path=%2Ffiles%2Freport.pdf&expires=1735689600&sig=..."
}

/**
 * Verify a signed query string.
 * @param {string} query – Full query string (with or without leading '?')
 * @returns {boolean} True if signature is valid and not expired.
 */
function verify(query) {
  // Strip leading '?' if present.
  const qs = query.startsWith('?') ? query.slice(1) : query;
  const params = new URLSearchParams(qs);

  const path = params.get('path');
  const expires = params.get('expires');
  const sig = params.get('sig');

  if (!path || !expires || !sig) return false;

  // Check expiration (assume expires is a Unix timestamp in seconds).
  const now = Math.floor(Date.now() / 1000);
  if (Number(expires) < now) return false;

  // Re‑compute expected signature.
  const expectedSig = hmacDigest(`${path}:${expires}`);

  // Use timing‑safe comparison.
  const bufSig = Buffer.from(sig);
  const bufExp = Buffer.from(expectedSig);
  if (bufSig.length !== bufExp.length) return false;

  return crypto.timingSafeEqual(bufSig, bufExp);
}

module.exports = { sign, verify };
