 *   const qs = sign('/files/report.pdf', Date.now() + 10 * 60 * 1000);
 *   // qs => "path=%2Ffiles%2Freport.pdf&expires=169...&sig=..."
 */
function sign(path, expiresAt) {
  if (typeof path !== 'string' || path.length === 0) {
    throw new Error('path must be a non‑empty string');
  }

  const expires =
    expiresAt instanceof Date ? expiresAt.getTime() : Number(expiresAt);

  if (!Number.isFinite(expires) || expires <= 0) {
    throw new Error('expiresAt must be a valid timestamp (ms since epoch)');
  }

  const sig = _signature(path, expires);

  const params = new URLSearchParams({
    path,
    expires: expires.toString(),
    sig,
  });

  // URLSearchParams automatically percent‑encodes the values.
  return params.toString(); // e.g. "path=%2Ffiles%2Freport.pdf&expires=169...&sig=..."
}

/**
 * Verify a signed query string (or full URL containing a query string).
 *
 * @param {string} queryOrUrl
 *        - Either just the query part (`path=…&expires=…&sig=…`) or a full URL.
 * @returns {boolean} `true` if the signature matches **and** the URL has not expired.
 *
 * The function never throws – any malformed input simply results in `false`.
 */
function verify(queryOrUrl) {
  try {
    // Extract just the query component – URLSearchParams can handle both forms.
    const qs = queryOrUrl.includes('?')
      ? queryOrUrl.split('?')[1]
      : queryOrUrl;

    const params = new URLSearchParams(qs);

    const path = params.get('path');
    const expiresStr = params.get('expires');
    const sig = params.get('sig');

    // All three parameters must be present.
    if (!path || !expiresStr || !sig) {
      return false;
    }

    const expires = Number(expiresStr);
    if (!Number.isFinite(expires) || expires <= 0) {
      return false;
    }

    // Expiry check – we treat the timestamp as **milliseconds**.
    if (Date.now() > expires) {
      return false; // expired
    }

    // Re‑compute the expected signature.
    const expectedSig = _signature(path, expires);

    // Use timing‑safe comparison to avoid side‑channel leaks.
    const sigBuf = Buffer.from(sig, 'hex');
    const expBuf = Buffer.from(expectedSig, 'hex');

    // If lengths differ, comparison must still be performed to keep timing constant.
    if (sigBuf.length !== expBuf.length) {
      // Pad the shorter buffer (crypto.timingSafeEqual throws on length mismatch)
      const maxLen = Math.max(sigBuf.length, expBuf.length);
      const paddedSig = Buffer.alloc(maxLen, 0);
      const paddedExp = Buffer.alloc(maxLen, 0);
      sigBuf.copy(paddedSig);
      expBuf.copy(paddedExp);
      return crypto.timingSafeEqual(paddedSig, paddedExp) && false;
    }

    return crypto.timingSafeEqual(sigBuf, expBuf);
  } catch (e) {
    // Any parsing / unexpected error means verification fails.
    return false;
  }
}

