// downloadSigner.js
// Simple URL signer/validator for download links using HMAC‑SHA256.
// Uses Node's built‑in crypto module and a secret key from the environment.

const crypto = require('crypto');
const { URLSearchParams } = require('url');

// Secret used for HMAC – must be kept confidential.
// In production you should load this from a secure place (e.g., env var, secret manager).
const SECRET = process.env.DOWNLOAD_URL_SECRET || 'default-insecure-secret';

// Helper: create a base64url string (no padding, URL‑safe chars)
function toBase64Url(buf) {
  return buf.toString('base64')
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=+$/g, '');
}

// Generate HMAC‑SHA256 signature for given data
function signData(data) {
  return toBase64Url(
    crypto.createHmac('sha256', SECRET).update(data).digest()
  );
}

/**
 * Sign a download URL.
 * @param {string} path      – Path to the resource (e.g., "/files/report.pdf")
 * @param {number|string} expiresAt – Unix timestamp (seconds) when the link expires
 * @returns {string} query string containing path, expires, and sig
 */
function sign(path, expiresAt) {
  const expires = String(expiresAt);
  // canonical string to sign: path + '|' + expires
  const dataToSign = `${path}|${expires}`;
  const sig = signData(dataToSign);

  const params = new URLSearchParams({
    path,
    expires,
    sig,
  });

  return params.toString(); // e.g. "path=%2Ffiles%2Freport.pdf&expires=1735689600&sig=..."
}

/**
 * Verify a signed query string.
 * @param {string} query – The raw query part of the URL (e.g., "?path=...&expires=...&sig=...")
 * @returns {boolean} true if signature is valid and not expired
 */
function verify(query) {
  // Remove leading '?' if present
  const qs = query.startsWith('?') ? query.slice(1) : query;
  const params = new URLSearchParams(qs);

  const path = params.get('path');
  const expires = params.get('expires');
  const sig = params.get('sig');

  // All three components must exist
  if (!path || !expires || !sig) return false;

  // Check expiration (expires is unix seconds)
  const now = Math.floor(Date.now() / 1000);
  if (Number(expires) < now) return false;

  // Re‑create the signature
  const dataToSign = `${path}|${expires}`;
  const expectedSig = signData(dataToSign);

  // Use timing‑safe comparison
  const sigBuf = Buffer.from(sig);
  const expectedBuf = Buffer.from(expectedSig);
  if (sigBuf.length !== expectedBuf.length) return false;

  return crypto.timingSafeEqual(sigBuf, expectedBuf);
}

module.exports = { sign, verify };
