  const expires = typeof expiresAt === 'number'
    ? expiresAt
    : Math.floor(new Date(expiresAt).getTime() / 1000); // seconds

  // Data to sign: "path:expires"
  const data = `${path}:${expires}`;
  const sig = crypto
    .createHmac('sha256', SECRET)
    .update(data)
    .digest('hex');

  // Encode components for safe URL usage
  const qs = new URLSearchParams({
    path: path,
    expires: expires.toString(),
    sig,
  });

  return qs.toString(); // e.g. "path=%2Ffiles%2Freport.pdf&expires=1735689600&sig=..."
