 * @param {Date|number|string} expiresAt – expiration time (Date object, Unix seconds, or parseable string)
 * @returns {string} query string beginning with '?'
 */
function sign(path, expiresAt) {
  if (!secret) throw new Error('Signing secret not set');

  // Normalise expiry to Unix seconds (integer)
  const expires = typeof expiresAt === 'number'
    ? Math.floor(expiresAt)
    : Math.floor(new Date(expiresAt).getTime() / 1000);

  const data = `${path}:${expires}`;
  const hmac = crypto.createHmac('sha256', secret);
  hmac.update(data);
  const sig = hmac.digest('hex');

  const params = new URLSearchParams({
    path,
    expires: expires.toString(),
    sig,
  });

  return `?${params.toString()}`;
}

/**
 * Verify a signed query string.
 * @param {string} queryString – may start with '?' or not
 * @returns {boolean} true if signature is valid and not expired
 */
function verify(queryString) {
  if (!secret) throw new Error('Signing secret not set');

  // Strip leading '?'
  const qs = queryString.startsWith('?') ? queryString.slice(1) : queryString;
  const params = new URLSearchParams(qs);

  const path = params.get('path');
  const expires = params.get('expires');
  const sig = params.get('sig');

  if (!path || !expires || !sig) return false;

  const now = Math.floor(Date.now() / 1000);
  if (now > Number(expires)) return false; // expired

  const data = `${path}:${expires}`;
  const expectedHmac = crypto.createHmac('sha256', secret).update(data).digest();

  // Compare signatures in constant time
  const providedSig = Buffer.from(sig, 'hex');
  if (providedSig.length !== expectedHmac.length) return false;
  return crypto.timingSafeEqual(providedSig, expectedHmac);
}

