//   expires – expiry timestamp (seconds since epoch)
//   sig    – HMAC signature
// ------------------------------------------------------------------
function sign(path, expiresAt) {
  // Normalise expiry to a unix‑seconds integer
  const expires =
    expiresAt instanceof Date
      ? Math.floor(expiresAt.getTime() / 1000)
      : Number(expiresAt);

  if (!path || isNaN(expires)) {
    throw new Error('Invalid arguments to sign()');
  }

  const signature = computeSignature(path, expires);

  const params = new URLSearchParams();
  params.set('path', path);
  params.set('expires', expires.toString());
  params.set('sig', signature);

  return params.toString(); // e.g. "path=%2Ffile.txt&expires=1735689600&sig=..."
}

