// verify(queryString)
//   queryString – the raw query part of the URL (e.g. "?path=...&expires=...&sig=...")
// Returns true if:
//   * all three parameters are present
//   * the signature matches the expected HMAC
//   * the current time is before the expiry timestamp
// ------------------------------------------------------------------
function verify(queryString) {
  // Strip leading '?' if present
  const clean = queryString.startsWith('?')
    ? queryString.slice(1)
    : queryString;

