  const h = crypto.createHmac('sha256', SECRET);
  // Normalise expires to a string of milliseconds since epoch
  const expiresStr = typeof expires === 'number' ? expires.toString() : expires;
  h.update(`${path}\n${expiresStr}`);
  return h.digest('hex');
