```js
// urlSigner.js
// Simple URL signing / verification using HMAC‑SHA256.
// Requires a secret key (set in the environment as URL_SIGNER_SECRET).

const crypto = require('crypto');
const { URLSearchParams } = require('url');

const SECRET = process.env.URL_SIGNER_SECRET || 'change-me-please';

/**
 * Generate a HMAC‑SHA256 signature for the given path and expiry.
 * @param {string} path      - The resource path to protect (e.g. "/files/report.pdf").
 * @param {number|string} expiresAt - Unix timestamp (seconds) when the URL should expire.
 * @returns {string} Query string containing path, expires, and sig.
 */
function sign(path, expiresAt) {
  const expires = typeof expiresAt === 'number' ? expiresAt.toString() : expiresAt;

  // Build the data to sign: "path:expires"
  const data = `${path}:${expires}`;

  // Compute HMAC‑SHA256 signature (hex encoded)
  const sig = crypto
    .createHmac('sha256', SECRET)
    .update(data)
    .digest('hex');

  // Encode components for safe URL transport
  const params = new URLSearchParams({
    path,
    expires,
    sig,
  });

  // Return only the query string (no leading '?')
  return params.toString();
}

/**
 * Verify a signed URL query string.
 * @param {string} query - The raw query string (e.g. "path=/file&expires=1700000000&sig=abcd...")
 * @returns {boolean} True if the signature is valid and the URL has not expired.
 */
function verify(query) {
  const params = new URLSearchParams(query);

  const path = params.get('path');
  const expires = params.get('expires');
  const sig = params.get('sig');

  // All three components must be present
  if (!path || !expires || !sig) return false;

  // Check expiration (expires is a Unix timestamp in seconds)
  const now = Math.floor(Date.now() / 1000);
  if (Number(expires) < now) return false;

  // Re‑create the data string and compute expected signature
  const data = `${path}:${expires}`;
  const expectedSig = crypto
    .createHmac('sha256', SECRET)
    .update(data)
    .digest('hex');

  // Timing‑safe comparison to avoid side‑channel attacks
  const match = crypto.timingSafeEqual(
    Buffer.from(sig, 'hex'),
    Buffer.from(expectedSig, 'hex')
  );

  return match;
}

module.exports = { sign, verify };
```

