/**
 * download-url-signer
 * -------------------
 * A very small helper that creates a signed query string for a download URL
 * and can later verify that the signature is still valid and not expired.
 *
 * The implementation uses only the built‑in `crypto` module (no external deps)
 * and HMAC‑SHA256 with a secret key that you provide (or read from an env var).
 *
 * ── API ─────────────────────────────────────────────────────────────────────
 *   sign(path, expiresAt) → string
 *       path      – the resource path that will be downloaded (e.g. "/files/a.pdf")
 *       expiresAt – Date object, number (ms since epoch) or a Unix timestamp (seconds)
 *       returns   – a URL‑encoded query string, e.g.
 *                   "path=%2Ffiles%2Fa.pdf&expires=1735689600&sig=ab12…"
 *
 *   verify(query) → boolean
 *       query – a query string (with or without the leading "?")
 *                containing the three parameters `path`, `expires` and `sig`.
 *       returns – true only when
 *                 • the signature matches the supplied path & expires,
 *                 • the `expires` timestamp is in the future,
 *                 • and the signature comparison is done in constant‑time.
 *
 * ── Usage example ───────────────────────────────────────────────────────
 *   const signer = require('./download-url-signer');
 *
 *   // 1️⃣  Create a signed URL (valid for 10 minutes)
 *   const query = signer.sign('/files/report.pdf', Date.now() + 10 * 60 * 1000);
 *   const url   = `https://cdn.example.com/download?${query}`;
 *
 *   // 2️⃣  Later, when a request arrives, verify it
 *   if (!signer.verify(req.url.split('?')[1])) {
 *       res.statusCode = 403;
 *       res.end('Invalid or expired download link');
 *       return;
 *   }
 *
 *   // … serve the file …
 */

const crypto = require('crypto');
const querystring = require('querystring');

/**
 * -------------------------------------------------------------------------
 * Configuration
 * -------------------------------------------------------------------------
 * The secret key must be a sufficiently random string.  For production you
 * should keep it out of source control – e.g. set the environment variable
 * `DOWNLOAD_URL_SIGNING_KEY`.
 */
const SECRET = process.env.DOWNLOAD_URL_SIGNING_KEY || 'change‑me‑to‑a‑real‑secret';

/**
 * Helper: turn a Date|number|undefined into a Unix timestamp (seconds).
 */
function toUnixSeconds(value) {
  if (value instanceof Date) return Math.floor(value.getTime() / 1000);
  if (typeof value === 'number') {
    // If the number looks like milliseconds ( > 10⁹ ), assume ms.
    return value > 1_000_000_000_000 ? Math.floor(value / 1000) : Math.floor(value);
  }
  // Default: now
  return Math.floor(Date.now() / 1000);
}

/**
 * -------------------------------------------------------------------------
 * sign(path, expiresAt)
 * -------------------------------------------------------------------------
 * Returns a URL‑encoded query string that contains:
 *   - path   : the original path (percent‑encoded)
 *   - expires: Unix timestamp (seconds)
 *   - sig    : HMAC‑SHA256 over `${path}:${expires}`
 *
 * @param {string} path        Path to the resource (e.g. "/files/a.pdf")
 * @param {Date|number} expiresAt  Expiration moment (Date, ms, or seconds)
 * @returns {string}           Query string (no leading "?")
 */
function sign(path, expiresAt) {
  if (typeof path !== 'string') {
    throw new TypeError('path must be a string');
  }

  const expires = toUnixSeconds(expiresAt);
  const data = `${path}:${expires}`;

  const hmac = crypto.createHmac('sha256', SECRET);
  hmac.update(data);
  const sig = hmac.digest('hex');

  // Build a plain‑object then let querystring.stringify do the percent‑encoding
  const qs = querystring.stringify({
    path,
    expires,
    sig,
  });

  return qs; // e.g. "path=%2Ffiles%2Fa.pdf&expires=1735689600&sig=ab12..."
}

/**
 * -------------------------------------------------------------------------
 * verify(query)
 * -------------------------------------------------------------------------
 * @param {string} query   The raw query string (with or without leading "?")
 * @returns {boolean}      true if the signature is valid **and** not expired
 */
function verify(query) {
  if (typeof query !== 'string') {
    throw new TypeError('query must be a string');
  }

  // Strip a possible leading '?'
  const clean = query.startsWith('?') ? query.slice(1) : query;

  // Parse into an object: { path, expires, sig }
  const params = querystring.parse(clean);

  // All three parameters are required
  if (!params.path || !params.expires || !params.sig) {
    return false;
  }

  const expires = Number(params.expires);
  if (!Number.isFinite(expires) || expires <= 0) {
    return false;
  }

  // 1️⃣  Check expiration first – cheap, no crypto needed
  const now = Math.floor(Date.now() / 1000);
  if (expires < now) {
    return false; // expired
  }

  // 2️⃣  Re‑create the data string & compute the expected signature
  const data = `${params.path}:${expires}`;
  const hmac = crypto.createHmac('sha256', SECRET);
  hmac.update(data);
  const expectedSig = Buffer.from(hmac.digest('hex'), 'utf8');
  const providedSig = Buffer.from(params.sig, 'utf8');

  // 3️⃣  Constant‑time comparison
  // If lengths differ, `timingSafeEqual` throws – we treat that as a mismatch.
  if (expectedSig.length !== providedSig.length) {
    return false;
  }

  return crypto.timingSafeEqual(expectedSig, providedSig);
}

/**
 * Export the two public helpers.
 */
module.exports = {
  sign,
  verify,
};
```

### How it works

1. **Signing**  
   * The caller supplies the resource path and an expiration moment.  
   * The module converts the expiration to a Unix timestamp (seconds).  
   * It builds the string `"{path}:{expires}"` and creates an HMAC‑SHA256 using the secret key.  
   * The resulting hex digest becomes the `sig` parameter.  
   * The three parameters are URL‑encoded into a query string.

2. **Verification**  
   * The incoming query string is parsed.  
   * If any required field is missing or the timestamp is already past, verification fails.  
   * The same data string (`path:expires`) is re‑hashed with the secret key.  
   * The newly computed signature is compared to the supplied one with `crypto.timingSafeEqual` (constant‑time).  
   * Only when the signatures match **and** the URL has not expired does `verify` return `true`.

### Integration tips

| Situation | What to do |
|-----------|------------|
| **Different secret per environment** | Set `process.env.DOWNLOAD_URL_SIGNING_KEY` on each server (e.g. via Docker secret, `.env` file, or your cloud provider's secret manager). |
| **Expose only the query string** | Concatenate it to your base URL: `https://cdn.example.com/download?${signer.sign(...)};` |
| **Large files – streaming** | The signature check is cheap; you can run it as the first middleware before opening any stream. |
| **Clock drift** | If you need a small grace period, add `const GRACE = 30; // seconds` and compare `expires + GRACE < now`. |

