// downloadSigner.js
// Simple URL signing/verification using HMAC-SHA256.
// Usage:
//   const signer = require('./downloadSigner')('my-secret-key');
//   const qs = signer.sign('/files/report.pdf', Date.now() + 60000); // 1‑min expiry
//   const ok = signer.verify(qs); // true if not expired and signature matches

const crypto = require('crypto');

/**
 * Factory that creates a signer/validator bound to a secret key.
 * @param {string|Buffer} secret - Secret key used for HMAC.
 * @returns {{ sign: Function, verify: Function }}
 */
module.exports = function createSigner(secret) {
  if (!secret) {
    throw new Error('A secret key is required for signing URLs');
  }

  /**
   * Generate a signed query string.
   * @param {string} path - The resource path (e.g., "/files/report.pdf").
   * @param {number} expiresAt - Unix timestamp (ms) when the URL should expire.
   * @returns {string} Query string containing path, expires, and signature.
   */
  function sign(path, expiresAt) {
    if (typeof path !== 'string') throw new TypeError('path must be a string');
    if (typeof expiresAt !== 'number') throw new TypeError('expiresAt must be a number');

    const payload = `${path}:${expiresAt}`;
    const signature = crypto
      .createHmac('sha256', secret)
      .update(payload)
      .digest('hex');

    // Encode components to be URL‑safe
    const qs = new URLSearchParams({
      path,
      expires: expiresAt.toString(),
      sig: signature,
    });

    return qs.toString(); // e.g., "path=%2Ffiles%2Freport.pdf&expires=169...&sig=..."
  }

  /**
   * Verify a signed query string.
   * @param {string} query - The raw query string (e.g., from req.url).
   * @returns {boolean} True if signature matches and not expired.
   */
  function verify(query) {
    const params = new URLSearchParams(query);
    const path = params.get('path');
    const expires = params.get('expires');
    const sig = params.get('sig');

    if (!path || !expires || !sig) return false;

    const expiresNum = Number(expires);
    if (Number.isNaN(expiresNum) || Date.now() > expiresNum) return false; // expired

    const payload = `${path}:${expiresNum}`;
    const expectedSig = crypto
      .createHmac('sha256', secret)
      .update(payload)
      .digest('hex');

    // Use constant‑time comparison to avoid timing attacks
    return crypto.timingSafeEqual(Buffer.from(sig, 'hex'), Buffer.from(expectedSig, 'hex'));
  }

  return { sign, verify };
};
