// urlSigner.js
// Simple URL signing / verification using HMAC‑SHA256.
// ---------------------------------------------------
// sign(path, expiresAt) -> query string with path, expires, sig
// verify(queryString)   -> true if signature matches and not expired

const crypto = require('crypto');
const querystring = require('querystring');

// Secret key – set via env var for production use.
const SECRET = process.env.URL_SIGNING_SECRET || 'change-me-please';

/**
 * Create an HMAC signature for the given data.
 * @param {string} data - The string to sign.
 * @returns {string} Hex‑encoded signature.
 */
function _signData(data) {
  return crypto.createHmac('sha256', SECRET).update(data).digest('hex');
}

/**
 * Build a signed URL query string.
 * @param {string} path - The resource path (e.g. "/files/report.pdf").
 * @param {Date|number} expiresAt - Expiration as a Date object or Unix timestamp (seconds).
 * @returns {string} Query string: path=...&expires=...&sig=...
 */
function sign(path, expiresAt) {
  const expires = typeof expiresAt === 'number'
    ? expiresAt
    : Math.floor((expiresAt instanceof Date ? expiresAt : new Date()).getTime() / 1000);

  const dataToSign = `${path}:${expires}`;
  const sig = _signData(dataToSign);

  // Encode components to be URL‑safe.
  const qs = querystring.stringify({
    path,
    expires,
    sig,
  });
  return qs;
}

/**
 * Verify a signed query string.
 * @param {string} query - The raw query string (e.g. "path=...&expires=...&sig=...").
 * @returns {boolean} True if signature is valid and not expired.
 */
function verify(query) {
  const params = querystring.parse(query);

  const { path, expires, sig } = params;
  if (!path || !expires || !sig) return false;

  const expiresNum = Number(expires);
  if (Number.isNaN(expiresNum)) return false;

  // Expiration check (current time in seconds).
  const now = Math.floor(Date.now() / 1000);
  if (expiresNum < now) return false;

  const expectedSig = _signData(`${path}:${expiresNum}`);

  // Use timing‑safe comparison to avoid side‑channel attacks.
  const bufSig = Buffer.from(sig, 'hex');
  const bufExp = Buffer.from(expectedSig, 'hex');
  if (bufSig.length !== bufExp.length) return false;

  return crypto.timingSafeEqual(bufSig, bufExp);
}

module.exports = { sign, verify };
