  if (typeof secret !== 'string' || secret.length === 0) {
    throw new Error('Secret must be a non‑empty string');
  }
  _secret = secret;
}

// -----------------------------------------------------------------------------
// Helper: compute HMAC signature for a given path & expiry
// -----------------------------------------------------------------------------
function _calcSignature(path, expires) {
  // The data to sign is deterministic – use a simple colon delimiter.
  const data = `${path}:${expires}`;
  return crypto
    .createHmac('sha256', _secret)
    .update(data, 'utf8')
    .digest('hex');
}

// -----------------------------------------------------------------------------
// sign(path, expiresAt)
//   - path: string (e.g. "/files/report.pdf")
//   - expiresAt: Unix timestamp (seconds) or Date object
// Returns: query string ready to be appended to a URL.
// -----------------------------------------------------------------------------
function sign(path, expiresAt) {
  if (typeof path !== 'string') throw new TypeError('path must be a string');

  // Normalise expiry to a numeric Unix timestamp (seconds)
  const expires =
    expiresAt instanceof Date
      ? Math.floor(expiresAt.getTime() / 1000)
      : Number(expiresAt);

  if (!Number.isFinite(expires) || expires <= 0) {
    throw new TypeError('expiresAt must be a valid timestamp or Date');
  }

  const sig = _calcSignature(path, expires);

  const params = new URLSearchParams({
    path,
    expires: expires.toString(),
    sig,
  });

  // Return only the query part (no leading '?')
  return params.toString();
}

// -----------------------------------------------------------------------------
// verify(query)
//   - query: string (e.g. "path=%2Ffiles%2Freport.pdf&expires=1735689600&sig=abcd...")
// Returns: true if signature matches and the URL has not expired.
// -----------------------------------------------------------------------------
function verify(query) {
  if (typeof query !== 'string') return false;

  const params = new URLSearchParams(query);

  const path = params.get('path');
  const expiresStr = params.get('expires');
  const providedSig = params.get('sig');

  if (!path || !expiresStr || !providedSig) return false;

  const expires = Number(expiresStr);
  if (!Number.isFinite(expires) || expires <= 0) return false;

  // Expiry check – current time (seconds) must be less than expires
  const now = Math.floor(Date.now() / 1000);
  if (now > expires) return false;

  // Re‑calculate expected signature
  const expectedSig = _calcSignature(path, expires);

  // Constant‑time comparison to avoid timing attacks
  const bufA = Buffer.from(providedSig, 'hex');
  const bufB = Buffer.from(expectedSig, 'hex');

  // If lengths differ, signatures cannot match
  if (bufA.length !== bufB.length) return false;

  return crypto.timingSafeEqual(bufA, bufB);
}

// -----------------------------------------------------------------------------
// Export the public API
// -----------------------------------------------------------------------------
module.exports = {
  setSecret,
  sign,
  verify,
};
