 * Sign a download URL.
 * @param {string} path        – URL path (e.g. "/files/report.pdf")
 * @param {number|string} expiresAt – Unix timestamp (seconds) when the link expires
 * @returns {string} query string containing path, expires, and signature
 */
function sign(path, expiresAt) {
  const expires = String(expiresAt);
  const encodedPath = encodeURIComponent(path);
  const data = `${encodedPath}:${expires}`;
  const sig = hmac(data);
  // Return without leading '?', caller can prepend if needed.
  return `path=${encodedPath}&expires=${expires}&sig=${sig}`;
}

/**
 * Verify a signed query string.
 * @param {string} queryString – may include leading '?' or be raw (e.g. "path=...&expires=...&sig=...")
 * @returns {boolean} true if signature matches and not expired
 */
function verify(queryString) {
  // Strip leading '?' if present.
  const qs = queryString.startsWith('?') ? queryString.slice(1) : queryString;
  const params = new URLSearchParams(qs);

  const encodedPath = params.get('path');
  const expires = params.get('expires');
  const providedSig = params.get('sig');

  if (!encodedPath || !expires || !providedSig) return false;

  // Expiry check – treat value as seconds since epoch.
  const now = Math.floor(Date.now() / 1000);
  if (Number(expires) < now) return false;

  const data = `${encodedPath}:${expires}`;
  const expectedSig = hmac(data);

  // Use timing‑safe comparison to avoid side‑channel attacks.
  const bufProvided = Buffer.from(providedSig, 'hex');
  const bufExpected = Buffer.from(expectedSig, 'hex');

  // If lengths differ, signatures can't match.
  if (bufProvided.length !== bufExpected.length) return false;

  return crypto.timingSafeEqual(bufProvided, bufExpected);
}

