// Create a signature for a given path and expiry timestamp.
// Returns a hex‑encoded string.
function createSignature(path, expiresAt) {
  const hmac = crypto.createHmac('sha256', getSecret());
  // The string to sign must be deterministic.
  hmac.update(`${path}:${expiresAt}`);
  return hmac.digest('hex');
}

// -----------------------------------------------------------------------------
// Public API: sign a download URL.
//   path       – string, e.g. "/files/report.pdf"
//   expiresAt  – Date instance or numeric UNIX timestamp (seconds)
// Returns a query string (without leading "?") containing:
//   path, expires, and sig
function sign(path, expiresAt) {
  const expiry = typeof expiresAt === 'number' ? expiresAt : Math.floor(expiresAt.getTime() / 1000);
  const encodedPath = encodeURIComponent(path);
  const signature = createSignature(path, expiry);

  // Build query string
  const params = new URLSearchParams({
    path: encodedPath,
    expires: expiry.toString(),
    sig: signature,
  });

  return params.toString(); // e.g. "path=%2Ffiles%2Freport.pdf&expires=1735689600&sig=..."
}

// -----------------------------------------------------------------------------
// Public API: verify a signed query string.
//   query – string (may start with "?" or be raw)
// Returns true only if:
//   • required parameters are present,
//   • the signature matches, and
//   • the current time is ≤ expires.
// Otherwise returns false.
function verify(query) {
  // Strip leading "?" if present
  const qs = query.startsWith('?') ? query.slice(1) : query;
  const params = new URLSearchParams(qs);

  const path = params.get('path');
  const expires = params.get('expires');
  const sig = params.get('sig');

  if (!path || !expires || !sig) return false;

  const expiryNum = Number(expires);
  if (Number.isNaN(expiryNum) || expiryNum < Math.floor(Date.now() / 1000)) {
    // Expired or invalid timestamp
    return false;
