//   sign(path, expiresAt) -> "path=...&expires=...&sig=..."
//   verify(queryString)   -> true|false
// ---------------------------------------------------
//   expiresAt: Unix timestamp (seconds) or Date object.

const crypto = require('crypto');
const { URLSearchParams } = require('url');

// secret key – in production load this from env / config
const SECRET = process.env.DOWNLOAD_URL_SECRET || 'change‑me‑to‑a‑strong‑secret';

/**
 * Create a signed query string for a downloadable resource.
 *
 * @param {string} path        – resource path (e.g. "/files/report.pdf")
 * @param {number|Date} expiresAt – expiry time (Unix seconds or Date)
 * @returns {string} query string (no leading "?")
 */
function sign(path, expiresAt) {
  // normalise expiry to a numeric Unix timestamp (seconds)
  const exp = typeof expiresAt === 'number'
    ? expiresAt
    : Math.floor(expiresAt.getTime() / 1000);

  // compute HMAC over "path|expires"
  const hmac = crypto.createHmac('sha256', SECRET);
  hmac.update(`${path}|${exp}`);
  const sig = hmac.digest('hex');

  // build query string (URL‑encoded)
  const params = new URLSearchParams();
  params.set('path', path);
  params.set('expires', exp.toString());
  params.set('sig', sig);
  return params.toString();
}

