 * Verify a signed query string.
 *
 * @param {string} queryString – the raw query part of the URL (e.g. "?path=...&expires=...&sig=...")
 * @returns {boolean} true if signature matches and not expired
 */
function verify(queryString) {
  // strip optional leading '?'
  const qs = queryString.startsWith('?') ? queryString.slice(1) : queryString;
  const params = new URLSearchParams(qs);

  const path = params.get('path');
  const expires = params.get('expires');
  const sig = params.get('sig');

  if (!path || !expires || !sig) return false;

  const expNum = Number(expires);
  if (Number.isNaN(expNum) || Date.now() / 1000 > expNum) return false; // expired

  // recompute expected signature
  const hmac = crypto.createHmac('sha256', SECRET);
  hmac.update(`${path}|${expNum}`);
  const expectedSig = hmac.digest('hex');

  // timing‑safe comparison
  const bufSig = Buffer.from(sig, 'hex');
  const bufExp = Buffer.from(expectedSig, 'hex');
  if (bufSig.length !== bufExp.length) return false;
  return crypto.timingSafeEqual(bufSig, bufExp);
}

module.exports = { sign, verify };
