// ------------------------------------------------------------------
// sign(path, expiresAt)
//   path       – string, the resource path (e.g., "/files/report.pdf")
//   expiresAt  – Date object or Unix timestamp (seconds)
// Returns a URL‑encoded query string containing path, expires, signature.
// ------------------------------------------------------------------
function sign(path, expiresAt) {
  const expires = typeof expiresAt === 'number'
    ? expiresAt
    : Math.floor((expiresAt instanceof Date ? expiresAt : new Date()).getTime() / 1000);

  const dataToSign = buildSigningString(path, expires);
  const hmac = crypto.createHmac('sha256', SECRET);
  hmac.update(dataToSign);
  const signature = hmac.digest('hex');

  const params = new URLSearchParams({
    path,
    expires: expires.toString(),
    signature,
  });

  // Return only the query portion (no leading '?')
  return params.toString();
}

// ------------------------------------------------------------------
// verify(queryString)
//   queryString – URL query part (may start with '?' or be raw)
// Returns true if the signature is valid and the URL has not expired.
// ------------------------------------------------------------------
function verify(queryString) {
  // Strip leading '?' if present
  const qs = queryString.startsWith('?') ? queryString.slice(1) : queryString;
  const params = new URLSearchParams(qs);

  const path = params.get('path');
  const expires = params.get('expires');
  const signature = params.get('signature');

  // Basic sanity checks
  if (!path || !expires || !signature) return false;

  const expiresNum = Number(expires);
  if (!Number.isFinite(expiresNum) || expiresNum < Math.floor(Date.now() / 1000)) {
    // Expired or invalid timestamp
    return false;
  }

  const expectedData = buildSigningString(path, expiresNum);
  const hmac = crypto.createHmac('sha256', SECRET);
  hmac.update(expectedData);
  const expectedSig = Buffer.from(hmac.digest('hex'), 'utf8');
  const providedSig = Buffer.from(signature, 'utf8');

  // Use constant‑time comparison to avoid timing attacks
  if (expectedSig.length !== providedSig.length) return false;
  return crypto.timingSafeEqual(expectedSig, providedSig);
}

// Export the API
module.exports = {
  sign,
  verify,
};
