// index.js
const express = require('express');
const multer  = require('multer');
const path    = require('path');
const fs      = require('fs');
const mkdirp  = require('mkdirp');

const app = express();
const PORT = process.env.PORT || 3000;

// -------------------------------------------------------------------
// 1️⃣ Ensure the ./uploads directory exists
const UPLOAD_DIR = path.join(__dirname, 'uploads');
mkdirp.sync(UPLOAD_DIR);   // creates the folder if missing

// -------------------------------------------------------------------
// 2️⃣ Configure Multer storage
const storage = multer.diskStorage({
  destination: (req, file, cb) => {
    cb(null, UPLOAD_DIR);
  },
  filename: (req, file, cb) => {
    // Keep the original extension, prepend a timestamp to avoid collisions
    const timestamp = Date.now();
    const ext = path.extname(file.originalname);
    const safeBase = path.basename(file.originalname, ext)
                         .replace(/\s+/g, '_')          // replace spaces
                         .replace(/[^\w.-]/g, '');      // strip unsafe chars
    cb(null, `${timestamp}-${safeBase}${ext}`);
  }
});

// -------------------------------------------------------------------
// 3️⃣ File filter – only allow PDFs and Word docs
const fileFilter = (req, file, cb) => {
  const allowedMimeTypes = [
    'application/pdf',
    // Microsoft Word (old .doc)
    'application/msword',
    // Word (Office Open XML) – .docx, .dotx, etc.
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    'application/vnd.openxmlformats-officedocument.wordprocessingml.template',
  ];

  if (allowedMimeTypes.includes(file.mimetype)) {
    cb(null, true);
  } else {
    cb(
      new multer.MulterError(
        'LIMIT_UNEXPECTED_FILE',
        `Unsupported file type: ${file.mimetype}`
      ),
      false
    );
  }
};

// -------------------------------------------------------------------
// 4️⃣ Set up the Multer middleware
const upload = multer({
  storage,
  fileFilter,
  limits: {
    fileSize: 10 * 1024 * 1024, // 10 MB per file (adjust as needed)
    files: 1                    // only one file per request
  }
});

// -------------------------------------------------------------------
// 5️⃣ Route: POST /upload
app.post('/upload', upload.single('document'), (req, res) => {
  // At this point Multer has already saved the file.
  // If we reach here, the upload succeeded.
  const savedFile = req.file; // Multer adds this object

  // Respond with the stored filename (you could also send the full path)
  res.json({
    success: true,
    storedFileName: savedFile.filename,
    originalName: savedFile.originalname,
    size: savedFile.size,
    mimeType: savedFile.mimetype,
    url: `/uploads/${savedFile.filename}` // optional, for static serving
  });
});

// -------------------------------------------------------------------
// 6️⃣ Global error handler for Multer errors (and any others)
app.use((err, req, res, next) => {
  if (err instanceof multer.MulterError) {
    // Multer‑specific errors
    return res.status(400).json({
      success: false,
      message: err.message,
      code: err.code
    });
  }

  // Generic fallback
  console.error(err);
  res.status(500).json({
    success: false,
    message: 'Internal server error'
  });
});

// -------------------------------------------------------------------
// 7️⃣ (Optional) Serve uploaded files statically
app.use('/uploads', express.static(UPLOAD_DIR));

// -------------------------------------------------------------------
// 8️⃣ Start the server
app.listen(PORT, () => {
  console.log(`🚀 Server listening on http://localhost:${PORT}`);
});
```

