  destination: (req, file, cb) => {
    // Store everything in ./uploads
    cb(null, UPLOAD_DIR);
  },

  // Keep the original name but make it unique to avoid collisions
  filename: (req, file, cb) => {
    // Example: 20230904-163045-abcdef123.pdf
    const timestamp = Date.now();
    const random = Math.random().toString(36).substring(2, 8);
    const ext = path.extname(file.originalname).toLowerCase();
    const safeName = `${timestamp}-${random}${ext}`;
    cb(null, safeName);
  }
});

// -------------------------------------------------
// 3️⃣ File‑type filter (PDF & Word only)
// -------------------------------------------------
const fileFilter = (req, file, cb) => {
  const allowedMime = [
    'application/pdf',
    // Word (old binary format)
    'application/msword',
    // Word (OpenXML – .docx)
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
  ];

  // Some browsers may send generic mime types; fall back to extension check
  const ext = path.extname(file.originalname).toLowerCase();
  const allowedExt = ['.pdf', '.doc', '.docx'];

  if (allowedMime.includes(file.mimetype) && allowedExt.includes(ext)) {
    cb(null, true);
  } else {
    cb(new Error('Only PDF and Word documents (.pdf, .doc, .docx) are allowed'));
  }
};

// -------------------------------------------------
// 4️⃣ Multer middleware instance
// -------------------------------------------------
const upload = multer({
  storage,
  fileFilter,
  limits: {
    fileSize: 10 * 1024 * 1024 // 10 MB per file (adjust as needed)
  }
});

// -------------------------------------------------
// 5️⃣ Route – POST /upload
// -------------------------------------------------
app.post('/upload', upload.single('document'), (req, res) => {
  // If we reach here, the file has been saved successfully
  // `req.file` contains all the info Multer stored
  const storedFileName = req.file.filename;   // the name on disk
  const originalName   = req.file.originalname; // what the user submitted

  res.json({
    success: true,
    message: 'File uploaded successfully',
    storedFileName,
    originalName,
    // you can also return a URL if you plan to serve the file later:
    // fileUrl: `${req.protocol}://${req.get('host')}/uploads/${storedFileName}`
  });
});

// -------------------------------------------------
// 6️⃣ Global error handler (for Multer errors, etc.)
// -------------------------------------------------
app.use((err, req, res, next) => {
  if (err instanceof multer.MulterError) {
    // Multer‑specific errors
    return res.status(400).json({ success: false, error: err.message });
  }

  // Custom or generic errors
  return res.status(400).json({ success: false, error: err.message || 'Unknown error' });
});

// -------------------------------------------------
// 7️⃣ (Optional) Serve uploaded files statically
// -------------------------------------------------
app.use('/uploads', express.static(UPLOAD_DIR));

// -------------------------------------------------
// 8️⃣ Start the server
// -------------------------------------------------
app.listen(PORT, () => {
  console.log(`🚀 Server listening on http://localhost:${PORT}`);
});
