```python
from flask import Flask, request, jsonify, send_from_directory, url_for, abort
from werkzeug.utils import secure_filename
import os

app = Flask(__name__)

# Directory where uploaded avatars will be stored
UPLOAD_FOLDER = os.path.join(os.path.dirname(__file__), 'uploads')
ALLOWED_EXTENSIONS = {'png', 'jpg', 'jpeg'}

os.makedirs(UPLOAD_FOLDER, exist_ok=True)
app.config['UPLOAD_FOLDER'] = UPLOAD_FOLDER


def allowed_file(filename: str) -> bool:
    """Check if the file has an allowed extension."""
    return '.' in filename and \
           filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS


@app.route('/avatar', methods=['POST'])
def upload_avatar():
    """Handle avatar image upload."""
    if 'file' not in request.files:
        return jsonify({'error': 'No file part'}), 400

    file = request.files['file']
    if file.filename == '':
        return jsonify({'error': 'No selected file'}), 400

    if not allowed_file(file.filename):
        return jsonify({'error': 'File type not allowed'}), 400

    filename = secure_filename(file.filename)
    save_path = os.path.join(app.config['UPLOAD_FOLDER'], filename)
    file.save(save_path)

    # Build absolute URL for the uploaded file
    file_url = url_for('uploaded_file', filename=filename, _external=True)
    return jsonify({'url': file_url}), 201


@app.route('/uploads/<filename>', methods=['GET'])
def uploaded_file(filename):
    """Serve uploaded avatar files."""
    if not allowed_file(filename):
        abort(404)
    return send_from_directory(app.config['UPLOAD_FOLDER'], filename)


if __name__ == '__main__':
    # Run the app (debug mode can be turned off in production)
    app.run(host='0.0.0.0', port=5000, debug=True)
