Below is a **stand‑alone `upload.php`** that you can drop into the root of your web site.  
It expects a `POST` request from an HTML form that contains a file input named **`avatar`**.  

The script:

1. Checks that a file was actually uploaded.  
2. Validates the file type (only common image types are allowed).  
3. Generates a safe, unique filename (keeps the original extension).  
4. Moves the file into an **`uploads/`** directory that lives next to `upload.php`.  
5. Prints the public URL of the saved image (or an error message).

> **Important** – Make sure the `uploads/` folder exists and is writable by the web‑server user (e.g. `chmod 0755 uploads` or `chmod 0777 uploads` on some shared hosts).

```php
<?php
/* ---------------------------------------------------------------
 * upload.php
 * ---------------------------------------------------------------
 * Handles a profile picture upload from a form field named "avatar".
 * Saves the file to ./uploads/ and prints the URL of the stored image.
 * --------------------------------------------------------------- */

// ----- CONFIG ----------------------------------------------------
$uploadDir   = __DIR__ . '/uploads/';          // physical path
$maxFileSize = 5 * 1024 * 1024;                // 5 MiB max
$allowedMime = [
    'image/jpeg' => '.jpg',
    'image/pjpeg'=> '.jpg',
    'image/png'  => '.png',
    'image/gif'  => '.gif',
    'image/webp' => '.webp',
];

// ----- HELPERS ---------------------------------------------------
/**
 * Returns the base URL of the current request (scheme + host + optional port).
 */
function baseUrl()
{
    $scheme = (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off')
              ? 'https' : 'http';
    $host   = $_SERVER['HTTP_HOST']; // includes port if non‑standard
    return $scheme . '://' . $host;
}

/**
 * Generates a safe filename: uniqid + original extension.
 */
function generateFileName($extension)
{
    return uniqid('avatar_', true) . $extension;
}

// ----- MAIN -------------------------------------------------------
if ($_SERVER['REQUEST_METHOD'] !== 'POST') {
    http_response_code(405);
    exit('Method Not Allowed – use POST');
}

// Make sure the uploads directory exists
if (!is_dir($uploadDir) && !mkdir($uploadDir, 0755, true)) {
    http_response_code(500);
    exit('Failed to create uploads directory.');
}

// Check that the file field exists
if (!isset($_FILES['avatar'])) {
    http_response_code(400);
    exit('No file uploaded (field name "avatar" missing).');
}

$file = $_FILES['avatar'];

// 1. PHP upload errors
if ($file['error'] !== UPLOAD_ERR_OK) {
    $errors = [
        UPLOAD_ERR_INI_SIZE   => 'The uploaded file exceeds the server limit.',
        UPLOAD_ERR_FORM_SIZE  => 'The uploaded file exceeds the form limit.',
        UPLOAD_ERR_PARTIAL    => 'The file was only partially uploaded.',
        UPLOAD_ERR_NO_FILE    => 'No file was uploaded.',
        UPLOAD_ERR_NO_TMP_DIR => 'Missing a temporary folder.',
        UPLOAD_ERR_CANT_WRITE => 'Failed to write file to disk.',
        UPLOAD_ERR_EXTENSION  => 'A PHP extension stopped the file upload.',
    ];
    $msg = $errors[$file['error']] ?? 'Unknown upload error.';
    http_response_code(400);
    exit($msg);
}

// 2. Size check
if ($file['size'] > $maxFileSize) {
    http_response_code(400);
    exit('File is too large. Max size: ' . ($maxFileSize / (1024 * 1024)) . ' MiB');
}

// 3. MIME type check (using finfo)
$finfo = new finfo(FILEINFO_MIME_TYPE);
$mime  = $finfo->file($file['tmp_name']);

if (!array_key_exists($mime, $allowedMime)) {
    http_response_code(400);
    exit('Invalid file type. Only JPEG, PNG, GIF and WebP are allowed.');
}

// 4. Build a safe destination filename
$extension = $allowedMime[$mime];
$destName  = generateFileName($extension);
$destPath  = $uploadDir . $destName;

// 5. Move the uploaded file
if (!move_uploaded_file($file['tmp_name'], $destPath)) {
    http_response_code(500);
    exit('Failed to move uploaded file.');
}

// 6. Build the public URL
$publicUrl = baseUrl() . dirname($_SERVER['SCRIPT_NAME']) . '/uploads/' . $destName;

// Output the URL (you can change this to JSON, HTML, etc.)
header('Content-Type: text/plain');
echo $publicUrl;
?>
