if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_FILES['avatar'])) {
    // Directory where files will be stored (relative to this script)
    $uploadDir = __DIR__ . '/uploads/';

    // Ensure the upload directory exists
    if (!is_dir($uploadDir)) {
        mkdir($uploadDir, 0755, true);
    }

    $file = $_FILES['avatar'];

    // Basic upload error handling
    if ($file['error'] !== UPLOAD_ERR_OK) {
        http_response_code(400);
        echo 'Upload error.';
        exit;
    }

    // Allow only common image MIME types
    $allowedMime = ['image/jpeg', 'image/png', 'image/gif', 'image/webp'];
    $finfo      = new finfo(FILEINFO_MIME_TYPE);
    $mime       = $finfo->file($file['tmp_name']);

    if (!in_array($mime, $allowedMime, true)) {
        http_response_code(400);
        echo 'Invalid file type.';
        exit;
    }

    // Generate a safe, unique filename
    $ext        = strtolower(pathinfo($file['name'], PATHINFO_EXTENSION));
    $uniqueName = bin2hex(random_bytes(8)) . '.' . $ext;
    $destPath   = $uploadDir . $uniqueName;

    // Move the uploaded file to the target directory
    if (!move_uploaded_file($file['tmp_name'], $destPath)) {
        http_response_code(500);
        echo 'Failed to save file.';
        exit;
    }

    // Build the public URL of the saved image
    $scheme    = (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off') ? 'https' : 'http';
    $host      = $_SERVER['HTTP_HOST'];
    $scriptDir = rtrim(dirname($_SERVER['SCRIPT_NAME']), '/\\');
    $url       = $scheme . '://' . $host . $scriptDir . '/uploads/' . $uniqueName;

    echo $url;
} else {
    http_response_code(405);
    echo 'Invalid request.';
}
?>
