## 2. `server.js`

```js
// server.js
const express = require('express');
const multer  = require('multer');
const fs      = require('fs');
const path    = require('path');

const app = express();
const PORT = process.env.PORT || 3000;

// -------------------------------------------------
// 1️⃣ Ensure ./uploads directory exists
// -------------------------------------------------
const uploadDir = path.join(__dirname, 'uploads');
if (!fs.existsSync(uploadDir)) {
  fs.mkdirSync(uploadDir, { recursive: true });
}

// -------------------------------------------------
// 2️⃣ Multer storage configuration
// -------------------------------------------------
const storage = multer.diskStorage({
  destination: (req, file, cb) => {
    // Files will be saved in ./uploads
    cb(null, uploadDir);
  },
  filename: (req, file, cb) => {
    // Keep the original name but make it unique with a timestamp
    const timestamp = Date.now();
    const ext = path.extname(file.originalname);
    const base = path.basename(file.originalname, ext).replace(/\s+/g, '_');
    cb(null, `${base}-${timestamp}${ext}`);
  }
});

// -------------------------------------------------
// 3️⃣ File filter – only PDF & Word docs allowed
// -------------------------------------------------
const fileFilter = (req, file, cb) => {
  const allowedMime = [
    'application/pdf',
    'application/msword',                     // .doc
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document' // .docx
  ];

  if (allowedMime.includes(file.mimetype)) {
    cb(null, true);
  } else {
    cb(new Error('Only PDF and Word documents are allowed!'), false);
  }
};

// -------------------------------------------------
// 4️⃣ Multer middleware
// -------------------------------------------------
const upload = multer({
  storage,
  fileFilter,
  limits: {
    fileSize: 10 * 1024 * 1024 // 10 MB per file (adjust as needed)
  }
});

// -------------------------------------------------
// 5️⃣ Route: POST /upload
// -------------------------------------------------
app.post('/upload', upload.single('document'), (req, res) => {
  // If we reach here, multer already saved the file.
  // req.file contains info about the stored file.
  if (!req.file) {
    // This should rarely happen because multer would have thrown earlier,
    // but we guard against it.
    return res.status(400).json({ error: 'No file was uploaded.' });
  }

  // Return the stored filename (the one on disk)
  res.json({
    message: 'File uploaded successfully.',
    filename: req.file.filename,
    originalName: req.file.originalname,
    size: req.file.size,
    mimetype: req.file.mimetype,
    path: req.file.path
  });
});

// -------------------------------------------------
// 6️⃣ Global error handler (for Multer & others)
// -------------------------------------------------
app.use((err, req, res, next) => {
  console.error(err);
  if (err instanceof multer.MulterError) {
    // Multer‑specific errors
    return res.status(400).json({ error: err.message });
  }
  // Custom errors (e.g., from fileFilter)
  return res.status(400).json({ error: err.message || 'Something went wrong.' });
});

// -------------------------------------------------
// 7️⃣ Start the server
// -------------------------------------------------
app.listen(PORT, () => {
  console.log(`🚀 Server listening on http://localhost:${PORT}`);
});
```

