const express = require('express');
const multer  = require('multer');
const fs      = require('fs');
const path    = require('path');

const app = express();
const PORT = process.env.PORT || 3000;

// -------------------------------------------------------------------
// 1️⃣ Ensure the ./uploads directory exists (create it if missing)
// -------------------------------------------------------------------
const UPLOAD_DIR = path.join(__dirname, 'uploads');

if (!fs.existsSync(UPLOAD_DIR)) {
  fs.mkdirSync(UPLOAD_DIR, { recursive: true });
  console.log(`Created uploads folder at ${UPLOAD_DIR}`);
}

// -------------------------------------------------------------------
// 2️⃣ Multer storage configuration
// -------------------------------------------------------------------
const storage = multer.diskStorage({
  // Destination folder
  destination: (req, file, cb) => {
    cb(null, UPLOAD_DIR);
  },

  // File name on disk – keep original name but make it unique
  filename: (req, file, cb) => {
    // Remove spaces & sanitize a little
    const safeBase = file.originalname
      .replace(/\s+/g, '_')
      .replace(/[^\w.\-]/g, '');

    // Append a timestamp to avoid collisions
    const timestamp = Date.now();
    const ext = path.extname(safeBase);
    const nameWithoutExt = path.basename(safeBase, ext);

    const finalName = `${nameWithoutExt}-${timestamp}${ext}`;
    cb(null, finalName);
  }
});

// -------------------------------------------------------------------
// 3️⃣ File filter – only allow PDF & Word docs
// -------------------------------------------------------------------
const fileFilter = (req, file, cb) => {
  const allowedMime = [
    'application/pdf',
    // Word (old binary format)
    'application/msword',
    // Word (OpenXML format)
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
  ];

  if (allowedMime.includes(file.mimetype)) {
    cb(null, true);
  } else {
    cb(
      new multer.MulterError(
        'LIMIT_UNEXPECTED_FILE',
        'Only PDF and Word documents are allowed.'
      ),
      false
    );
  }
};

// -------------------------------------------------------------------
// 4️⃣ Multer middleware instance
// -------------------------------------------------------------------
const upload = multer({
  storage,
  fileFilter,
  limits: {
    fileSize: 10 * 1024 * 1024 // 10 MB max per file (adjust as needed)
  }
});

// -------------------------------------------------------------------
// 5️⃣ Route: POST /upload
// -------------------------------------------------------------------
app.post('/upload', upload.single('document'), (req, res) => {
  // If we reach here, Multer already saved the file.
  // `req.file` contains the details.
  if (!req.file) {
    return res.status(400).json({ error: 'No file was uploaded.' });
  }

  // Respond with the stored filename (you could also send the whole file object)
  res.json({
    message: 'File uploaded successfully.',
    storedFileName: req.file.filename,
    originalName: req.file.originalname,
    size: req.file.size,
    mimeType: req.file.mimetype,
    path: req.file.path
  });
});

// -------------------------------------------------------------------
// 6️⃣ Global error handler (to catch Multer errors)
// -------------------------------------------------------------------
app.use((err, req, res, next) => {
  if (err instanceof multer.MulterError) {
    // A Multer-specific error occurred.
    let message = err.message;
    if (err.code === 'LIMIT_FILE_SIZE') {
      message = 'File too large. Max size is 10 MB.';
    } else if (err.code === 'LIMIT_UNEXPECTED_FILE') {
      message = err.message; // custom message from fileFilter
    }
    return res.status(400).json({ error: message });
  }

  // Anything else
  console.error(err);
  res.status(500).json({ error: 'Internal server error.' });
});

// -------------------------------------------------------------------
// 7️⃣ Start the server
// -------------------------------------------------------------------
app.listen(PORT, () => {
  console.log(`🚀 Server listening on http://localhost:${PORT}`);
});
