    """Execute the deployment script with the given branch."""
    return subprocess.run(
        ["./deploy.sh", branch],
        check=False,               # don't raise, handle result manually
        capture_output=True,
        text=True,
    )


@app.post("/github/webhook")
async def github_webhook(request: Request):
    """
    GitHub push webhook handler.
    Triggers ./deploy.sh <branch> only for pushes to the `main` branch.
    """
    payload = await request.json()

    # Ensure this is a push event
    if payload.get("hook") is None and payload.get("ref") is None:
        raise HTTPException(status_code=400, detail="Invalid GitHub payload")

    # Extract branch name from ref (e.g., "refs/heads/main")
    ref: str = payload.get("ref", "")
    branch = ref.split("/")[-1] if ref else ""

    if branch != "main":
        # Not the branch we care about – ignore silently
        return JSONResponse(content={"status": "ignored", "branch": branch})

    # Run deployment script
    result = run_deploy(branch)

    if result.returncode != 0:
        # Deployment failed – include stderr for debugging
        return JSONResponse(
            status_code=500,
            content={
                "status": "error",
                "branch": branch,
                "error": result.stderr.strip(),
            },
        )

    # Success
    return JSONResponse(
        content={
            "status": "deployed",
            "branch": branch,
            "output": result.stdout.strip(),
        }
