# main.py
from fastapi import FastAPI, Request, HTTPException, Header
import subprocess
import hmac
import hashlib
import os

app = FastAPI()

# Optional: GitHub webhook secret (set as env var)
WEBHOOK_SECRET = os.getenv("GITHUB_WEBHOOK_SECRET", "")


def verify_signature(payload: bytes, signature: str) -> bool:
    """Validate GitHub HMAC signature."""
    if not WEBHOOK_SECRET:
        return True  # No secret configured, skip verification
    sha_name, signature = signature.split("=")
    if sha_name != "sha256":
        return False
    mac = hmac.new(WEBHOOK_SECRET.encode(), msg=payload, digestmod=hashlib.sha256)
    return hmac.compare_digest(mac.hexdigest(), signature)


@app.post("/github/webhook")
async def github_webhook(request: Request, x_github_event: str = Header(...), x_hub_signature_256: str = Header(None)):
    """Handle GitHub push events and trigger deployment for the main branch."""
    payload = await request.body()

    # Verify signature if secret is set
    if WEBHOOK_SECRET and not verify_signature(payload, x_hub_signature_256 or ""):
        raise HTTPException(status_code=401, detail="Invalid signature")

    # Only process push events
    if x_github_event != "push":
        return {"msg": "Event ignored"}

    data = await request.json()

    # Extract branch name from ref (e.g., "refs/heads/main")
    ref = data.get("ref", "")
    if not ref.startswith("refs/heads/"):
        return {"msg": "Ref not a branch"}

    branch = ref.removeprefix("refs/heads/")

    # Deploy only for main branch
    if branch != "main":
        return {"msg": f"Ignored branch {branch}"}

    # Run deployment script
    try:
        result = subprocess.run(
            ["./deploy.sh", branch],
            check=True,
            capture_output=True,
            text=True,
        )
        return {
            "msg": "Deployment started",
            "stdout": result.stdout,
            "stderr": result.stderr,
        }
    except subprocess.CalledProcessError as exc:
        raise HTTPException(
            status_code=500,
            detail=f"Deployment failed: {exc.stderr}",
        )
