# main.py
from fastapi import FastAPI, Request, HTTPException
from fastapi.responses import JSONResponse
import subprocess
import asyncio

app = FastAPI()


async def run_deploy(branch: str) -> int:
    """
    Execute ./deploy.sh with the branch name.
    Returns the subprocess exit code.
    """
    # Use a thread pool to avoid blocking the event loop
    loop = asyncio.get_event_loop()
    return await loop.run_in_executor(
        None,
        lambda: subprocess.run(["./deploy.sh", branch], check=False).returncode,
    )


@app.post("/github/webhook")
async def github_webhook(request: Request):
    """
    GitHub push webhook endpoint.
    Triggers ./deploy.sh <branch> only for pushes to the main branch.
    """
    # Verify that the payload is JSON
    try:
        payload = await request.json()
    except Exception:
        raise HTTPException(status_code=400, detail="Invalid JSON payload")

    # Ensure this is a push event (GitHub always sends X-GitHub-Event header)
    event = request.headers.get("X-GitHub-Event")
    if event != "push":
        return JSONResponse(
            {"msg": f"Ignored event type '{event}'"}, status_code=200
        )

    # Extract branch name from the ref field: "refs/heads/<branch>"
    ref = payload.get("ref", "")
    if not ref.startswith("refs/heads/"):
        return JSONResponse({"msg": "Invalid ref format"}, status_code=400)

    branch = ref.removeprefix("refs/heads/")

    # Only trigger deployment for the main branch
    if branch != "main":
        return JSONResponse(
            {"msg": f"Ignored push to branch '{branch}'"}, status_code=200
        )

    # Run the deployment script
    exit_code = await run_deploy(branch)

    if exit_code == 0:
        return JSONResponse({"msg": "Deployment started"}, status_code=202)
    else:
        return JSONResponse(
            {"msg": "Deployment failed", "exit_code": exit_code},
            status_code=500,
        )
