from fastapi import FastAPI, Request, HTTPException, Header
import subprocess
import hmac
import hashlib

app = FastAPI()

# Optional: set your GitHub webhook secret here for payload verification
GITHUB_WEBHOOK_SECRET = b"your_secret_here"  # replace with actual secret or set to None


def verify_signature(body: bytes, signature_header: str) -> bool:
    """Verify X-Hub-Signature-256 using the shared secret."""
    if not signature_header:
        return False
    sha_name, signature = signature_header.split("=")
    if sha_name != "sha256":
        return False
    mac = hmac.new(GITHUB_WEBHOOK_SECRET, body, hashlib.sha256)
    return hmac.compare_digest(mac.hexdigest(), signature)


@app.post("/github/webhook")
async def github_webhook(
    request: Request,
    x_github_event: str = Header(..., alias="X-GitHub-Event"),
    x_hub_signature_256: str = Header(None, alias="X-Hub-Signature-256"),
):
    """
    Receive GitHub push events. If the push is to the `main` branch,
    execute `./deploy.sh main`.
    """
    # Verify payload signature if a secret is configured
    if GITHUB_WEBHOOK_SECRET:
        body = await request.body()
        if not verify_signature(body, x_hub_signature_256):
            raise HTTPException(status_code=401, detail="Invalid signature")
        payload = request.json()  # will re‑parse the body
    else:
        payload = await request.json()

    # Only handle push events
    if x_github_event != "push":
        raise HTTPException(status_code=400, detail="Unsupported event type")

    ref = payload.get("ref")
    # GitHub uses full ref name, e.g. refs/heads/main
    if ref != "refs/heads/main":
        return {"message": "Push to non‑main branch ignored"}

    # Trigger deployment
    try:
        result = subprocess.run(
            ["./deploy.sh", "main"],
            capture_output=True,
            text=True,
            check=True,
        )
    except subprocess.CalledProcessError as exc:
        raise HTTPException(
            status_code=500,
            detail=f"Deployment failed: {exc.stderr.strip()}",
        )

    return {
        "message": "Deployment triggered",
        "stdout": result.stdout.strip(),
    }
