// 4. Verify MIME type (using finfo, not just the client‑supplied type)
// -----------------------------------------------------------------
$finfo = new finfo(FILEINFO_MIME_TYPE);
$mime  = $finfo->file($file['tmp_name']);

if (!array_key_exists($mime, $allowedMimeTypes)) {
    http_response_code(400);
    die('Invalid file type. Only JPEG, PNG and GIF images are allowed.');
}

// -----------------------------------------------------------------
// 5. Build a safe, unique filename
// -----------------------------------------------------------------
$ext      = $allowedMimeTypes[$mime];
$basename = bin2hex(random_bytes(12)); // 24‑char random string
$filename = $basename . $ext;
$target   = $uploadDir . '/' . $filename;

// -----------------------------------------------------------------
// 6. Move the uploaded file to its final destination
// -----------------------------------------------------------------
if (!move_uploaded_file($file['tmp_name'], $target)) {
    http_response_code(500);
    die('Failed to move uploaded file.');
}

