// 7. Output the public URL
// -----------------------------------------------------------------
$protocol = (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off'
            || $_SERVER['SERVER_PORT'] == 443) ? "https://" : "http://";

$host = $_SERVER['HTTP_HOST']; // includes port if non‑standard

// URL to the uploads directory relative to the web root
$uploadsUrlPath = $webRoot . '/uploads/' . $filename;

// Full absolute URL (nice for copying/pasting)
$fullUrl = $protocol . $host . $uploadsUrlPath;

header('Content-Type: text/plain');
echo $fullUrl;
