// ------------------------------------------------------------
//  POST /payments/callback
//  Expected JSON payload from the provider:
//  {
//      "orderId": "12345",
//      "amount": 1999,               // in cents (or whatever your currency unit is)
//      "status": "PAID",             // other possible values: "FAILED", "PENDING", …
//      "signature": "a1b2c3d4…"      // HMAC‑SHA256 of the payload (see below)
//  }
// ------------------------------------------------------------

const express = require('express');
const crypto = require('crypto');
const router = express.Router();

// ---------------------------------------------------------------------
//  Helper – verify the HMAC‑SHA256 signature sent by the provider.
//  The provider builds the signature from the *raw* request body
//  (the JSON string) using the shared secret.
// ---------------------------------------------------------------------
function verifySignature(rawBody, signature, secret) {
  // Compute HMAC‑SHA256 of the raw request body
  const hmac = crypto.createHmac('sha256', secret);
  hmac.update(rawBody, 'utf8');
  const expected = hmac.digest('hex');

  // Use a timing‑safe comparison to avoid side‑channel attacks
  return crypto.timingSafeEqual(
    Buffer.from(expected, 'hex'),
    Buffer.from(signature, 'hex')
  );
}

// ---------------------------------------------------------------------
//  POST /payments/callback
// ---------------------------------------------------------------------
router.post(
  '/payments/callback',
  // Express' built‑in JSON parser gives us both the parsed object
  // (req.body) **and** the raw string (if we capture it with a verify fn)
  express.json({
    verify: (req, res, buf) => {
      // Store the raw body on the request so we can verify the signature later
      req.rawBody = buf.toString('utf8');
    },
  }),
  async (req, res) => {
    const { orderId, amount, status, signature } = req.body;

    // -----------------------------------------------------------------
    //  1️⃣  Basic validation – make sure the required fields exist
    // -----------------------------------------------------------------
    if (!orderId || !amount || !status || !signature) {
      console.warn('⚠️  Invalid callback payload – missing fields');
      return res.status(400).json({ error: 'Invalid payload' });
    }

    // -----------------------------------------------------------------
    //  2️⃣  Verify the HMAC signature
    // -----------------------------------------------------------------
    const secret = process.env.PAYMENT_SECRET;
    if (!secret) {
      console.error('❌  PAYMENT_SECRET is not set in the environment');
      return res.status(500).json({ error: 'Server configuration error' });
    }

    try {
      const isValid = verifySignature(req.rawBody, signature, secret);
      if (!isValid) {
        console.warn(`⚠️  Signature verification failed for order ${orderId}`);
        return res.status(401).json({ error: 'Invalid signature' });
      }
    } catch (err) {
      // If the signature format is wrong crypto.timingSafeEqual throws
      console.warn(`⚠️  Signature verification error for order ${orderId}:`, err);
      return res.status(400).json({ error: 'Bad signature format' });
    }

    // -----------------------------------------------------------------
    //  3️⃣  Process the payment status
    // -----------------------------------------------------------------
    if (status === 'PAID') {
      try {
        // Assume db.markOrderPaid returns a promise and throws on error
        await db.markOrderPaid(orderId, amount); // you may also want to store amount
        console.info(`✅  Order ${orderId} marked as PAID`);
        // Respond with 200 so the provider knows we processed it
        return res.json({ result: 'ok' });
      } catch (dbErr) {
        console.error(`❌  DB error while marking order ${orderId} paid:`, dbErr);
        // 500 tells the provider that we couldn't process the callback – they may retry
        return res.status(500).json({ error: 'Database error' });
      }
    }

    // -----------------------------------------------------------------
    //  4️⃣  Non‑PAID statuses – just acknowledge (or handle as needed)
    // -----------------------------------------------------------------
    console.info(`ℹ️  Received status ${status} for order ${orderId}. No DB update performed.`);
    return res.json({ result: 'ignored', status });
  }
);

module.exports = router;
