// ------------------------------------------------------------

require('dotenv').config();          // loads process.env.PAYMENT_SECRET from .env
const express = require('express');
const crypto = require('crypto');

const router = express.Router();

/**
 * Helper – verify the HMAC‑SHA256 signature.
 *
 * The provider’s spec usually tells you exactly how the signature
 * is calculated. A common approach is:
 *
 *   signature = HMAC_SHA256(secret, `${orderId}|${amount}|${status}`)
 *
 * Adjust the `payloadString` construction if your provider uses a
 * different delimiter or includes additional fields.
 *
 * @param {Object} body   The parsed JSON body.
 * @param {string} secret Shared secret (process.env.PAYMENT_SECRET).
 * @returns {boolean}     True if the signature matches.
 */
function verifySignature(body, secret) {
  const { orderId, amount, status, signature } = body;

  // Defensive: make sure we have everything we need.
  if (!orderId || !amount || !status || !signature) return false;

  // Build the exact string the provider signed.
  const payloadString = `${orderId}|${amount}|${status}`;

  // Compute HMAC‑SHA256.
  const expected = crypto
    .createHmac('sha256', secret)
    .update(payloadString, 'utf8')
    .digest('hex');

  // Use a timing‑safe comparison.
  return crypto.timingSafeEqual(
    Buffer.from(expected, 'hex'),
    Buffer.from(signature, 'hex')
  );
}

/**
 * POST /payments/callback
 *
 * Expected JSON body:
 * {
 *   "orderId": "12345",
 *   "amount": "49.99",
 *   "status": "PAID",          // or other statuses like "FAILED"
 *   "signature": "ab12cd34..." // hex‑encoded HMAC‑SHA256
 * }
 */
router.post('/payments/callback', async (req, res) => {
  const secret = process.env.PAYMENT_SECRET;

  if (!secret) {
    console.error('PAYMENT_SECRET is not set');
    return res.status(500).json({ error: 'Server configuration error' });
  }

  // Ensure we have JSON – Express's json middleware should already have parsed it.
  const payload = req.body;

  // Basic validation.
  const requiredFields = ['orderId', 'amount', 'status', 'signature'];
  const missing = requiredFields.filter((f) => !(f in payload));
  if (missing.length) {
    return res.status(400).json({ error: `Missing fields: ${missing.join(', ')}` });
  }

  // Verify the signature.
  if (!verifySignature(payload, secret)) {
    return res.status(401).json({ error: 'Invalid signature' });
  }

  // At this point the request is authentic.
  const { orderId, status } = payload;

  if (status === 'PAID') {
    try {
      // Assume db.markOrderPaid returns a Promise.
      await db.markOrderPaid(orderId);
      console.info(`Order ${orderId} marked as PAID`);
      return res.status(200).json({ result: 'ok' });
    } catch (err) {
      console.error(`Failed to mark order ${orderId} as paid:`, err);
      return res.status(500).json({ error: 'Database error' });
    }
  }

  // If we get here the status is something else (e.g., FAILED, PENDING)
  console.info(`Callback received for order ${orderId} with status ${status}`);
  return res.status(200).json({ result: 'ignored', status });
});

