Below is a **stand‑alone** example of an Express.js route that can be dropped into any existing Express app (or used as a tiny micro‑service).  

It:

1. **Parses JSON** sent by the payment provider.  
2. **Verifies the HMAC‑SHA256 signature** that the provider includes in the `signature` field.  
3. If the signature is valid **and** `status === "PAID"` it calls the assumed `db.markOrderPaid(orderId)` helper.  
4. Returns a JSON response (`200 OK` on success, `400/401` on error) so the provider knows the callback was processed.

```javascript
// paymentsCallback.js
require('dotenv').config();          // loads process.env.PAYMENT_SECRET from .env
const express = require('express');
const crypto = require('crypto');
const router = express.Router();

// -------------------------------------------------------------------
// Helper: verify the HMAC‑SHA256 signature
// -------------------------------------------------------------------
/**
 * @param {Object} payload   The raw JSON body (already parsed by express.json())
 * @param {string} signature The signature string sent by the provider
 * @returns {boolean}        true if the signature matches
 */
function isValidSignature(payload, signature) {
  // The provider usually signs a deterministic string.
  // A common pattern is to sign the JSON stringified payload *without* the signature field.
  // Adjust the algorithm to match the provider's docs.
  const { signature: _ignore, ...dataToSign } = payload; // remove signature field
  const payloadString = JSON.stringify(dataToSign); // deterministic order is important

  const hmac = crypto.createHmac('sha256', process.env.PAYMENT_SECRET);
  hmac.update(payloadString);
  const expected = hmac.digest('hex');

  // Some providers send the signature in base64 – handle both cases:
  const normalizedSignature = signature.trim().toLowerCase();
  const normalizedExpected = expected.trim().toLowerCase();

  return normalizedSignature === normalizedExpected;
}

// -------------------------------------------------------------------
// Route: POST /payments/callback
// -------------------------------------------------------------------
router.post('/payments/callback', async (req, res) => {
  const { orderId, amount, status, signature } = req.body || {};

  // -----------------------------------------------------------------
  // Basic validation
  // -----------------------------------------------------------------
  if (!orderId || !status || !signature) {
    return res.status(400).json({
      error: 'Missing required fields (orderId, status, signature).',
    });
  }

  // -----------------------------------------------------------------
  // Verify signature
  // -----------------------------------------------------------------
  if (!isValidSignature(req.body, signature)) {
    // Do NOT expose the secret or detailed reason – just reject.
    return res.status(401).json({ error: 'Invalid signature.' });
  }

  // -----------------------------------------------------------------
  // Process the payment status
  // -----------------------------------------------------------------
  try {
    if (status === 'PAID') {
      // Assume db.markOrderPaid returns a promise.
      await db.markOrderPaid(orderId);
      console.log(`✅ Order ${orderId} marked as PAID (amount: ${amount}).`);
    } else {
      // For other statuses you may want to log or handle them differently.
      console.log(`ℹ️ Received callback for order ${orderId} with status "${status}".`);
    }

    // Respond with a success acknowledgement so the provider knows we processed it.
    return res.status(200).json({ received: true });
  } catch (err) {
    console.error(`❌ Error processing callback for order ${orderId}:`, err);
    // Do not leak internal errors to the provider – just a generic 500.
    return res.status(500).json({ error: 'Internal server error.' });
  }
});

module.exports = router;
```

