   * @returns {Promise<void>}
   */
  async markOrderPaid(orderId) {
    // Example implementation – you will probably do a SQL UPDATE or
    // a MongoDB findOneAndUpdate here.
    console.log(`🟢  Order ${orderId} marked as PAID in the DB`);
    // Throw if something goes wrong so the caller can catch it.
  }
};

// ------------------------------------------------------------------
// Helper: verify the HMAC signature sent by the provider.
// ------------------------------------------------------------------
/**
 * The provider signs the request body (excluding the `signature` field)
 * using HMAC‑SHA256 with the shared secret.
 *
 * @param {object} payload   The parsed JSON body (including signature)
 * @param {string} secret    Shared secret (process.env.PAYMENT_SECRET)
 * @returns {boolean}        true if the signature matches
 */
function isValidSignature(payload, secret) {
  // 1️⃣  Pull the signature out of the payload.
  const { signature, ...signedPart } = payload;
  if (!signature) return false;

  // 2️⃣  Re‑create the canonical string that the provider signed.
  //     Most providers ask you to concatenate the fields in a fixed order.
  //     Adjust this to match the provider’s spec.
  const signingString = `${signedPart.orderId}|${signedPart.amount}|${signedPart.status}`;

  // 3️⃣  Compute HMAC‑SHA256 using the shared secret.
  const hmac = crypto.createHmac('sha256', secret);
  hmac.update(signingString);
  const expectedSignature = hmac.digest('hex');

  // 4️⃣  Constant‑time comparison to avoid timing attacks.
  return crypto.timingSafeEqual(
    Buffer.from(expectedSignature, 'utf8'),
    Buffer.from(signature, 'utf8')
  );
}

// ------------------------------------------------------------------
// Express app & middleware
// ------------------------------------------------------------------
const app = express();

// Parse JSON bodies (the provider sends JSON)
app.use(bodyParser.json());

// ------------------------------------------------------------------
// POST /payments/callback
// ------------------------------------------------------------------
