  const payload = req.body;

  // Basic sanity check – ensure required fields exist.
  const requiredFields = ['orderId', 'amount', 'status', 'signature'];
  const missing = requiredFields.filter(f => !(f in payload));
  if (missing.length) {
    console.warn('❌  Callback missing fields:', missing);
    return res.status(400).json({ error: `Missing fields: ${missing.join(', ')}` });
  }

  // Verify the signature.
  const secret = process.env.PAYMENT_SECRET;
  if (!secret) {
    console.error('❌  PAYMENT_SECRET not configured');
    return res.status(500).json({ error: 'Server mis‑configuration' });
  }

  if (!isValidSignature(payload, secret)) {
    console.warn('❌  Invalid signature for order', payload.orderId);
    return res.status(401).json({ error: 'Invalid signature' });
  }

  // At this point the request is authentic.
  const { orderId, status } = payload;

  // Process only PAID statuses – ignore others (e.g., FAILED, PENDING).
  if (status === 'PAID') {
    try {
      await db.markOrderPaid(orderId);
      // Respond with 200 so the provider knows we processed it.
      return res.status(200).json({ received: true });
    } catch (err) {
      console.error('❌  DB error while marking order paid:', err);
      // The provider may retry, so we return a 5xx.
      return res.status(500).json({ error: 'Database error' });
    }
  }

  // If the status is something else we simply acknowledge it.
  console.info(`ℹ️  Received callback for order ${orderId} with status ${status} – no action taken`);
  return res.status(200).json({ received: true });
});

