const express = require('express');
const crypto = require('crypto');
const router = express.Router();
const db = require('./db'); // assumes db.markOrderPaid(orderId) exists

// Capture raw request body for signature verification
router.use(
  express.json({
    verify: (req, res, buf) => {
      req.rawBody = buf; // store raw buffer on request
    },
  })
);

// POST /payments/callback
router.post('/payments/callback', async (req, res) => {
  const { orderId, amount, status, signature } = req.body;
  const secret = process.env.PAYMENT_SECRET;

  // Basic validation
  if (!orderId || !status || !signature) {
    return res.status(400).json({ error: 'Missing required fields' });
  }

  // Compute HMAC‑SHA256 over the raw JSON payload (excluding the signature field)
  // Assuming the provider signs the entire JSON string without the signature key.
  const payload = JSON.parse(req.rawBody.toString());
  delete payload.signature; // remove signature before recomputing
  const computed = crypto
    .createHmac('sha256', secret)
    .update(JSON.stringify(payload))
    .digest('hex');

  // Compare signatures (use timing‑safe compare)
  const signaturesMatch = crypto.timingSafeEqual(
    Buffer.from(computed, 'hex'),
    Buffer.from(signature, 'hex')
  );

  if (!signaturesMatch) {
    return res.status(401).json({ error: 'Invalid signature' });
  }

  // If payment succeeded, mark order as paid
  if (status === 'PAID') {
    try {
      await db.markOrderPaid(orderId);
      return res.json({ result: 'OK' });
    } catch (err) {
      console.error('Failed to mark order paid:', err);
      return res.status(500).json({ error: 'Database error' });
    }
  }

  // For other statuses just acknowledge receipt
  res.json({ result: 'Ignored' });
});

module.exports = router;
