 * or an appropriate HTTP error code on failure.
 */

declare(strict_types=1);

// ---------------------------------------------------------------------
// Helper: send HTTP response and exit
function respond(int $code, string $msg): void
{
    http_response_code($code);
    header('Content-Type: text/plain; charset=utf-8');
    echo $msg;
    exit;
}

// ---------------------------------------------------------------------
// 1. Retrieve POST data safely
$orderId = filter_input(INPUT_POST, 'order_id', FILTER_SANITIZE_STRING);
$amount  = filter_input(INPUT_POST, 'amount', FILTER_SANITIZE_STRING);
$status  = filter_input(INPUT_POST, 'status', FILTER_SANITIZE_STRING);
$sig     = filter_input(INPUT_POST, 'sig', FILTER_SANITIZE_STRING);

if ($orderId === null || $amount === null || $status === null || $sig === null) {
    respond(400, 'Missing required parameters.');
}

// Trim whitespace (just in case)
$orderId = trim($orderId);
$amount  = trim($amount);
$status  = trim($status);
$sig     = trim($sig);

// ---------------------------------------------------------------------
// 2. Verify signature
$secret = getenv('GATEWAY_SECRET');
if ($secret === false) {
    // Configuration error – do NOT expose internal details to the gateway
    respond(500, 'Server configuration error.');
}

/**
 * Expected signature algorithm:
 *   HMAC‑SHA256 of the concatenated string: order_id + amount + status
 *   using the shared secret.
 *
 * Adjust the algorithm if your gateway uses a different scheme.
 */
$payload   = $orderId . $amount . $status;
$calcSig   = hash_hmac('sha256', $payload, $secret);
$calcSig   = strtolower($calcSig);          // ensure case‑insensitive compare
$provided  = strtolower($sig);

if (!hash_equals($calcSig, $provided)) {
    respond(403, 'Invalid signature.');
}

// ---------------------------------------------------------------------
// 3. Process only completed payments
if (strtolower($status) !== 'completed') {
    // Nothing to do – acknowledge receipt so the gateway does not retry
    respond(200, 'Notification received (status not completed).');
}

// ---------------------------------------------------------------------
// 4. Update the order in the database
$dsn  = getenv('DB_DSN');
$user = getenv('DB_USER');
$pass = getenv('DB_PASS');

if ($dsn === false || $user === false) {
    respond(500, 'Database configuration missing.');
}

try {
    $pdo = new PDO($dsn, $user, $pass, [
        PDO::ATTR_ERRMODE            => PDO::ERRMODE_EXCEPTION,
        PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,
    ]);
} catch (PDOException $e) {
    // Log the error internally, but do not expose details to the gateway
    error_log('Database connection failed: ' . $e->getMessage());
    respond(500, 'Database connection error.');
}

// Use a prepared statement to avoid SQL injection
$sql = 'UPDATE orders SET paid = 1 WHERE order_id = :order_id';
$stmt = $pdo->prepare($sql);

try {
    $stmt->execute([':order_id' => $orderId]);

    // Check whether any row was actually updated (order might not exist)
    if ($stmt->rowCount() === 0) {
        // Order not found – still return 200 so the gateway stops retrying,
        // but you may want to log this situation.
        error_log("IPN: order_id {$orderId} not found.");
        respond(200, 'Order not found.');
    }

    // Success
    respond(200, 'Payment recorded.');
} catch (PDOException $e) {
    error_log('SQL error: ' . $e->getMessage());
    respond(500, 'Database query error.');
}
