if ($secret === false) {
    logError('GATEWAY_SECRET not defined in environment');
    respond(500, 'Server configuration error');
}

// Re‑create the signature exactly as the gateway does.
// The format (order_id:amount:status) is a common simple pattern – adjust if your gateway uses a different scheme.
