1. **Place the file** where your web server can execute it (e.g., `public_html/ipn.php`).
2. **Set environment variables** on the server (via `.env`, Apache `SetEnv`, Nginx `fastcgi_param`, Docker, etc.):

   ```bash
   export GATEWAY_SECRET="your‑shared‑secret"
   export DB_HOST="127.0.0.1"
   export DB_PORT="3306"
   export DB_NAME="myshop"
   export DB_USER="myuser"
   export DB_PASS="mypassword"
   ```

3. **Make the log file writable** by the web‑server user:

   ```bash
   touch ipn_error.log
   chmod 660 ipn_error.log   # adjust as needed
   ```

4. **Test** with a simulated POST (e.g., using `curl`):

   ```bash
   SECRET="your‑shared‑secret"
   ORDER_ID=123
   AMOUNT=49.99
   STATUS=completed
   SIG=$(printf "%s:%s:%s" "$ORDER_ID" "$AMOUNT" "$STATUS" | \
        openssl dgst -sha256 -hmac "$SECRET" -r | cut -d' ' -f1)

   curl -X POST -d "order_id=$ORDER_ID&amount=$AMOUNT&status=$STATUS&sig=$SIG" \
        https://your‑domain.com/ipn.php
   ```

If everything is configured correctly, the script will respond with:

```json
{"message":"Order marked as paid"}
```

and the corresponding row in `orders` will have `paid = 1`.

**File: `ipn.php`**

```php
<?php
/**
 * IPN (Instant Payment Notification) endpoint for the payment gateway.
 *
 * The gateway sends a POST request with the following fields:
 *   - order_id : integer (the order primary key)
 *   - amount   : string  (the amount that was paid, e.g. "12.34")
 *   - status   : string  (e.g. "completed", "failed", …)
 *   - sig      : string  (HMAC‑SHA256 signature of the payload)
 *
 * The secret used to generate the signature is stored in the environment
 * variable GATEWAY_SECRET.
 *
 * When the status is "completed" we mark the order as paid (paid = 1) in the
 * `orders` table using PDO.
 *
 * The script returns a plain‑text response so the gateway can log success /
 * failure.
 */

declare(strict_types=1);

// ---------------------------------------------------------------------
// 1. Basic sanity checks & helper functions
// ---------------------------------------------------------------------

/**
 * Send a plain‑text response and stop execution.
 *
 * @param int    $code HTTP status code
 * @param string $msg  Message body
 */
function respond(int $code, string $msg): void
{
    http_response_code($code);
    header('Content-Type: text/plain; charset=utf-8');
    echo $msg;
    exit;
}

/**
 * Compute the expected HMAC‑SHA256 signature.
 *
 * The exact algorithm must match the gateway’s implementation.  A common
 * approach is to concatenate the fields in a deterministic order and hash
 * them with the secret:
 *
 *   expected = hash_hmac('sha256', order_id . '|' . amount . '|' . status, secret)
 *
 * If your gateway uses a different format (JSON, URL‑encoded string, etc.),
 * adjust the concatenation accordingly.
 *
 * @param string $orderId
 * @param string $amount
 * @param string $status
 * @param string $secret
 *
 * @return string The hex‑encoded HMAC‑SHA256 signature
 */
function calculateSignature(string $orderId, string $amount, string $status, string $secret): string
{
    $payload = $orderId . '|' . $amount . '|' . $status; // pipe‑separated for clarity
    return hash_hmac('sha256', $payload, $secret);
}

// ---------------------------------------------------------------------
// 2. Retrieve POST data
// ---------------------------------------------------------------------

$requiredFields = ['order_id', 'amount', 'status', 'sig'];
foreach ($requiredFields as $field) {
    if (!isset($_POST[$field])) {
        respond(400, "Missing required field: $field");
    }
}

// Cast to strings (POST values are always strings)
$orderId = (string)$_POST['order_id'];
$amount  = (string)$_POST['amount'];
$status  = (string)$_POST['status'];
$receivedSig = (string)$_POST['sig'];

// ---------------------------------------------------------------------
// 3. Verify signature
// ---------------------------------------------------------------------

$secret = getenv('GATEWAY_SECRET');
if ($secret === false) {
    // The secret must be defined in the environment – otherwise we cannot
    // trust any notification.
    respond(500, 'Server configuration error: missing GATEWAY_SECRET');
}

// Compute the expected signature
$expectedSig = calculateSignature($orderId, $amount, $status, $secret);

// Use hash_equals to avoid timing attacks
if (!hash_equals($expectedSig, $receivedSig)) {
    // Log the failure for audit purposes (optional but recommended)
    error_log("IPN signature mismatch for order {$orderId}. Expected {$expectedSig}, got {$receivedSig}");
    respond(400, 'Invalid signature');
}

// ---------------------------------------------------------------------
// 4. Process the notification
// ---------------------------------------------------------------------

if (strtolower($status) !== 'completed') {
    // Nothing to do for non‑completed statuses – just acknowledge.
    respond(200, 'OK (status not completed)');
}

// ---------------------------------------------------------------------
// 5. Update the order in the database
// ---------------------------------------------------------------------

// Database connection parameters – adjust to your environment.
// It is a good practice to keep these values out of the source code
// (e.g. via environment variables or a separate config file).
$dbHost = getenv('DB_HOST') ?: '127.0.0.1';
$dbName = getenv('DB_NAME') ?: 'my_database';
$dbUser = getenv('DB_USER') ?: 'my_user';
$dbPass = getenv('DB_PASS') ?: '';

$dsn = "mysql:host={$dbHost};dbname={$dbName};charset=utf8mb4";

try {
    $pdo = new PDO(
        $dsn,
        $dbUser,
        $dbPass,
        [
            PDO::ATTR_ERRMODE            => PDO::ERRMODE_EXCEPTION,
            PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,
        ]
    );
} catch (PDOException $e) {
    // Critical – we cannot talk to the DB.
    error_log('IPN DB connection error: ' . $e->getMessage());
    respond(500, 'Database connection error');
}

// Prepare the UPDATE statement.  Using a prepared statement protects against
// SQL injection even though $orderId is expected to be numeric.
$sql = 'UPDATE orders SET paid = 1 WHERE id = :order_id';
$stmt = $pdo->prepare($sql);

try {
    $stmt->execute([':order_id' => $orderId]);

    if ($stmt->rowCount() === 0) {
        // No rows were updated – either the order does not exist or it was
        // already marked as paid.
        error_log("IPN: No order updated for id {$orderId}. Possible unknown order.");
        respond(200, 'OK (order not found or already paid)');
    }

    // Success
    respond(200, 'OK (order marked as paid)');
} catch (PDOException $e) {
    // Log the error for debugging – do NOT expose details to the gateway.
    error_log('IPN DB update error: ' . $e->getMessage());
    respond(500, 'Database error');
}
