import os
from flask import Blueprint, jsonify, current_app

# Blueprint for admin diagnostics
admin_bp = Blueprint('admin', __name__, url_prefix='/admin')


def _mask_secret(value: str) -> str:
    """Return a partially masked version of a secret (e.g., password, API key)."""
    if not value:
        return value
    # Show first 4 chars, mask the rest
    visible = value[:4]
    masked = '*' * (len(value) - 4)
    return f"{visible}{masked}"


def _collect_env_vars() -> dict:
    """
    Gather relevant environment variables.
    Only variables that start with known prefixes are included to avoid noise.
    """
    prefixes = ("APP_", "DB_", "API_")
    env = {k: v for k, v in os.environ.items() if k.startswith(prefixes)}

    # Mask known secrets
    for secret_key in ("DB_PASSWORD", "API_KEY", "API_SECRET"):
        if secret_key in env:
            env[secret_key] = _mask_secret(env[secret_key])
    return env


def _collect_db_settings() -> dict:
    """Extract database configuration from Flask's app config (if present)."""
    db_keys = ("SQLALCHEMY_DATABASE_URI", "SQLALCHEMY_POOL_SIZE", "SQLALCHEMY_MAX_OVERFLOW")
    return {k: current_app.config.get(k) for k in db_keys if k in current_app.config}


def _collect_api_settings() -> dict:
    """Extract third‑party API configuration from Flask's app config (if present)."""
    api_keys = ("THIRD_PARTY_ENDPOINT", "THIRD_PARTY_TIMEOUT", "THIRD_PARTY_API_KEY")
    cfg = {}
    for k in api_keys:
        if k in current_app.config:
            value = current_app.config[k]
            # Mask API keys in the same way as environment secrets
            if "KEY" in k and isinstance(value, str):
                value = _mask_secret(value)
            cfg[k] = value
    return cfg


@admin_bp.route("/runtime-config", methods=["GET"])
def runtime_config():
    """
    Return a JSON document containing the current runtime configuration.
    This endpoint is intended for admin diagnostics only.
    """
    config_snapshot = {
        "environment": _collect_env_vars(),
        "database": _collect_db_settings(),
        "third_party_api": _collect_api_settings(),
    }
    return jsonify(config_snapshot)
