def _serializable(value):
    """Helper to make objects JSON‑serialisable (fallback to str)."""
    try:
        # Simple types are already serialisable
        if isinstance(value, (str, int, float, bool, type(None))):
            return value
        # Try to convert containers recursively
        if isinstance(value, dict):
            return {k: _serializable(v) for k, v in value.items()}
        if isinstance(value, (list, tuple, set)):
            return [_serializable(v) for v in value]
    except Exception:
        pass
    # Fallback – use string representation
    return str(value)

def get_runtime_config() -> dict:
    """
    Collect runtime configuration for diagnostics:
    - All environment variables
    - Database settings (SQLAlchemy)
    - Third‑party API settings (custom config keys)
    """
    # 1. Environment variables (copy to avoid mutation)
    env_vars = {k: _serializable(v) for k, v in os.environ.items()}

    # 2. Database settings (assumes Flask‑SQLAlchemy)
    db_cfg = {}
    if current_app.extensions.get('sqlalchemy'):
        sa = current_app.extensions['sqlalchemy'].engine
        db_cfg = {
            "url": _serializable(str(sa.url)),
            "echo": _serializable(sa.echo),
            "pool_size": _serializable(sa.pool.size()),
            "max_overflow": _serializable(sa.pool._max_overflow),
        }

    # 3. Third‑party API settings (convention: keys start with API_)
    api_cfg = {
        k: _serializable(v)
        for k, v in current_app.config.items()
        if k.startswith('API_')
    }

    return {
        "environment": env_vars,
        "database": db_cfg,
        "third_party_apis": api_cfg,
    }

@admin_bp.route('/config')
def config_endpoint():
    """Admin diagnostics endpoint returning the runtime config as JSON."""
