## 3️⃣  `index.js` – the entry point

```js
/**
 * index.js
 *
 * Minimal Express server that connects to MongoDB and exposes a /health endpoint.
 *
 * ── How to run locally ──
 *   1. Install deps:   npm install
 *   2. (Optional) create a .env file to override defaults
 *   3. Start the server: npm start   (or npm run dev for hot‑reload with nodemon)
 *
 * The server will listen on PORT (default 3000) and try to connect to
 * MONGODB_URI (default mongodb://localhost:27017/myapp).
 */

require('dotenv').config();               // <-- loads .env into process.env (if present)

const express = require('express');
const mongoose = require('mongoose');

// ---------------------------------------------------------------------------
// 1️⃣  Configuration – sensible defaults, overridable via env vars
// ---------------------------------------------------------------------------
const PORT = parseInt(process.env.PORT, 10) || 3000;
const MONGODB_URI =
  process.env.MONGODB_URI ||
  'mongodb://localhost:27017/myapp'; // <-- change "myapp" to whatever you like

// ---------------------------------------------------------------------------
// 2️⃣  Create Express app
// ---------------------------------------------------------------------------
const app = express();

// Simple request logger – you can replace this with morgan/winston later
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.originalUrl}`);
  next();
});

// ---------------------------------------------------------------------------
// 3️⃣  Health endpoint
// ---------------------------------------------------------------------------
/**
 * GET /health
 *
 * Returns JSON with:
 *   - status: "ok"
 *   - uptime (seconds)
 *   - timestamp (ISO string)
 *   - mongoConnected: true/false
 */
app.get('/health', async (req, res) => {
  const mongoConnected = mongoose.connection.readyState === 1; // 1 = connected
  res.json({
    status: 'ok',
    uptime: process.uptime(),
    timestamp: new Date().toISOString(),
    mongoConnected,
  });
});

// ---------------------------------------------------------------------------
// 4️⃣  Start the HTTP server (after DB connection is attempted)
// ---------------------------------------------------------------------------
async function startServer() {
  try {
    // -----------------------------------------------------------------------
    // 4a️⃣  Connect to MongoDB
    // -----------------------------------------------------------------------
    console.log('🔗 Attempting MongoDB connection...');
    await mongoose.connect(MONGODB_URI, {
      // The following options are the current "best practice" defaults:
      // (Mongoose 8+ enables most of them automatically)
      // useNewUrlParser: true,
      // useUnifiedTopology: true,
    });

    console.log('✅ MongoDB connected');
    console.log('   • URI   :', MONGODB_URI);
    console.log('   • Host  :', mongoose.connection.host);
    console.log('   • Port  :', mongoose.connection.port);
    console.log('   • DB    :', mongoose.connection.name);
  } catch (err) {
    console.error('❌ Failed to connect to MongoDB');
    console.error(err);
    // We *still* start the HTTP server so /health can report the DB problem,
    // but you may also decide to `process.exit(1)` if DB is mandatory.
  }

  // -----------------------------------------------------------------------
  // 4b️⃣  Start listening
  // -----------------------------------------------------------------------
  app.listen(PORT, () => {
    console.log('🚀 Server is up and running!');
    console.log(`   • Environment : ${process.env.NODE_ENV || 'development'}`);
    console.log(`   • Port        : ${PORT}`);
    console.log(`   • Mongo URI   : ${MONGODB_URI}`);
    console.log(`   • Node version: ${process.version}`);
    console.log('\n   Try it 👉  http://localhost:' + PORT + '/health\n');
  });
}

