## 1️⃣ `index.js`

```js
/**
 * index.js
 * --------
 * Minimal Express + MongoDB starter.
 *
 *   npm i express mongodb
 *
 * Run:
 *   node index.js               # uses defaults (localhost Mongo, port 3000)
 *   PORT=4000 MONGODB_URI=mongodb://user:pass@host:27017/dbname node index.js
 */

'use strict';

// ──────────────────────────────
// 1️⃣  Imports & configuration
// ──────────────────────────────
const express = require('express');
const { MongoClient } = require('mongodb');
const os = require('os');

// Environment variables (with sensible fall‑backs)
const PORT = normalizePort(process.env.PORT || '3000');
const MONGODB_URI = process.env.MONGODB_URI || 'mongodb://127.0.0.1:27017/health_demo';

// Optional: name of the DB to use (extracted from the URI if possible)
const DB_NAME = (() => {
  try {
    const url = new URL(MONGODB_URI);
    // mongodb://host:port/<db>?...
    const path = url.pathname.replace(/^\/+/, '');
    return path || 'test';
  } catch (_) {
    return 'test';
  }
})();

// ──────────────────────────────
// 2️⃣  Create Express app
// ──────────────────────────────
const app = express();

// Simple JSON body parser (optional, but handy for extensions)
app.use(express.json());

// ──────────────────────────────
// 3️⃣  Health endpoint
// ──────────────────────────────
app.get('/health', async (req, res) => {
  // 1️⃣   HTTP layer is alive (we are already handling the request)
  // 2️⃣   DB layer – ping the server
  let dbOk = false;
  try {
    // The client is stored on app.locals (see below)
    const client = req.app.locals.mongoClient;
    if (client && client.isConnected()) {
      // `admin().ping()` is the cheapest way to verify connectivity
      await client.db(DB_NAME).admin().ping();
      dbOk = true;
    }
  } catch (e) {
    // ignore – dbOk stays false
  }

  const health = {
    uptime: process.uptime(),
    timestamp: new Date().toISOString(),
    status: dbOk ? 'ok' : 'degraded',
    components: {
      http: 'ok',
      mongodb: dbOk ? 'ok' : 'unreachable',
    },
  };

  const statusCode = dbOk ? 200 : 503;
  res.status(statusCode).json(health);
});

// ──────────────────────────────
// 4️⃣  Start server & connect to MongoDB
// ──────────────────────────────
(async () => {
  try {
    // 4️⃣.1️⃣  Connect to MongoDB
    console.log('🔌 Attempting to connect to MongoDB...');
    const mongoClient = new MongoClient(MONGODB_URI, {
      // The driver defaults are fine for a dev environment,
      // but we enable the unified topology flag for modern behaviour.
      useUnifiedTopology: true,
    });

    await mongoClient.connect();
    console.log(`✅ Connected to MongoDB`);
    console.log(`   URI          : ${MONGODB_URI}`);
    console.log(`   Database name: ${DB_NAME}`);

    // Store the client for later use (e.g. health checks, routes)
    app.locals.mongoClient = mongoClient;

    // 4️⃣.2️⃣  Start the HTTP server
    const server = app.listen(PORT, () => {
      const address = server.address();
      const bind = typeof address === 'string' ? address : `${address.address}:${address.port}`;
      console.log(`🚀 Express server listening on ${bind}`);
      console.log(`   Health endpoint → http://${address.address}:${address.port}/health`);
    });

    // ──────────────────────────────
    // 5️⃣  Graceful shutdown handling
    // ──────────────────────────────
    const shutdown = async (signal) => {
      console.log(`\n⚡ Received ${signal}. Shutting down gracefully...`);
      try {
        // Stop accepting new connections
        server.close(() => console.log('🛑 HTTP server closed'));

        // Close MongoDB connection
        if (mongoClient && mongoClient.isConnected()) {
          await mongoClient.close();
          console.log('🗑️ MongoDB connection closed');
        }
      } catch (err) {
        console.error('❗ Error during shutdown:', err);
      } finally {
        process.exit(0);
      }
    };

    process.on('SIGINT', () => shutdown('SIGINT'));
    process.on('SIGTERM', () => shutdown('SIGTERM'));
  } catch (err) {
    console.error('❌ Failed to start application:', err);
    process.exit(1);
  }
})();

// ──────────────────────────────
// Helper: normalise port to number or named pipe
// ──────────────────────────────
function normalizePort(val) {
  const port = parseInt(val, 10);
  if (Number.isNaN(port)) {
    // named pipe
    return val;
  }
  if (port >= 0) {
    // port number
    return port;
  }
  return false;
}
```

