## 4️⃣ `index.js` – **the entry point**

```js
/**
 * index.js
 *
 * Minimal Express server that:
 *   • reads configuration from env vars (with defaults)
 *   • connects to MongoDB via Mongoose
 *   • logs useful startup information
 *   • exposes a /health endpoint
 *
 * To run locally:
 *   1. `npm install`
 *   2. `cp .env.example .env` and adjust values if you like
 *   3. `npm start`   (or `npm run dev` if you have nodemon)
 */

require('dotenv').config(); // <-- loads .env (if present) into process.env

const express = require('express');
const mongoose = require('mongoose');
const http = require('http');

// ------------------------------------------------------------------
// Configuration (environment variables with sensible defaults)
// ------------------------------------------------------------------
const {
  PORT = 3000,
  NODE_ENV = 'development',
  MONGODB_URI = 'mongodb://localhost:27017/health-demo',
} = process.env;

const isProduction = NODE_ENV === 'production';

// ------------------------------------------------------------------
// Helper: pretty‑print the MongoDB connection string (mask password)
// ------------------------------------------------------------------
function maskMongoUri(uri) {
  try {
    const url = new URL(uri);
    if (url.password) {
      url.password = '*****';
    }
    return url.toString();
  } catch (_) {
    // If parsing fails (e.g. SRV format), just return the original string
    return uri;
  }
}

// ------------------------------------------------------------------
// Create Express app
// ------------------------------------------------------------------
const app = express();

// Simple JSON body parser – useful if you later add POST routes
app.use(express.json());

// ------------------------------------------------------------------
// /health endpoint
// ------------------------------------------------------------------
app.get('/health', async (req, res) => {
  // We expose two bits of info:
  //   • HTTP status (always 200 if we get here)
  //   • MongoDB connection state (connected / disconnected / connecting / etc.)
  const mongoState = mongoose.connection.readyState; // 0‑5 enum (see Mongoose docs)
  const stateMap = {
    0: 'disconnected',
    1: 'connected',
    2: 'connecting',
    3: 'disconnecting',
    4: 'invalid',
    5: 'buffering',
  };

  const health = {
    uptime: process.uptime(),
    timestamp: new Date().toISOString(),
    mongo: {
      uri: maskMongoUri(MONGODB_URI),
      state: stateMap[mongoState] ?? 'unknown',
    },
  };

  // If Mongo is not connected, we return 503 so load‑balancers can react.
  const status = mongoState === 1 ? 200 : 503;
  res.status(status).json(health);
});

// ------------------------------------------------------------------
// Connect to MongoDB
// ------------------------------------------------------------------
async function connectToMongo() {
  try {
    // Mongoose's default options are fine for most cases; we add a few
    // that make sense for a quick starter.
    await mongoose.connect(MONGODB_URI, {
      // useNewUrlParser & useUnifiedTopology are true by default in Mongoose 6+
      // The following options are only kept for explicitness.
      serverSelectionTimeoutMS: 5000, // fail fast if the server is unreachable
    });

    console.log('✅ MongoDB connection established');
    console.log(`   • URI       : ${maskMongoUri(MONGODB_URI)}`);
    console.log(`   • Database  : ${mongoose.connection.db?.databaseName ?? 'N/A'}`);
    console.log(`   • Host info : ${mongoose.connection.host}:${mongoose.connection.port}`);
  } catch (err) {
    console.error('❌ Failed to connect to MongoDB');
    console.error(err);
    // Exit the process – without a DB the app is not useful in this demo.
    process.exit(1);
  }
}

// ------------------------------------------------------------------
// Start HTTP server (after Mongo is ready)
// ------------------------------------------------------------------
async function startServer() {
  await connectToMongo();

  const server = http.createServer(app);

  server.listen(PORT, () => {
    console.log('🚀 Server is up and running');
    console.log(`   • Environment : ${NODE_ENV}`);
    console.log(`   • Listening on : http://localhost:${PORT}`);
    console.log(`   • Health check : http://localhost:${PORT}/health`);
  });

  // Graceful shutdown handling (Ctrl‑C, Docker SIGTERM, etc.)
  const shutdown = async (signal) => {
    console.log(`\n⚡ Received ${signal}. Shutting down gracefully…`);
    server.close(async (err) => {
      if (err) {
        console.error('Error while closing the HTTP server:', err);
        process.exit(1);
      }
      try {
        await mongoose.disconnect();
        console.log('✅ MongoDB connection closed');
      } catch (mongoErr) {
        console.error('Error while disconnecting MongoDB:', mongoErr);
      }
      process.exit(0);
    });
  };

  process.on('SIGINT', () => shutdown('SIGINT'));
  process.on('SIGTERM', () => shutdown('SIGTERM'));
}

// ------------------------------------------------------------------
// Run the app
// ------------------------------------------------------------------
startServer().catch((err) => {
  console.error('❌ Unexpected error during startup', err);
  process.exit(1);
});
```

