#!/usr/bin/env node
/**
 * Minimal Express + MongoDB service
 *
 *   - Reads configuration from env vars (with defaults for local dev)
 *   - Connects to MongoDB and logs connection info
 *   - Exposes GET /health that returns JSON with the DB status
 *
 * To run locally:
 *   $ npm install
 *   $ npm start               # uses defaults (MongoDB on localhost)
 *
 * To run in another environment set the vars before starting:
 *   $ MONGODB_URI=mongodb://user:pass@host:27017/dbname PORT=8080 npm start
 */

import express from 'express';
import { MongoClient } from 'mongodb';
import process from 'process';

// ---------- Configuration (env vars + defaults) ----------
const PORT = parseInt(process.env.PORT, 10) || 3000;
const MONGODB_URI =
  process.env.MONGODB_URI ||
  'mongodb://127.0.0.1:27017/health-demo'; // default local DB
const MONGODB_OPTIONS = {
  // The driver defaults are fine for most dev scenarios.
  // You can add more options here (e.g. authMechanism, tls, etc.).
};

// ---------- Create Express app ----------
const app = express();

// ---------- MongoDB client ----------
let mongoClient; // will hold the connected client
let db; // optional reference to a DB (not used here but handy)

async function connectToMongo() {
  console.log('🔌 Attempting MongoDB connection...');
  console.log(`   URI : ${MONGODB_URI}`);

  try {
    mongoClient = new MongoClient(MONGODB_URI, MONGODB_OPTIONS);
    await mongoClient.connect();

    // Pick the DB name from the connection string if present,
    // otherwise fall back to "test".
    const dbName = mongoClient.db().databaseName || 'test';
    db = mongoClient.db(dbName);

    console.log(`✅ Connected to MongoDB (db: "${dbName}")`);
    console.log(
      `   Server version: ${mongoClient.topology?.description?.maxWireVersion}`
    );
  } catch (err) {
    console.error('❌ MongoDB connection failed:', err);
    // In a real service you might want to exit the process,
    // but for this demo we just keep the app running.
  }
}

// ---------- Health endpoint ----------
app.get('/health', async (req, res) => {
  // Simple health check – we only verify that the DB client is ready.
  const mongoOk = mongoClient?.isConnected?.() ?? false;

  // If you want a deeper check you could do a ping:
  // const pingResult = await db.command({ ping: 1 });

  const payload = {
    status: mongoOk ? 'ok' : 'degraded',
    uptimeSeconds: process.uptime(),
    timestamp: new Date().toISOString(),
    mongo: {
      connected: mongoOk,
      uri: MONGODB_URI,
      // Do not expose credentials in logs / responses.
    },
  };

  const httpStatus = mongoOk ? 200 : 503;
  res.status(httpStatus).json(payload);
});

// ---------- Start the server ----------
async function start() {
  await connectToMongo();

  app.listen(PORT, () => {
    console.log(`🚀 Server listening on http://localhost:${PORT}`);
    console.log('   Health endpoint → GET /health');
  });
}

// Graceful shutdown (Ctrl‑C or SIGTERM)
process.on('SIGINT', async () => {
  console.log('\n🛑 Received SIGINT – shutting down...');
  await shutdown();
});
process.on('SIGTERM', async () => {
  console.log('\n🛑 Received SIGTERM – shutting down...');
  await shutdown();
});

async function shutdown() {
  try {
    if (mongoClient?.isConnected?.()) {
      await mongoClient.close();
      console.log('🔒 MongoDB connection closed');
    }
  } catch (e) {
    console.error('Error while closing MongoDB:', e);
  } finally {
    process.exit(0);
  }
}

// Run the bootstrap
start().catch((err) => {
  console.error('❗ Unhandled error during startup:', err);
  process.exit(1);
});
```

