Below is a **single‑file entry point** (`index.js`) that you can drop into a fresh folder, run `npm install` and start the server locally.  

It:

* Reads configuration from environment variables with sensible defaults (`PORT=3000`, `MONGODB_URI=mongodb://localhost:27017/healthdb`).
* Connects to MongoDB using the **official Node driver** (no extra ORM required, but you can swap to Mongoose if you prefer).
* Logs the connection details (host, port, db name, whether TLS is used, etc.) so developers can instantly see where the app is pointing.
* Exposes a very small **`/health`** endpoint that returns JSON with the app’s status and the MongoDB connection state.
* Handles start‑up errors gracefully and exits with a non‑zero code so CI / Docker can detect a failure.

```js
/**
 * index.js
 *
 * Minimal Express + MongoDB starter.
 *
 *   $ npm install
 *   $ node index.js            # uses defaults (PORT=3000, MONGODB_URI=mongodb://localhost:27017/healthdb)
 *
 *   # Or override with environment variables:
 *   $ MONGODB_URI=mongodb://user:pass@db.example.com:27017/mydb PORT=8080 node index.js
 *
 * The server prints useful startup information so you always know
 * which MongoDB instance it is connected to.
 */

'use strict';

// ----- 1️⃣  Imports ---------------------------------------------------------
const express = require('express');
const { MongoClient } = require('mongodb');
const os = require('os');

// ----- 2️⃣  Configuration ---------------------------------------------------
const PORT = process.env.PORT ? Number(process.env.PORT) : 3000;
const MONGODB_URI = process.env.MONGODB_URI || 'mongodb://localhost:27017/healthdb';

// Parse the URI for nicer logging (fallback to raw string if parsing fails)
let parsedMongoUri;
try {
  const { URL } = require('url');
  const url = new URL(MONGODB_URI);
  parsedMongoUri = {
    protocol: url.protocol.replace(':', ''),
    host: url.hostname,
    port: url.port || (url.protocol === 'mongodb+srv:' ? '443' : '27017'),
    dbName: url.pathname.replace('/', '') || '(default)',
    auth: url.username ? `${url.username}:${'*'.repeat(url.password.length)}` : '(none)',
    options: Object.fromEntries(url.searchParams.entries()),
  };
} catch (_) {
  parsedMongoUri = null;
}

// ----- 3️⃣  Create Express app -----------------------------------------------
const app = express();

// Simple JSON body parser (optional, but handy for future endpoints)
app.use(express.json());

// ----- 4️⃣  Health endpoint -------------------------------------------------
app.get('/health', async (req, res) => {
  // We expose a tiny bit of runtime info; feel free to extend.
  const health = {
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptimeSeconds: process.uptime(),
    pid: process.pid,
    hostname: os.hostname(),
    mongo: {
      connected: client?.isConnected?.() ?? false,
      // If connected, give a quick sanity‑check by pinging the server.
      // This is deliberately lightweight.
      ping: client?.topology?.description?.type ? 'unknown' : 'unavailable',
    },
  };
  res.json(health);
});

// ----- 5️⃣  MongoDB connection ------------------------------------------------
let client; // will hold the MongoClient instance

async function startServer() {
  console.log('🚀 Starting Express + MongoDB app...');
  console.log(`   • Listening on port   : ${PORT}`);
  console.log(`   • MongoDB URI        : ${MONGODB_URI}`);

  if (parsedMongoUri) {
    console.log('   • Parsed Mongo URI   :', parsedMongoUri);
  }

  // Create a new client – keep a single connection for the whole process.
  client = new MongoClient(MONGODB_URI, {
    // The driver will use sensible defaults; we enable the unified topology.
    useUnifiedTopology: true,
    // You can tweak pool size, timeouts, etc. here if needed.
  });

  try {
    await client.connect();
    const db = client.db(); // default DB from the URI (or the one you passed)
    console.log('✅ MongoDB connection established');
    console.log(`   • Connected to      : ${db.databaseName}`);
    console.log(`   • Server address    : ${client.topology?.description?.servers?.map(s => `${s.address}`).join(', ') || 'unknown'}`);
    console.log(`   • TLS enabled?      : ${client.topology?.description?.type === 'ReplicaSetWithPrimary' ? 'yes' : 'no'}`);

    // Start listening only after the DB is ready – this prevents race conditions.
    app.listen(PORT, () => {
      console.log(`🌍 HTTP server listening on http://localhost:${PORT}`);
      console.log('   • Health endpoint   : GET /health');
    });
  } catch (err) {
    console.error('❌ Failed to connect to MongoDB:', err.message);
    console.error('   Stack trace:', err.stack);
    // Graceful shutdown – give Docker / systemd a chance to see the failure.
    process.exit(1);
  }
}

// ----- 6️⃣  Graceful shutdown ------------------------------------------------
process.on('SIGINT', async () => {
  console.log('\n👋 Received SIGINT – shutting down...');
  await shutdown();
});
process.on('SIGTERM', async () => {
  console.log('\n🛑 Received SIGTERM – shutting down...');
  await shutdown();
});

async function shutdown() {
  try {
    if (client?.isConnected?.()) {
      await client.close();
      console.log('🔒 MongoDB connection closed');
    }
  } catch (e) {
    console.error('Error while closing MongoDB connection:', e);
  } finally {
    process.exit(0);
  }
}

// ----- 7️⃣  Run --------------------------------------------------------------
startServer();
