import json
import base64
from dataclasses import dataclass, asdict, is_dataclass, fields
from datetime import datetime, date
from typing import Any, Dict, List, Union

# ----------------------------------------------------------------------
# Example custom dataclass – replace/extend as needed for the app.
# ----------------------------------------------------------------------
@dataclass
class Preference:
    """A user‑defined preference entry."""
    key: str
    value: Any


# ----------------------------------------------------------------------
# JSON encoder that knows how to serialize dates, datetimes and Preference.
# ----------------------------------------------------------------------
class _SettingsEncoder(json.JSONEncoder):
    def default(self, o: Any) -> Any:
        if isinstance(o, (datetime, date)):
            # ISO‑format with a type marker so we can restore the exact class.
            return {"__type__": "datetime", "value": o.isoformat()}
        if is_dataclass(o):
            # Store the dataclass name and its fields.
            return {"__type__": "Preference", "value": asdict(o)}
        return super().default(o)


# ----------------------------------------------------------------------
# JSON object_hook that reconstructs the special types.
# ----------------------------------------------------------------------
def _settings_object_hook(d: Dict) -> Any:
    if "__type__" not in d:
        return d
    typ = d["__type__"]
    if typ == "datetime":
        # Try to parse as datetime first, fallback to date.
        val = d["value"]
        try:
            return datetime.fromisoformat(val)
        except ValueError:
            return date.fromisoformat(val)
    if typ == "Preference":
        # Re‑create the Preference dataclass.
        return Preference(**d["value"])
    return d


# ----------------------------------------------------------------------
# Public API
# ----------------------------------------------------------------------
def save_user_settings(obj: Any) -> bytes:
    """
    Serialize a user‑settings object (nested dicts/lists, dates, Preference)
    into a bytes blob suitable for a cookie.
    """
    # JSON → UTF‑8 string → base64 to ensure cookie‑safe characters.
    json_str = json.dumps(obj, cls=_SettingsEncoder, separators=(",", ":"))
    b64 = base64.urlsafe_b64encode(json_str.encode("utf-8"))
    return b64


def load_user_settings(blob: bytes) -> Any:
    """
    Decode a bytes blob produced by ``save_user_settings`` back into the original
    Python object, restoring dates and Preference instances.
    """
    # Reverse of save_user_settings: base64 → UTF‑8 JSON → Python objects.
    json_bytes = base64.urlsafe_b64decode(blob)
    return json.loads(json_bytes.decode("utf-8"), object_hook=_settings_object_hook)
