# Helper: convert Python objects to JSON‑serialisable structures.
# ----------------------------------------------------------------------
def _to_serialisable(obj: Any) -> Any:
    """Recursively transform obj into something json.dumps can handle."""
    if isinstance(obj, datetime.datetime):
        # ISO format with a marker so we can restore a datetime later.
        return {"__type__": "datetime", "value": obj.isoformat()}
    if isinstance(obj, Preference):
        # Store the dataclass as a dict with a type marker.
        data = asdict(obj)
        # Recursively serialise nested values (e.g., datetime inside the dataclass).
        data = {k: _to_serialisable(v) for k, v in data.items()}
        data["__type__"] = "Preference"
        return data
    if isinstance(obj, dict):
        return {k: _to_serialisable(v) for k, v in obj.items()}
    if isinstance(obj, (list, tuple)):
        return [_to_serialisable(v) for v in obj]
    # Primitive types are already JSON‑compatible.
    return obj


# ----------------------------------------------------------------------
# Helper: reconstruct Python objects from the JSON‑decoded structure.
# ----------------------------------------------------------------------
def _from_serialisable(data: Any) -> Any:
    """Recursively restore original Python objects from the serialisable form."""
    if isinstance(data, dict):
