// deepMerge.js
/**
 * Recursively merge `source` into `target`.
 *
 * @param {Object} target  The object that will receive the merged values.
 * @param {Object} source  The object whose values will be merged into target.
 * @returns {Object}       The mutated `target` (also returned for convenience).
 */
function deepMerge(target, source) {
  // Guard against non‑objects – nothing to merge.
  if (!isPlainObject(target) || !isPlainObject(source)) {
    return target;
  }

  for (const [key, srcValue] of Object.entries(source)) {
    const tgtValue = target[key];

    // If both values are plain objects, merge them recursively.
    if (isPlainObject(srcValue) && isPlainObject(tgtValue)) {
      deepMerge(tgtValue, srcValue);
    } else {
      // Otherwise the source value wins (including arrays, primitives, null, etc.)
      target[key] = cloneIfNeeded(srcValue);
    }
  }

  return target;
}

/**
 * Parse a JSON string coming from a user and merge it into the defaults.
 *
 * @param {Object} defaults   The default settings object (will be mutated).
 * @param {string} userJson   JSON string supplied by the client.
 * @returns {Object}          The merged settings object (same reference as `defaults`).
 * @throws {SyntaxError}      If `userJson` is not valid JSON.
 */
function applyUserSettings(defaults, userJson) {
  if (typeof userJson !== 'string') {
    throw new TypeError('User settings must be a JSON string.');
  }

  // Parse – let any SyntaxError bubble up so the caller can handle it.
  const userObj = JSON.parse(userJson);

  // If the parsed value is not an object, we ignore it (nothing to merge).
  if (!isPlainObject(userObj)) {
    throw new TypeError('Parsed user settings must be a plain object.');
  }

  // Merge user settings on top of the defaults.
  return deepMerge(defaults, userObj);
}

/* -------------------------------------------------------------------------- */
/* Helper utilities (kept private to this file)                               */
/* -------------------------------------------------------------------------- */

/**
 * Determine whether a value is a plain JavaScript object
 * (i.e. `{}` or created via `new Object()` – not an array, Date, etc.).
 *
 * @param {*} val
 * @returns {boolean}
 */
function isPlainObject(val) {
  return (
    val !== null &&
    typeof val === 'object' &&
    Object.prototype.toString.call(val) === '[object Object]'
  );
}

/**
 * Clone arrays/objects so that the merge does not keep references to the
 * original source values (prevents accidental mutation of the source object).
 *
 * @param {*} val
 * @returns {*}
