  // Fast‑path: if source is not an object, just return a shallow copy of target.
  if (!isPlainObject(source)) return cloneValue(target);

  // Ensure we have a plain object to start from.
  const result = isPlainObject(target) ? {} : {};

  // Copy keys from target first.
  for (const key of Object.keys(target)) {
    result[key] = cloneValue(target[key]);
  }

  // Merge/override with keys from source.
  for (const key of Object.keys(source)) {
    const srcVal = source[key];
    const tgtVal = result[key];

    if (isPlainObject(srcVal) && isPlainObject(tgtVal)) {
      // Both sides are plain objects → merge recursively.
      result[key] = deepMerge(tgtVal, srcVal);
