/**
 * Deeply merges source into target.
 * Arrays are overwritten; objects are merged recursively.
 * @param {Object} target - The object to receive properties.
 * @param {Object} source - The object providing properties.
 * @returns {Object} The merged target object.
 */
function deepMerge(target, source) {
  if (typeof target !== 'object' || target === null) return source;
  if (typeof source !== 'object' || source === null) return target;

  for (const key of Object.keys(source)) {
    const srcVal = source[key];
    const tgtVal = target[key];

    if (Array.isArray(srcVal)) {
      // Overwrite arrays entirely
      target[key] = srcVal.slice();
    } else if (typeof srcVal === 'object' && srcVal !== null) {
      // Recursively merge plain objects
      if (typeof tgtVal !== 'object' || tgtVal === null) {
        target[key] = {};
      }
      deepMerge(target[key], srcVal);
    } else {
      // Primitive values: overwrite
      target[key] = srcVal;
    }
  }
  return target;
}

/**
 * Parses a JSON string from a user and merges it into default settings.
 * @param {Object} defaults - The default settings object.
 * @param {string} userJson - JSON string supplied by the user.
 * @returns {Object} New settings object with user overrides applied.
 */
function applyUserSettings(defaults, userJson) {
  let userSettings = {};
  try {
    userSettings = JSON.parse(userJson);
  } catch (e) {
    // Invalid JSON – keep defaults unchanged
    console.error('Failed to parse user settings JSON:', e.message);
    return { ...defaults };
  }

  // Clone defaults to avoid mutating the original object
  const merged = JSON.parse(JSON.stringify(defaults));
  return deepMerge(merged, userSettings);
}

