Below is a **stand‑alone, production‑ready Express.js middleware** that

* **Supports credentials** (`Access‑Control‑Allow‑Credentials: true`);
* **Allows a configurable list of partner origins** that can be added/removed at runtime;
* **Serves the web‑app’s own origin** (you can also add it to the list);
* **Handles the OPTIONS pre‑flight request** automatically (responds with `204 No Content`);
* **Falls back to a safe default** when an origin is not on the whitelist.

The code is written in plain JavaScript (ES 2022) but also includes a TypeScript type definition for those who prefer it.

---

## 1️⃣  The Middleware – `corsWithCredentials.js`

```js
/**
 * CORS middleware that:
 *   • Allows credentials
 *   • Dynamically manages a whitelist of allowed origins
 *   • Handles OPTIONS pre‑flight requests
 *
 * Usage:
 *   const cors = require('./corsWithCredentials');
 *   const corsMw = cors({ allowedOrigins: ['https://myapp.com'] });
 *
 *   app.use(corsMw);
 *
 *   // Add a partner at runtime:
 *   corsMw.addOrigin('https://partner.example.com');
 *   // Remove a partner:
 *   corsMw.removeOrigin('https://oldpartner.com');
 */

const DEFAULT_METHODS = ['GET', 'HEAD', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'];
const DEFAULT_MAX_AGE = 86400; // seconds (24 h)

function createCorsMiddleware(options = {}) {
  // -------------------------------------------------------------------------
  // 1️⃣  Normalise options & internal state
  // -------------------------------------------------------------------------
  const {
    // Array of origins that are allowed from the start (e.g. your own web app)
    allowedOrigins = [],
    // Optional extra headers you always want to expose
    exposeHeaders = [],
    // Optional list of methods you want to allow (defaults to DEFAULT_METHODS)
    allowedMethods = DEFAULT_METHODS,
    // Optional list of request headers you want to allow (if not supplied we echo
    // back what the client asked for via Access-Control-Request-Headers)
    allowedHeaders = null,
    // How long a pre‑flight response may be cached by the browser (seconds)
    maxAge = DEFAULT_MAX_AGE,
  } = options;

  // A Set gives O(1) look‑ups and lets us add/remove origins at runtime.
  const originWhitelist = new Set(
    allowedOrigins.map(normaliseOrigin) // normalise once up‑front
  );

  // -------------------------------------------------------------------------
  // 2️⃣  Helper utilities
  // -------------------------------------------------------------------------
  // Normalise a URL string – we only keep the scheme + host + optional port.
  // This protects against accidental inclusion of a path or query string.
  function normaliseOrigin(origin) {
    try {
      const url = new URL(origin);
      return `${url.protocol}//${url.host}`;
    } catch (_) {
      // If it cannot be parsed we treat it as a raw host (e.g. "http://localhost:3000")
      return origin;
    }
  }

  // Is the incoming request origin allowed?
  function isOriginAllowed(requestOrigin) {
    if (!requestOrigin) return false;
    const norm = normaliseOrigin(requestOrigin);
    return originWhitelist.has(norm);
  }

  // Build the Access‑Control‑Allow‑Headers header.
  // If the caller supplied a static list we use that, otherwise we echo back
  // the request's Access-Control-Request-Headers (the most common pattern).
  function getAllowedHeaders(req) {
    if (Array.isArray(allowedHeaders) && allowedHeaders.length) {
      return allowedHeaders.join(', ');
    }
    const requestHeaders = req.header('Access-Control-Request-Headers');
    return requestHeaders ? requestHeaders : '';
  }

  // -------------------------------------------------------------------------
  // 3️⃣  The actual middleware function
  // -------------------------------------------------------------------------
  const middleware = function (req, res, next) {
    const requestOrigin = req.header('Origin');

    // -----------------------------------------------------------------------
    // 3a️⃣  If the request has no Origin header we are not dealing with a CORS
    //      request – just pass control to the next handler.
    // -----------------------------------------------------------------------
    if (!requestOrigin) {
      return next();
    }

    // -----------------------------------------------------------------------
    // 3b️⃣  Origin validation
    // -----------------------------------------------------------------------
    if (!isOriginAllowed(requestOrigin)) {
      // You may either silently ignore the request (no CORS headers) or
      // actively reject it. Here we choose the silent route – the browser will
      // treat the response as a CORS error.
      return next();
    }

    // -----------------------------------------------------------------------
    // 3c️⃣  Set the CORS response headers for *all* request methods
    // -----------------------------------------------------------------------
    const normalizedOrigin = normaliseOrigin(requestOrigin);
    res.setHeader('Access-Control-Allow-Origin', normalizedOrigin);
    // When credentials are allowed the wildcard "*" is *not* permitted.
    res.setHeader('Access-Control-Allow-Credentials', 'true');

    // Optional: expose additional response headers to the browser.
    if (exposeHeaders.length) {
      res.setHeader('Access-Control-Expose-Headers', exposeHeaders.join(', '));
    }

    // -----------------------------------------------------------------------
    // 3d️⃣  OPTIONS pre‑flight handling
    // -----------------------------------------------------------------------
    if (req.method === 'OPTIONS') {
      // The browser is asking what it may send. We answer with the allowed
      // methods, headers, and how long the answer may be cached.
      res.setHeader('Access-Control-Allow-Methods', allowedMethods.join(', '));
      const hdrs = getAllowedHeaders(req);
      if (hdrs) {
        res.setHeader('Access-Control-Allow-Headers', hdrs);
      }
      res.setHeader('Access-Control-Max-Age', String(maxAge));

      // No body – 204 No Content is the conventional response.
      return res.status(204).end();
    }

    // -----------------------------------------------------------------------
    // 3e️⃣  Non‑OPTIONS request – just continue down the stack.
    // -----------------------------------------------------------------------
    return next();
  };

  // -------------------------------------------------------------------------
  // 4️⃣  Runtime management helpers (exposed on the middleware function)
  // -------------------------------------------------------------------------
  /**
   * Add a new origin to the whitelist.
   * @param {string} origin e.g. "https://partner.example.com"
   */
  middleware.addOrigin = function (origin) {
    originWhitelist.add(normaliseOrigin(origin));
  };

  /**
   * Remove an origin from the whitelist.
   * @param {string} origin
   */
  middleware.removeOrigin = function (origin) {
    originWhitelist.delete(normaliseOrigin(origin));
  };

  /**
   * Replace the whole whitelist (useful for bulk updates).
   * @param {string[]} origins
   */
  middleware.setWhitelist = function (origins) {
    originWhitelist.clear();
    origins.forEach((o) => originWhitelist.add(normaliseOrigin(o)));
  };

  /**
   * Retrieve the current whitelist as an array (read‑only copy).
   */
  middleware.getWhitelist = function () {
    return Array.from(originWhitelist);
  };

  return middleware;
}

// Export both the factory and a ready‑to‑use default instance (with an empty list).
module.exports = createCorsMiddleware;
module.exports.default = createCorsMiddleware({ allowedOrigins: [] });
```

### What the file does

| Section | Purpose |
|---------|---------|
| **Options** | Lets you pre‑seed the whitelist, set extra exposed headers, customise allowed methods/headers, and tweak `max‑age`. |
| **originWhitelist** | A `Set` that stores the *normalised* origins (`scheme://host[:port]`). Using a Set makes `addOrigin`/`removeOrigin` O(1). |
| **isOriginAllowed** | Checks whether the incoming `Origin` header matches an entry in the whitelist. |
| **Middleware** | For every request that contains an `Origin` header: <br>• If the origin is not whitelisted → **no CORS headers** (the browser will block it). <br>• If it is whitelisted → set `Access‑Control‑Allow‑Origin` **to that exact origin** (required for credentialed requests). <br>• Always set `Access‑Control‑Allow‑Credentials: true`. <br>• For `OPTIONS` → return a `204` with the appropriate `Allow‑*` headers. |
| **Runtime helpers** | `addOrigin`, `removeOrigin`, `setWhitelist`, `getWhitelist` – expose a simple API so your admin UI or a script can modify the list without restarting the service. |

