## 2️⃣  How to Use It in an Express App

```js
// server.js (or wherever you configure Express)
const express = require('express');
const cors = require('./corsWithCredentials'); // path to the file above

const app = express();

// ---------------------------------------------------------------------
// 1️⃣  Initialise the middleware with the origins you already know.
// ---------------------------------------------------------------------
const corsMw = cors({
  allowedOrigins: [
    // Your own front‑end (same‑origin or a dedicated domain)
    'https://app.mycompany.com',
    // A partner that is already onboarded
    'https://partner1.example.com',
  ],
  // Optional: expose custom response headers (e.g. pagination info)
  exposeHeaders: ['X-Total-Count', 'Link'],
  // Optional: tighten the allowed methods if you wish
  allowedMethods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
});

app.use(corsMw); // <‑‑ must be before your route handlers

// ---------------------------------------------------------------------
// 2️⃣  Example route
// ---------------------------------------------------------------------
app.get('/api/data', (req, res) => {
  // Your normal business logic …
  res.json({ message: 'Hello, CORS‑enabled world!' });
});

// ---------------------------------------------------------------------
// 3️⃣  Dynamically add a partner at runtime (e.g. from an admin UI)
// ---------------------------------------------------------------------
function onboardNewPartner(partnerOrigin) {
  // Validate the origin string first (optional but recommended)
  try {
    new URL(partnerOrigin); // will throw if malformed
    corsMw.addOrigin(partnerOrigin);
    console.log(`✅ Added new partner origin: ${partnerOrigin}`);
  } catch (e) {
    console.error(`❌ Invalid origin "${partnerOrigin}" – not added`);
  }
}

// Simulate a partner being added 10 seconds after start‑up
setTimeout(() => onboardNewPartner('https://newpartner.example.org'), 10_000);

// ---------------------------------------------------------------------
// 4️⃣  Start the server
// ---------------------------------------------------------------------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`🚀 API listening on http://localhost:${PORT}`);
});
```

### Adding / Removing Partners from Somewhere Else

Because the middleware returns an object with helper methods, you can expose them via any interface you like (REST admin endpoint, CLI script, database trigger, etc.):

```js
// adminRoutes.js
const router = require('express').Router();
const corsMw = require('./corsWithCredentials').default; // the default instance

router.post('/partners', (req, res) => {
  const { origin } = req.body;
  try {
    new URL(origin);
    corsMw.addOrigin(origin);
    res.status(201).json({ ok: true, added: origin });
  } catch {
    res.status(400).json({ ok: false, error: 'Invalid origin URL' });
  }
});

router.delete('/partners', (req, res) => {
  const { origin } = req.body;
  corsMw.removeOrigin(origin);
  res.json({ ok: true, removed: origin });
});

module.exports = router;
```

Mount it **before** the CORS middleware (or after – the helpers are independent of order) and you have a live admin panel for partner management.

