## 1️⃣  The middleware source (plain JavaScript)

```js
/**
 * corsWithCredentials.js
 *
 * Express middleware that implements CORS with credentials.
 * It is deliberately tiny and does not depend on the `cors` package,
 * so you can see exactly what is happening and tweak it as needed.
 *
 * @param {Object} opts
 * @param {Array<string>|Function} opts.allowedOrigins
 *        - An array of origins (e.g. ['https://myapp.com', 'https://partner1.com'])
 *        - OR a function (origin => boolean) that decides at runtime.
 * @param {Array<string>} [opts.allowedMethods]
 *        HTTP verbs that you want to expose. Default: GET,HEAD,POST,PUT,PATCH,DELETE,OPTIONS
 * @param {Array<string>} [opts.allowedHeaders]
 *        Request headers you allow the client to send.
 *        Default: Content-Type,Authorization,Accept,Origin,X-Requested-With
 * @param {number} [opts.maxAge] – seconds browsers may cache the pre‑flight response.
 *
 * @returns {Function} Express middleware
 */
function corsWithCredentials(opts) {
  if (!opts || !opts.allowedOrigins) {
    throw new Error('corsWithCredentials: `allowedOrigins` option is required');
  }

  const {
    allowedOrigins,
    allowedMethods = ['GET', 'HEAD', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
    allowedHeaders = [
      'Content-Type',
      'Authorization',
      'Accept',
      'Origin',
      'X-Requested-With',
    ],
    maxAge,
  } = opts;

  // Helper – does the incoming origin match the whitelist?
  const isOriginAllowed = (origin) => {
    if (!origin) return false; // no Origin header → not a CORS request
    if (Array.isArray(allowedOrigins)) {
      return allowedOrigins.includes(origin);
    }
    // Function supplied by the caller
    return typeof allowedOrigins === 'function' && allowedOrigins(origin);
  };

  // The actual middleware
  return function (req, res, next) {
    const requestOrigin = req.headers.origin;

    // If the request is not a CORS request (no Origin header) just continue.
    if (!requestOrigin) {
      return next();
    }

    // -----------------------------------------------------------------
    // 1️⃣  Decide whether we will allow this origin
    // -----------------------------------------------------------------
    if (!isOriginAllowed(requestOrigin)) {
      // You could also choose to silently ignore the request (no CORS headers)
      // and let the browser block it. Here we send a 403 with a helpful message.
      res.status(403).send('Origin not allowed');
      return;
    }

    // -----------------------------------------------------------------
    // 2️⃣  Set the CORS response headers
    // -----------------------------------------------------------------
    // NOTE: We must echo back the *exact* origin, not "*", when credentials are used.
    res.setHeader('Access-Control-Allow-Origin', requestOrigin);
    res.setHeader('Vary', 'Origin'); // important for caches/proxies
    res.setHeader('Access-Control-Allow-Credentials', 'true');

    // These two are only needed for pre‑flight (OPTIONS) requests,
    // but setting them on every response is harmless and simplifies the code.
    res.setHeader('Access-Control-Allow-Methods', allowedMethods.join(','));
    res.setHeader('Access-Control-Allow-Headers', allowedHeaders.join(','));

    if (typeof maxAge === 'number') {
      res.setHeader('Access-Control-Max-Age', String(maxAge));
    }

    // -----------------------------------------------------------------
    // 3️⃣  OPTIONS pre‑flight handling
    // -----------------------------------------------------------------
    if (req.method === 'OPTIONS') {
      // According to the spec a successful pre‑flight response has no body.
      // 204 (No Content) is the conventional status code.
      return res.status(204).end();
    }

    // -----------------------------------------------------------------
    // 4️⃣  Normal request – continue down the middleware chain
    // -----------------------------------------------------------------
    next();
  };
}

/* --------------------------------------------------------------
   Export for both CommonJS and ES‑modules environments
   -------------------------------------------------------------- */
if (typeof module !== 'undefined' && module.exports) {
  module.exports = corsWithCredentials;
}
```

