Below is a **stand‑alone Express middleware** that

* whitelists a set of origins (your own web app + any partner sites)  
* automatically sends the right CORS response headers for **simple** requests  
* fully handles **OPTIONS pre‑flight** requests (including `Access‑Control‑Allow‑Methods`, `Access‑Control‑Allow-Headers`, `Access‑Control‑Max-Age`)  
* supports **credentials** (`Access‑Control‑Allow‑Credentials: true`) – therefore the origin header **must be echoed back** (you cannot use `*`)  
* is **easy to configure** and lets you add/remove partners at runtime without touching the middleware code.

---

## 1️⃣  The middleware (plain JavaScript – works with Node ≥ 12)

```js
/**
 * corsWithCredentials.js
 *
 * Usage:
 *   const cors = require('./corsWithCredentials');
 *   app.use(cors({ origins: ['https://myapp.com'] }));
 *
 *   // later you can add partners:
 *   cors.addOrigin('https://partner1.com');
 *   cors.removeOrigin('https://oldpartner.com');
 */

function createCorsMiddleware(options = {}) {
  // ----- 1️⃣ configuration -------------------------------------------------
  // A Set gives O(1) look‑ups and lets us add/remove origins at runtime.
  const allowedOrigins = new Set(options.origins || []);

  // Default values for pre‑flight response – feel free to override.
  const defaultMethods = options.methods || ['GET', 'HEAD', 'POST', 'PUT', 'PATCH', 'DELETE'];
  const defaultHeaders = options.allowedHeaders || null; // null → echo request header
  const maxAge = options.maxAge || 86400; // 24 h in seconds

  // ----- 2️⃣ helper to check origin ----------------------------------------
  function isOriginAllowed(origin) {
    // `origin` can be undefined (e.g. same‑origin requests without Origin header)
    return origin && allowedOrigins.has(origin);
  }

  // ----- 3️⃣ the actual Express middleware ----------------------------------
  const corsMiddleware = (req, res, next) => {
    const requestOrigin = req.headers.origin;

    // If the request has an Origin header and it is in our whitelist,
    // we need to add the CORS response headers.
    if (isOriginAllowed(requestOrigin)) {
      // 1️⃣ Always echo the exact origin (required when credentials are true)
      res.setHeader('Access-Control-Allow-Origin', requestOrigin);
      // 2️⃣ Allow cookies / Authorization header etc.
      res.setHeader('Access-Control-Allow-Credentials', 'true');

      // 3️⃣ Expose any custom response headers you might need on the client.
      //    If you don't need any, you can omit this header.
      if (options.exposedHeaders) {
        res.setHeader('Access-Control-Expose-Headers', Array.isArray(options.exposedHeaders)
          ? options.exposedHeaders.join(', ')
          : options.exposedHeaders);
      }
    }

    // ----- 4️⃣ Handle pre‑flight (OPTIONS) ---------------------------------
    if (req.method === 'OPTIONS') {
      // Only answer to a pre‑flight if the origin is allowed.
      if (isOriginAllowed(requestOrigin)) {
        // What HTTP methods are allowed for the actual request?
        res.setHeader('Access-Control-Allow-Methods', defaultMethods.join(', '));

        // Which request headers can the client send?
        // If the developer supplied a whitelist, use it; otherwise echo back
        // the request's Access-Control-Request-Headers header.
        const requestHeaders = req.headers['access-control-request-headers'];
        if (defaultHeaders) {
          res.setHeader('Access-Control-Allow-Headers', defaultHeaders.join(', '));
        } else if (requestHeaders) {
          res.setHeader('Access-Control-Allow-Headers', requestHeaders);
        }

        // How long may the result be cached by the browser?
        res.setHeader('Access-Control-Max-Age', String(maxAge));

        // No body – just end the pre‑flight with 204 No Content.
        res.status(204).end();
        return; // skip the rest of the middleware chain
      }

      // Origin not allowed → reject the pre‑flight.
      // You could also just call `next()` and let your app return 404/403.
      res.status(403).send('CORS origin denied');
      return;
    }

    // ----- 5️⃣ Not a pre‑flight → continue to the next handler ---------------
    next();
  };

  // ----- 6️⃣ Runtime API to add / remove partners ---------------------------
  // These helpers are attached to the middleware function itself so the
  // caller can do: `cors.addOrigin('https://partner.example.com')`.
  corsMiddleware.addOrigin = (origin) => {
    if (typeof origin !== 'string') throw new TypeError('origin must be a string');
    allowedOrigins.add(origin);
  };

  corsMiddleware.removeOrigin = (origin) => {
    allowedOrigins.delete(origin);
  };

  corsMiddleware.getOrigins = () => Array.from(allowedOrigins);

  // ----- 7️⃣ Return the configured middleware --------------------------------
  return corsMiddleware;
}

// Export a factory so users can create independent instances (useful for testing)
module.exports = createCorsMiddleware;
```

