## 1. The middleware source (`corsMiddleware.js`)

```js
/**
 * corsMiddleware.js
 *
 * A tiny, zero‑dependency CORS handler that:
 *   • Echoes back the request's Origin only when it is whitelisted.
 *   • Always sends Access-Control-Allow-Credentials: true.
 *   • Handles OPTIONS pre‑flight requests (204 No Content).
 *   • Lets you add/remove partner origins at runtime.
 *
 * Usage:
 *   const cors = require('./corsMiddleware');
 *   const app = express();
 *
 *   // initialise with your own domain + any partners you already know
 *   const corsHandler = cors({
 *     defaultOrigin: 'https://my‑app.example.com',
 *     allowedOrigins: [
 *       'https://my‑app.example.com',
 *       'https://partner1.example.com',
 *       'https://partner2.example.com',
 *     ],
 *     // optional – you can override defaults
 *     allowedMethods: ['GET','POST','PUT','PATCH','DELETE','OPTIONS'],
 *     allowedHeaders: ['Content-Type','Authorization','X-Requested-With'],
 *     maxAge: 86400, // seconds (1 day)
 *   });
 *
 *   // add a new partner later on
 *   corsHandler.addOrigin('https://new‑partner.example.com');
 *
 *   // plug the middleware into the stack (must be before your routes)
 *   app.use(corsHandler.middleware);
 *
 *   // …your routes…
 */
function cors(options = {}) {
  // -------------------------------------------------------------------------
  // 1️⃣  Default configuration
  // -------------------------------------------------------------------------
  const {
    // The origin you *always* trust – also used as a fallback when the request
    // has no Origin header (e.g. same‑origin calls from browsers).
    defaultOrigin = '',
    // Array of origins that are allowed to call the API with credentials.
    allowedOrigins = [],
    // HTTP methods you want to expose. OPTIONS is always added automatically.
    allowedMethods = ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
    // Headers you expect the client to send. You can add more later.
    allowedHeaders = [
      'Content-Type',
      'Authorization',
      'X-Requested-With',
    ],
    // How long browsers may cache the pre‑flight response (in seconds).
    maxAge = 86400, // 1 day
  } = options;

  // -------------------------------------------------------------------------
  // 2️⃣  Internal state – a Set is perfect for O(1) look‑ups & deduplication.
  // -------------------------------------------------------------------------
  const originSet = new Set(
    // Normalise: strip trailing slash, ensure lower‑case for comparison.
    allowedOrigins.map(normaliseOrigin)
  );

  // If a defaultOrigin was supplied, make sure it is also in the set.
  if (defaultOrigin) originSet.add(normaliseOrigin(defaultOrigin));

  // -------------------------------------------------------------------------
  // 3️⃣  Helper utilities
  // -------------------------------------------------------------------------
  function normaliseOrigin(origin) {
    // Remove trailing slash, force lower‑case – the spec says origins are case‑insensitive.
    return origin.trim().replace(/\/+$/, '').toLowerCase();
  }

  function isOriginAllowed(requestOrigin) {
    if (!requestOrigin) return false;
    return originSet.has(normaliseOrigin(requestOrigin));
  }

  // -------------------------------------------------------------------------
  // 4️⃣  Public API – methods to mutate the whitelist at runtime
  // -------------------------------------------------------------------------
  function addOrigin(origin) {
    if (!origin) throw new Error('addOrigin: origin must be a non‑empty string');
    originSet.add(normaliseOrigin(origin));
  }

  function removeOrigin(origin) {
    if (!origin) throw new Error('removeOrigin: origin must be a non‑empty string');
    originSet.delete(normaliseOrigin(origin));
  }

  function listOrigins() {
    // Return a copy so callers cannot mutate the internal Set directly.
    return Array.from(originSet);
  }

  // -------------------------------------------------------------------------
  // 5️⃣  The actual Express middleware
  // -------------------------------------------------------------------------
  function middleware(req, res, next) {
    const requestOrigin = req.headers.origin;

    // -------------------------------------------------
    // 5.1 Set CORS response headers if the origin is allowed
    // -------------------------------------------------
    if (requestOrigin && isOriginAllowed(requestOrigin)) {
      // Echo back the exact origin – you cannot use "*" when credentials are true.
      res.setHeader('Access-Control-Allow-Origin', requestOrigin);
    } else if (!requestOrigin && defaultOrigin) {
      // Same‑origin request (no Origin header). Use the default as a safety net.
      res.setHeader('Access-Control-Allow-Origin', defaultOrigin);
    } else {
      // Origin not allowed → *do not* set CORS headers (the browser will block).
      // If you prefer to always send a header with a generic error you can
      // uncomment the line below.
      // res.setHeader('Access-Control-Allow-Origin', 'null');
    }

    // Credentials are required for both our web‑app and partner sites.
    res.setHeader('Access-Control-Allow-Credentials', 'true');

    // -------------------------------------------------
    // 5.2 Pre‑flight (OPTIONS) handling
    // -------------------------------------------------
    if (req.method === 'OPTIONS') {
      // The client is asking what it may send – respond immediately.
      res.setHeader(
        'Access-Control-Allow-Methods',
        allowedMethods.join(', ')
      );
      res.setHeader(
        'Access-Control-Allow-Headers',
        allowedHeaders.join(', ')
      );
      // How long the result of a pre‑flight request can be cached.
      res.setHeader('Access-Control-Max-Age', String(maxAge));

      // No body needed – 204 No Content is the conventional response.
      res.status(204).end();
      return; // short‑circuit, do not call next()
    }

    // -------------------------------------------------
    // 5.3 Normal request – continue down the stack
    // -------------------------------------------------
    next();
  }

  // -------------------------------------------------------------------------
  // 6️⃣  Return the public interface
  // -------------------------------------------------------------------------
  return {
    middleware,
    addOrigin,
    removeOrigin,
    listOrigins,
    // expose the internal Set for advanced use‑cases (read‑only)
    _originSet: originSet,
  };
}

module.exports = cors;
```

