```js
// corsMiddleware.js
// Express.js CORS middleware that supports credentials and a dynamic list of allowed origins.
// ---------------------------------------------------------------
// Usage:
// const cors = require('./corsMiddleware');
// const corsMw = cors({ origins: ['https://myapp.com'] }); // initial list
// app.use(corsMw);                     // attach to all routes
// corsMw.addOrigin('https://partner1.com'); // add partners at runtime
// ---------------------------------------------------------------

/**
 * Create a CORS middleware.
 * @param {Object} options
 * @param {string[]} [options.origins] - Initial list of allowed origins.
 * @param {string[]} [options.methods] - HTTP methods allowed for pre‑flight.
 * @param {string[]} [options.headers] - Allowed request headers for pre‑flight.
 * @returns {Function & {addOrigin(origin:string):void}} Middleware function with an `addOrigin` helper.
 */
function createCorsMiddleware({
  origins = [],                     // allowed origins (exact strings)
  methods = ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
  headers = ['Content-Type', 'Authorization', 'X-Requested-With'],
} = {}) {
  // Use a Set for O(1) look‑ups and easy deduplication.
  const allowedOrigins = new Set(origins.map(normaliseOrigin));

  // Helper to normalise origins (remove trailing slash).
  function normaliseOrigin(origin) {
    if (!origin) return '';
    return origin.replace(/\/+$/, '');
  }

  // Public method to add a partner origin at runtime.
  function addOrigin(origin) {
    if (origin) allowedOrigins.add(normaliseOrigin(origin));
  }

  // The actual Express middleware.
  const middleware = (req, res, next) => {
    const requestOrigin = normaliseOrigin(req.headers.origin);

    // If the request's Origin header matches an allowed origin, set CORS headers.
    if (allowedOrigins.has(requestOrigin)) {
      res.setHeader('Access-Control-Allow-Origin', requestOrigin);
      res.setHeader('Vary', 'Origin'); // tell caches that response varies by Origin
      res.setHeader('Access-Control-Allow-Credentials', 'true');
    }

    // Always expose these headers (optional, adjust as needed).
    res.setHeader('Access-Control-Expose-Headers', 'Content-Length, X-Kuma-Revision');

    // Handle pre‑flight OPTIONS request.
    if (req.method === 'OPTIONS') {
      // If the origin is not allowed we still need to end the request,
      // but without the CORS headers – the browser will treat it as a failure.
      if (allowedOrigins.has(requestOrigin)) {
        res.setHeader('Access-Control-Allow-Methods', methods.join(', '));
        res.setHeader('Access-Control-Allow-Headers', headers.join(', '));
        // Some browsers also expect a max‑age value.
        res.setHeader('Access-Control-Max-Age', '86400'); // 24 hours
      }
      // No body for preflight responses.
      res.status(204).end();
      return;
    }

    // For non‑OPTIONS requests just continue down the stack.
    next();
  };

  // Attach the helper so callers can do: corsMw.addOrigin(...)
  middleware.addOrigin = addOrigin;

  return middleware;
}

module.exports = createCorsMiddleware;
```

