// corsMiddleware.js
// Express middleware to handle CORS with credentials and dynamic partner origins.

const DEFAULT_OPTIONS = {
  // Origins that are allowed to access the API.
  // Can be an array of strings or a function (origin => boolean).
  allowedOrigins: [],

  // HTTP methods allowed for CORS requests.
  methods: ['GET', 'HEAD', 'PUT', 'POST', 'DELETE', 'OPTIONS'],

  // Headers that the client may send.
  allowedHeaders: ['Content-Type', 'Authorization', 'X-Requested-With'],

  // Headers exposed to the client.
  exposedHeaders: [],

  // Max age for preflight cache (seconds).
  maxAge: 86400,
};

/**
 * Create a CORS middleware.
 *
 * @param {Object} opts Configuration options (see DEFAULT_OPTIONS).
 * @returns {Function} Express middleware.
 */
function corsMiddleware(opts = {}) {
  const {
    allowedOrigins,
    methods,
    allowedHeaders,
    exposedHeaders,
    maxAge,
  } = { ...DEFAULT_OPTIONS, ...opts };

  // Helper to decide whether an origin is allowed.
  const isOriginAllowed = typeof allowedOrigins === 'function'
    ? allowedOrigins
    : (origin) => allowedOrigins.includes(origin);

  return function (req, res, next) {
    const requestOrigin = req.headers.origin;

    // If the request has no Origin header, skip CORS handling.
    if (!requestOrigin) {
      return next();
    }

    // Set Access‑Control‑Allow‑Origin only for allowed origins.
    if (isOriginAllowed(requestOrigin)) {
      res.setHeader('Access-Control-Allow-Origin', requestOrigin);
      // Required for credentialed requests (cookies, auth headers, etc.).
      res.setHeader('Access-Control-Allow-Credentials', 'true');
    }

    // Always expose the allowed headers list (if any).
    if (exposedHeaders.length) {
      res.setHeader('Access-Control-Expose-Headers', exposedHeaders.join(','));
    }

    // Handle preflight (OPTIONS) requests.
    if (req.method === 'OPTIONS') {
      // CORS preflight must echo the requested method(s) and header(s).
      res.setHeader('Access-Control-Allow-Methods', methods.join(','));
      res.setHeader(
        'Access-Control-Allow-Headers',
        allowedHeaders.join(','),
      );
      if (maxAge) {
        res.setHeader('Access-Control-Max-Age', String(maxAge));
      }
      // Respond with 204 No Content – no body needed.
      return res.status(204).end();
    }

    // For non‑OPTIONS requests, continue down the middleware chain.
    next();
  };
}

module.exports = corsMiddleware;

