// corsMiddleware.js
// Express middleware to handle CORS with credentials.
// Allows configuring a dynamic list of allowed origins (e.g., partners).

/**
 * @param {Object} options
 * @param {string[]} options.allowedOrigins - Array of origins allowed to access the API.
 * @param {string[]} [options.allowedMethods=['GET','POST','PUT','PATCH','DELETE','OPTIONS']]
 * @param {string[]} [options.allowedHeaders=['Content-Type','Authorization']]
 * @param {number} [options.maxAge=86400] - Seconds browsers may cache the preflight response.
 * @returns {function} Express middleware.
 */
function cors(options) {
  const {
    allowedOrigins,
    allowedMethods = ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
    allowedHeaders = ['Content-Type', 'Authorization'],
    maxAge = 86400,
  } = options;

  // Convert arrays to comma‑separated strings once for efficiency.
  const methodsStr = allowedMethods.join(', ');
  const headersStr = allowedHeaders.join(', ');

  return function (req, res, next) {
    const origin = req.headers.origin;

    // If the request's Origin is in the whitelist, reflect it back.
    if (origin && allowedOrigins.includes(origin)) {
      res.setHeader('Access-Control-Allow-Origin', origin);
      res.setHeader('Vary', 'Origin'); // Ensure caches vary by Origin.
      res.setHeader('Access-Control-Allow-Credentials', 'true');
    }

    // Always expose the allowed methods & headers for preflight handling.
    res.setHeader('Access-Control-Allow-Methods', methodsStr);
    res.setHeader('Access-Control-Allow-Headers', headersStr);
    res.setHeader('Access-Control-Max-Age', String(maxAge));

    // Handle preflight OPTIONS request.
    if (req.method === 'OPTIONS') {
      // If the origin wasn't allowed, respond with 403.
      if (!origin || !allowedOrigins.includes(origin)) {
        return res.sendStatus(403);
      }
      return res.sendStatus(204); // No Content
    }

    // For non‑OPTIONS requests continue the middleware chain.
    next();
  };
}

module.exports = cors;

