## 1️⃣  The middleware source (`cors-middleware.js`)

```js
/**
 * cors-middleware.js
 *
 * Express middleware that:
 *   • Whitelists origins (static array, RegExp, or a custom function)
 *   • Allows credentials (required for cookies / Authorization headers)
 *   • Handles OPTIONS pre‑flight automatically
 *
 * Usage:
 *   const cors = require('./cors-middleware');
 *   app.use(cors({
 *     origins: ['https://myapp.com', 'https://partner1.com'],
 *     // optional: you can also pass RegExp or a function to match origins
 *   }));
 *
 *   // Add a partner later:
 *   cors.addOrigin('https://newpartner.com');
 *
 *   // Remove a partner:
 *   cors.removeOrigin('https://oldpartner.com');
 */

const DEFAULT_OPTIONS = {
  // If true, the `Access-Control-Allow-Credentials` header will be sent.
  // Required when the caller sends cookies, Authorization header, etc.
  credentials: true,

  // HTTP methods you want to allow on the API.
  // Feel free to adjust to your needs.
  methods: ['GET', 'HEAD', 'PUT', 'PATCH', 'POST', 'DELETE'],

  // Which request headers the client may send.
  // `*` is not allowed when credentials are true, so we echo the request's
  // `Access-Control-Request-Headers` header.
  allowedHeaders: null, // null → echo request header (see below)

  // Max‑age for the pre‑flight cache (seconds). 1 hour is a sensible default.
  maxAge: 3600,
};

/**
 * Helper that normalises the `origins` option into a matcher function.
 *
 * @param {Array<string|RegExp>|function(string):boolean} origins
 * @returns {function(string):boolean}
 */
function buildOriginMatcher(origins) {
  // If a custom matcher was supplied, trust it.
  if (typeof origins === 'function') {
    return origins;
  }

  // Normalise an array of strings / RegExp objects.
  const exactSet = new Set();
  const regexes = [];

  for (const o of origins) {
    if (typeof o === 'string') {
      exactSet.add(o);
    } else if (o instanceof RegExp) {
      regexes.push(o);
    } else {
      throw new TypeError(
        'CORS origins must be strings, RegExp objects, or a matcher function'
      );
    }
  }

  return function (origin) {
    if (!origin) return false;
    if (exactSet.has(origin)) return true;
    return regexes.some((re) => re.test(origin));
  };
}

/**
 * Factory function – returns the actual middleware.
 *
 * @param {Object} [options]
 * @param {Array<string|RegExp>|function(string):boolean} [options.origins=[]]
 *        – whitelist of allowed origins.  If omitted, no origin is allowed.
 * @param {boolean} [options.credentials=true]
 * @param {Array<string>} [options.methods]
 * @param {Array<string>|null} [options.allowedHeaders] – if null the request's
 *        `Access-Control-Request-Headers` header is echoed back.
 * @param {number} [options.maxAge]
 *
 * @returns {function(req, res, next)} Express middleware
 */
function corsMiddleware(userOptions = {}) {
  const opts = { ...DEFAULT_OPTIONS, ...userOptions };

  // Build the matcher that tells us whether an incoming Origin header is allowed.
  const isOriginAllowed = buildOriginMatcher(opts.origins || []);

  // -------------------------------------------------------------------------
  // The actual middleware
  // -------------------------------------------------------------------------
  return function (req, res, next) {
    const requestOrigin = req.headers.origin;

    // -----------------------------------------------------------------------
    // 1️⃣  If the request has no Origin header → not a CORS request → skip.
    // -----------------------------------------------------------------------
    if (!requestOrigin) {
      return next();
    }

    // -----------------------------------------------------------------------
    // 2️⃣  Is the origin on our whitelist?
    // -----------------------------------------------------------------------
    if (!isOriginAllowed(requestOrigin)) {
      // You could also choose to silently ignore and let the request continue,
      // but it's often helpful to send a 403 so the client knows why.
      return res
        .status(403)
        .send('CORS origin denied: ' + requestOrigin);
    }

    // -----------------------------------------------------------------------
    // 3️⃣  Set the basic CORS response headers.
    // -----------------------------------------------------------------------
    // When credentials are allowed you **must not** use "*".  Echo the origin.
    res.setHeader('Access-Control-Allow-Origin', requestOrigin);

    if (opts.credentials) {
      res.setHeader('Access-Control-Allow-Credentials', 'true');
    }

    // -----------------------------------------------------------------------
    // 4️⃣  Handle pre‑flight (OPTIONS) requests.
    // -----------------------------------------------------------------------
    if (req.method === 'OPTIONS') {
      // Access‑Control‑Request-Method is required on a pre‑flight request.
      const requestMethod = req.headers['access-control-request-method'];
      if (!requestMethod) {
        // Not a valid preflight – just let the request fall through.
        return next();
      }

      // 4a. Allowed methods
      res.setHeader(
        'Access-Control-Allow-Methods',
        opts.methods.join(', ')
      );

      // 4b. Allowed request headers
      const requestHeaders = req.headers['access-control-request-headers'];
      if (opts.allowedHeaders && opts.allowedHeaders.length) {
        res.setHeader(
          'Access-Control-Allow-Headers',
          opts.allowedHeaders.join(', ')
        );
      } else if (requestHeaders) {
        // Echo back what the client asked for.
        res.setHeader('Access-Control-Allow-Headers', requestHeaders);
      }

      // 4c. Cache duration for the preflight response
      if (opts.maxAge != null) {
        res.setHeader('Access-Control-Max-Age', String(opts.maxAge));
      }

      // 4d. End the preflight with a 204 No Content.
      return res.status(204).send();
    }

    // -----------------------------------------------------------------------
    // 5️⃣  Non‑OPTIONS request – just continue down the stack.
    // -----------------------------------------------------------------------
    next();
  };
}

/* -------------------------------------------------------------------------
 * Helper methods for runtime configuration (add / remove origins)
 * -------------------------------------------------------------------------
 * Because the matcher is built once at middleware creation time, we expose a
 * tiny API that mutates the underlying whitelist and rebuilds the matcher.
 *
 * Example:
 *    const cors = require('./cors-middleware');
 *    const corsMw = cors({ origins: ['https://myapp.com'] });
 *    app.use(corsMw);
 *
 *    // later …
 *    cors.addOrigin('https://newpartner.com');
 * ------------------------------------------------------------------------- */

corsMiddleware.addOrigin = function (origin, middlewareInstance) {
  if (!middlewareInstance || typeof middlewareInstance !== 'function') {
    throw new Error(
      'You must pass the middleware instance returned by corsMiddleware()'
    );
  }
  // Grab the internal whitelist (we stored it on the function object)
  const whitelist = middlewareInstance._whitelist || [];
  whitelist.push(origin);
  middlewareInstance._whitelist = whitelist;
  middlewareInstance._isOriginAllowed = buildOriginMatcher(whitelist);
};

corsMiddleware.removeOrigin = function (origin, middlewareInstance) {
  if (!middlewareInstance || typeof middlewareInstance !== 'function') {
    throw new Error(
      'You must pass the middleware instance returned by corsMiddleware()'
    );
  }
  const whitelist = (middlewareInstance._whitelist || []).filter(
    (o) => o !== origin
  );
  middlewareInstance._whitelist = whitelist;
  middlewareInstance._isOriginAllowed = buildOriginMatcher(whitelist);
};

/* -------------------------------------------------------------------------
 * When the middleware is created we stash the whitelist & matcher on the
 * returned function so the helpers above can mutate them.
 * ------------------------------------------------------------------------- */
function wrapWithState(mw, origins) {
  mw._whitelist = origins.slice(); // copy
  mw._isOriginAllowed = buildOriginMatcher(origins);
  // Overwrite the internal matcher used by the closure
  const original = mw;
  return function (req, res, next) {
    // Replace the `isOriginAllowed` reference with the mutable one.
    const isOriginAllowed = mw._isOriginAllowed;
    // Re‑run the same logic but using the mutable matcher.
    // To avoid code duplication we simply call the original with a tiny shim.
    // (the original closure captured its own `isOriginAllowed`, so we need
    //  to re‑execute the logic here.)
    const requestOrigin = req.headers.origin;
    if (!requestOrigin) return next();
    if (!isOriginAllowed(requestOrigin)) {
      return res
        .status(403)
        .send('CORS origin denied: ' + requestOrigin);
    }

    res.setHeader('Access-Control-Allow-Origin', requestOrigin);
    if (original._options.credentials) {
      res.setHeader('Access-Control-Allow-Credentials', 'true');
    }

    if (req.method === 'OPTIONS') {
      const requestMethod = req.headers['access-control-request-method'];
      if (!requestMethod) return next();

      res.setHeader(
        'Access-Control-Allow-Methods',
        original._options.methods.join(', ')
      );

      const requestHeaders = req.headers['access-control-request-headers'];
      if (original._options.allowedHeaders && original._options.allowedHeaders.length) {
        res.setHeader(
          'Access-Control-Allow-Headers',
          original._options.allowedHeaders.join(', ')
        );
      } else if (requestHeaders) {
        res.setHeader('Access-Control-Allow-Headers', requestHeaders);
      }

      if (original._options.maxAge != null) {
        res.setHeader('Access-Control-Max-Age', String(original._options.maxAge));
      }

      return res.status(204).send();
    }

    next();
  };
}

/* -------------------------------------------------------------------------
 * Exported factory – we wrap the middleware so that callers can later add/
 * remove origins without having to recreate the whole stack.
 * ------------------------------------------------------------------------- */
function createCors(options = {}) {
  const middleware = corsMiddleware(options);
  // stash options for later reference (used by the wrapper above)
  middleware._options = { ...DEFAULT_OPTIONS, ...options };
  // store the original whitelist for the mutable API
  middleware._whitelist = (options.origins || []).slice();

  // replace the inner matcher with a mutable one
  middleware._isOriginAllowed = buildOriginMatcher(middleware._whitelist);
  // Return a wrapper that uses the mutable matcher.
  return wrapWithState(middleware, middleware._whitelist);
}

/* -------------------------------------------------------------------------
 * Public API
 * ------------------------------------------------------------------------- */
module.exports = createCors;
module.exports.addOrigin = corsMiddleware.addOrigin;
module.exports.removeOrigin = corsMiddleware.removeOrigin;
```

