// corsMiddleware.js
// Express.js CORS middleware supporting credentials and dynamic partner origins.

const DEFAULT_OPTIONS = {
  // HTTP methods allowed for CORS requests
  methods: ['GET', 'HEAD', 'PUT', 'POST', 'DELETE', 'PATCH'],
  // Request headers the client may use
  allowedHeaders: ['Content-Type', 'Authorization'],
  // How long (seconds) the results of a preflight request can be cached
  maxAge: 86400,
};

/**
 * Factory that creates a CORS middleware.
 * @param {Object} opts
 * @param {Array<string>} [opts.origins] - Initial list of allowed origins.
 * @param {Array<string>} [opts.methods] - Allowed HTTP methods.
 * @param {Array<string>} [opts.allowedHeaders] - Allowed request headers.
 * @param {number} [opts.maxAge] - Max‑age for preflight cache (seconds).
 * @returns {Function} Express middleware.
 *
 * The returned function also has two helper methods:
 *   addOrigin(origin)   – add a new partner origin at runtime.
 *   removeOrigin(origin) – remove an origin.
 */
function createCorsMiddleware(opts = {}) {
  const config = {
    origins: new Set(opts.origins || []), // use Set for O(1) look‑ups
    methods: opts.methods || DEFAULT_OPTIONS.methods,
    allowedHeaders: opts.allowedHeaders || DEFAULT_OPTIONS.allowedHeaders,
    maxAge: opts.maxAge !== undefined ? opts.maxAge : DEFAULT_OPTIONS.maxAge,
  };

  // Helper to check whether the request origin is allowed
  const isOriginAllowed = (origin) => config.origins.has(origin);

  // The actual middleware
  const middleware = (req, res, next) => {
    const requestOrigin = req.headers.origin;

    // If no Origin header, it's not a CORS request – just continue.
    if (!requestOrigin) return next();

    // If the origin is allowed, echo it back; otherwise omit CORS headers.
    if (isOriginAllowed(requestOrigin)) {
      res.setHeader('Access-Control-Allow-Origin', requestOrigin);
      // Credentials require explicit origin, never '*'
      res.setHeader('Access-Control-Allow-Credentials', 'true');
    }

    // Handle preflight (OPTIONS) requests
    if (req.method === 'OPTIONS') {
      // Only respond to preflight if the origin is allowed
      if (isOriginAllowed(requestOrigin)) {
        res.setHeader('Access-Control-Allow-Methods', config.methods.join(','));
        res.setHeader(
          'Access-Control-Allow-Headers',
          config.allowedHeaders.join(',')
        );
        res.setHeader('Access-Control-Max-Age', String(config.maxAge));
        // No body needed for preflight response
        return res.sendStatus(204);
      }
      // Origin not allowed – reject with 403
      return res.sendStatus(403);
    }

    // Non‑preflight request – continue down the middleware chain
    next();
  };

  // Expose helper methods to modify the allowed origins at runtime
  middleware.addOrigin = (origin) => {
    if (typeof origin === 'string') config.origins.add(origin);
  };
  middleware.removeOrigin = (origin) => {
    config.origins.delete(origin);
  };
  middleware.getOrigins = () => Array.from(config.origins);

  return middleware;
}

module.exports = createCorsMiddleware;
