const DEFAULT_OPTIONS = {
  methods: 'GET,HEAD,PUT,PATCH,POST,DELETE',
  allowedHeaders: 'Content-Type,Authorization',
  maxAge: 86400, // seconds (1 day)
};

/**
 * Create a CORS middleware.
 * @param {Object} config
 * @param {string[]} [config.origins] - Initial list of allowed origins.
 * @param {string} [config.methods]   - Allowed HTTP methods.
 * @param {string} [config.allowedHeaders] - Allowed request headers.
 * @param {number} [config.maxAge]    - Pre‑flight cache time (seconds).
 * @returns {Function} Express middleware with an `addOrigin` helper.
 */
function createCorsMiddleware(config = {}) {
  const {
    origins = [],
    methods = DEFAULT_OPTIONS.methods,
    allowedHeaders = DEFAULT_OPTIONS.allowedHeaders,
    maxAge = DEFAULT_OPTIONS.maxAge,
  } = config;

  // Use a Set for O(1) look‑ups and easy dynamic updates.
  const allowedOrigins = new Set(origins);

  // Helper to add a new partner origin at runtime.
  const addOrigin = (origin) => {
    if (typeof origin === 'string' && origin.trim()) {
      allowedOrigins.add(origin.trim());
    }
  };

  // The actual middleware function.
  const middleware = (req, res, next) => {
    const requestOrigin = req.headers.origin;

    // If the request has an Origin header and it's in our whitelist,
    // set the appropriate CORS headers.
    if (requestOrigin && allowedOrigins.has(requestOrigin)) {
      res.setHeader('Access-Control-Allow-Origin', requestOrigin);
      res.setHeader('Access-Control-Allow-Credentials', 'true');
      res.setHeader('Vary', 'Origin'); // for caching proxies

      // Handle pre‑flight request.
      if (req.method === 'OPTIONS') {
        res.setHeader('Access-Control-Allow-Methods', methods);
        res.setHeader('Access-Control-Allow-Headers', allowedHeaders);
        res.setHeader('Access-Control-Max-Age', String(maxAge));
        // No body needed for pre‑flight response.
        return res.sendStatus(204);
      }
    }

    // For non‑CORS or disallowed origins just continue.
    return next();
  };

  // Expose the helper on the middleware function.
  middleware.addOrigin = addOrigin;
  middleware.allowedOrigins = allowedOrigins; // optional: for inspection

  return middleware;
}

module.exports = createCorsMiddleware;
