// Express middleware to handle CORS with credentials.
//   • Allows dynamic list of partner origins.
//   • Handles pre‑flight (OPTIONS) requests.
//   • Sends proper Access‑Control headers only for allowed origins.

const DEFAULT_OPTIONS = {
  // HTTP methods your API supports
  methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
  // Custom request headers you expect from the client
  allowedHeaders: ['Content-Type', 'Authorization', 'X-Requested-With'],
  // How long the results of a pre‑flight request can be cached (seconds)
  maxAge: 86400,
};

/**
 * Create a CORS middleware.
 *
 * @param {Object} config
 * @param {string[]} config.allowedOrigins - Array of origins (e.g., ['https://app.example.com', 'https://partner1.com'])
 * @param {string[]} [config.methods]        - Allowed HTTP methods.
 * @param {string[]} [config.allowedHeaders] - Allowed request headers.
 * @param {number}   [config.maxAge]         - Max‑age for pre‑flight cache (seconds).
 * @returns {function} Express middleware.
 */
function createCorsMiddleware(config) {
  const {
    allowedOrigins,
    methods = DEFAULT_OPTIONS.methods,
    allowedHeaders = DEFAULT_OPTIONS.allowedHeaders,
    maxAge = DEFAULT_OPTIONS.maxAge,
  } = config;

  // Turn the origin list into a Set for O(1) look‑ups.
  const originsSet = new Set(allowedOrigins);

  return function corsMiddleware(req, res, next) {
    const requestOrigin = req.headers.origin;

    // If the request has no Origin header (e.g., same‑origin or non‑browser request), skip CORS.
    if (!requestOrigin) {
      return next();
    }

    // Only set CORS headers for origins we explicitly allow.
    if (originsSet.has(requestOrigin)) {
      res.setHeader('Access-Control-Allow-Origin', requestOrigin);
      res.setHeader('Vary', 'Origin'); // Ensure caches vary by Origin.
      res.setHeader('Access-Control-Allow-Credentials', 'true');
      res.setHeader('Access-Control-Allow-Methods', methods.join(','));
      res.setHeader('Access-Control-Allow-Headers', allowedHeaders.join(','));
      res.setHeader('Access-Control-Max-Age', String(maxAge));
    }

    // Handle pre‑flight request.
    if (req.method === 'OPTIONS') {
      // If the origin was not allowed, respond with 403; otherwise 204 No Content.
      if (!originsSet.has(requestOrigin)) {
        return res.sendStatus(403);
      }
      return res.sendStatus(204);
    }

    // Normal request – continue down the middleware chain.
    next();
  };
}

