/**
 * GET /go?url=<external‑url>
 *
 *  • If the `url` query‑parameter is missing → 400 Bad Request
 *  • If the value is not a valid absolute URL   → 400 Bad Request
 *  • Otherwise:
 *        – Log the click (you can replace the console.log with a DB write, analytics service, …)
 *        – Respond with a 302 redirect to the supplied URL
 *
 * This endpoint is typically used for “outbound‑click tracking”.
 */

const express = require('express');
const app = express();
const port = process.env.PORT || 3000;

/**
 * Simple logger – replace with winston, pino, a DB write, etc.
 */
function logClick(req, targetUrl) {
  // Example fields you might want to capture
  const logEntry = {
    timestamp: new Date().toISOString(),
    ip: req.ip,
    userAgent: req.get('User-Agent') || '',
    referer: req.get('Referer') || '',
    targetUrl,
  };
  console.log('OUTBOUND_CLICK:', JSON.stringify(logEntry));
}

/**
 * Helper – validates that a string is an absolute HTTP(S) URL.
 * Returns a URL object if valid, otherwise `null`.
 */
function parseExternalUrl(raw) {
  try {
    const url = new URL(raw);
    // Only allow http / https – prevents redirects to javascript:, data:, etc.
    if (url.protocol === 'http:' || url.protocol === 'https:') {
      return url;
    }
    return null;
  } catch (_) {
    return null;
  }
}

/* ---------------------------------------------------------- */
/*  Route definition                                            */
/* ---------------------------------------------------------- */
app.get('/go', (req, res) => {
  const rawUrl = req.query.url;

  // ---- 1️⃣  Parameter missing? ---------------------------------
  if (!rawUrl) {
    return res
      .status(400)
      .json({ error: "Missing required query parameter 'url'." });
  }

  // ---- 2️⃣  Validate the URL ------------------------------------
  const safeUrl = parseExternalUrl(rawUrl);
  if (!safeUrl) {
    return res
      .status(400)
      .json({ error: "'url' must be a valid absolute http(s) URL." });
  }

  // ---- 3️⃣  Log the click ---------------------------------------
  logClick(req, safeUrl.href);

  // ---- 4️⃣  Redirect --------------------------------------------
  // 302 (Found) is the usual default for “temporary” outbound redirects.
  // If you want a permanent redirect, use 301 instead.
  return res.redirect(302, safeUrl.href);
});

/* ---------------------------------------------------------- */
/*  Generic error handler (optional)                           */
/* ---------------------------------------------------------- */
app.use((err, _req, res, _next) => {
  console.error('Unhandled error:', err);
  res.status(500).json({ error: 'Internal Server Error' });
});

/* ---------------------------------------------------------- */
/*  Start the server                                           */
/* ---------------------------------------------------------- */
app.listen(port, () => {
  console.log(`🚀 Server listening on http://localhost:${port}`);
});
```

### How it works

| Step | What happens | Why it matters |
|------|--------------|----------------|
| **Missing `url`** | Returns **400** with a JSON error message. | Prevents ambiguous redirects and makes the API contract clear. |
| **URL validation** | Uses the native `URL` constructor and only accepts `http:` or `https:` schemes. | Stops open‑redirect attacks (e.g., `javascript:` URLs) and guarantees the target is reachable by a browser. |
| **Logging** | Captures timestamp, client IP, UA, referer and the destination URL. | Gives you the data you need for analytics, fraud detection, or debugging. Replace `console.log` with a proper logging/DB solution for production. |
| **Redirect** | Sends a **302** response pointing at the validated URL. | The user’s browser follows the link, while you have already recorded the click. |

