// Express app that tracks outbound clicks via /go?url=...
// ------------------------------------------------------------
const express = require('express');
const morgan = require('morgan');          // optional request logger
const helmet = require('helmet');          // basic security headers
const app = express();
const PORT = process.env.PORT || 3000;

// ------------------------------------------------------------
// Middleware
// ------------------------------------------------------------
