app.use(morgan('combined'));    // log every HTTP request (optional)

// ------------------------------------------------------------
// Helper: simple URL validation
// ------------------------------------------------------------
function isValidHttpUrl(str) {
  try {
    const url = new URL(str);
    // Only allow http(s) – you can expand this list if needed
    return url.protocol === 'http:' || url.protocol === 'https:';
  } catch (_) {
    return false;
  }
}

// ------------------------------------------------------------
// GET /go – tracking redirect
// ------------------------------------------------------------
app.get('/go', (req, res) => {
  const target = req.query.url;          // the external URL to forward to

  // ---- 1️⃣  Parameter missing? -------------------------------------------------
  if (!target) {
    return res.status(400).json({ error: 'Missing required query parameter: url' });
  }

  // ---- 2️⃣  Basic validation ----------------------------------------------------
  if (!isValidHttpUrl(target)) {
    return res.status(400).json({ error: 'Invalid url parameter – must be a valid http/https URL' });
  }

  // ---- 3️⃣  Log the click --------------------------------------------------------
  // You can replace this `console.log` with a real logger / DB write.
  console.log(
    JSON.stringify({
      timestamp: new Date().toISOString(),
      ip: req.ip,
      userAgent: req.get('User-Agent') || '',
      targetUrl: target,
      referrer: req.get('Referer') || '',
    })
  );

  // ---- 4️⃣  Redirect -------------------------------------------------------------
  // 302 (Found) is the default for `res.redirect`. Use 301 if you need a permanent redirect.
  return res.redirect(target);
});

// ------------------------------------------------------------
// Fallback route (optional)
// ------------------------------------------------------------
