import os
import datetime
from typing import Dict

import jwt  # PyJWT
from fastapi import FastAPI, HTTPException, Depends, status

# 读取签名密钥（若未设置则抛出异常，防止服务启动时出错）
JWT_SECRET = os.getenv("JWT_SECRET_KEY")
if not JWT_SECRET:
    raise RuntimeError("环境变量 JWT_SECRET_KEY 未设置")

# token 有效期（可自行调节）
JWT_EXPIRE_MINUTES = 60

app = FastAPI()


def issue_token(user_id: str, role: str) -> str:
    """
    生成 JWT，payload 包含 user_id、role 与过期时间。
    """
    expire = datetime.datetime.utcnow() + datetime.timedelta(minutes=JWT_EXPIRE_MINUTES)
    payload = {
        "sub": user_id,          # 主题（用户唯一标识）
        "role": role,
        "exp": expire,
        "iat": datetime.datetime.utcnow(),
    }
    token = jwt.encode(payload, JWT_SECRET, algorithm="HS256")
    # PyJWT 在 2.x 版本返回 str，旧版返回 bytes，统一转为 str
    return token if isinstance(token, str) else token.decode("utf-8")


def verify_token(token: str) -> Dict:
    """
    验证 JWT 并返回解码后的 claims。
    若验证失败抛出 HTTPException（401 Unauthorized）。
    """
    try:
        claims = jwt.decode(token, JWT_SECRET, algorithms=["HS256"])
        return claims
    except jwt.ExpiredSignatureError:
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Token 已过期",
        )
    except jwt.InvalidTokenError:
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="无效的 Token",
        )


# 示例路由 --------------------------------------------------------------
def get_current_user(token: str = Depends(lambda: None)):
    """
    FastAPI 依赖示例：从请求头中获取 token 并验证。
    实际使用时请改为从 Authorization: Bearer <token> 中提取。
    """
    if not token:
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="未提供 Token",
        )
    return verify_token(token)


@app.post("/login")
def login(user_id: str, role: str):
    """
    登录后返回 JWT（仅示例，实际应校验用户名密码）。
    """
    return {"access_token": issue_token(user_id, role)}


@app.get("/protected")
def protected(claims: Dict = Depends(get_current_user)):
    """
    受保护的接口，返回 token 中的 claims。
    """
    return {"message": "访问成功", "claims": claims}
```

