import os
import datetime
from typing import Dict

import jwt
from fastapi import FastAPI, HTTPException, Depends, Header

# ----- configuration -------------------------------------------------
SECRET_KEY = os.getenv("JWT_SECRET_KEY")          # signing key from env
ALGORITHM = "HS256"
ACCESS_TOKEN_EXPIRE_MINUTES = 60                  # token lifetime
# ---------------------------------------------------------------------

def issue_token(user_id: str, role: str) -> str:
    """
    Create a signed JWT containing the user id and role.
    """
    now = datetime.datetime.utcnow()
    payload = {
        "sub": user_id,                         # subject
        "role": role,
        "iat": now,                             # issued at
        "exp": now + datetime.timedelta(minutes=ACCESS_TOKEN_EXPIRE_MINUTES),
    }
    return jwt.encode(payload, SECRET_KEY, algorithm=ALGORITHM)


def verify_token(token: str) -> Dict:
    """
    Validate a JWT and return its decoded claims.
    Raises HTTPException (401) on any verification error.
    """
    try:
        return jwt.decode(token, SECRET_KEY, algorithms=[ALGORITHM])
    except jwt.ExpiredSignatureError:
        raise HTTPException(status_code=401, detail="Token has expired")
    except jwt.InvalidTokenError:
        raise HTTPException(status_code=401, detail="Invalid token")


# ----- FastAPI example ------------------------------------------------
app = FastAPI()


@app.post("/login")
def login(user_id: str, role: str):
    """
    Issue a token for the given user.
    """
    token = issue_token(user_id, role)
    return {"access_token": token}


def get_current_claims(authorization: str = Header(...)):
    """
    Dependency that extracts the token from the Authorization header
    and returns the decoded claims.
    """
    scheme, _, token = authorization.partition(" ")
    if scheme.lower() != "bearer" or not token:
        raise HTTPException(status_code=401, detail="Invalid authorization header")
    return verify_token(token)


@app.get("/protected")
def protected(claims: Dict = Depends(get_current_claims)):
    """
    Example protected endpoint – only reachable with a valid token.
    """
    return {"msg": "Access granted", "claims": claims}
# ----------------------------------------------------------------------
