// app.js
const express = require('express');
const cookieParser = require('cookie-parser');
const db = require('./db'); // db.getUserById(id) → Promise<User>

const app = express();

// secret for signed cookies (change to a strong random value)
app.use(cookieParser('your-secret-here'));

// -------------------------------------------------------------------
// Middleware: restore user from remember‑me cookie (run early)
app.use(async (req, res, next) => {
  // If user already authenticated (e.g., via session) skip
  if (req.user) return next();

  const token = req.signedCookies['remember_me'];
  if (!token) return next(); // no cookie → anonymous request

  try {
    // token format: userId:timestamp (simple; in real apps use JWT/opaque token)
    const [userId] = token.split(':');
    const user = await db.getUserById(userId);
    if (user) {
      req.user = user;               // attach user to request
      // refresh cookie expiration on each request
      setRememberMeCookie(res, user.id);
    }
  } catch (err) {
    // ignore errors – treat as unauthenticated
  }
  next();
});
// -------------------------------------------------------------------

// Helper: set the remember‑me cookie (30‑day expiry)
function setRememberMeCookie(res, userId) {
  const expires = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000); // 30 days
  const token = `${userId}:${Date.now()}`; // simple token; sign it below
  res.cookie('remember_me', token, {
    expires,
    httpOnly: true,
    signed: true,          // sign to prevent tampering
    sameSite: 'lax',
    // secure: true,       // enable in production (HTTPS)
  });
}

// -------------------------------------------------------------------
// Example login route – after successful authentication
app.post('/login', express.json(), async (req, res) => {
  const { username, password, rememberMe } = req.body;

  // ---- YOUR AUTH LOGIC HERE ----
  const user = await db.authenticate(username, password); // assume returns user or null
  if (!user) return res.status(401).json({ error: 'Invalid credentials' });

  // Set session or token as you normally would
  req.session.userId = user.id;

  // If "remember me" was checked, issue the cookie
  if (rememberMe) setRememberMeCookie(res, user.id);

  res.json({ success: true });
});
// -------------------------------------------------------------------

// Example protected route
app.get('/profile', (req, res) => {
  if (!req.user) return res.status(401).json({ error: 'Not logged in' });
  res.json({ user: req.user });
});

app.listen(3000, () => console.log('Server listening on :3000'));
