**Explanation (brief)**  
- `cookie-parser` parses signed cookies (`req.signedCookies`).  
- The first middleware checks for a `remember_me` cookie, extracts the user ID, fetches the user via `db.getUserById`, and attaches it to `req.user`. It also refreshes the cookie expiration on each request.  
- `setRememberMeCookie` creates a signed cookie that lasts 30 days.  
- In the login handler, after successful authentication, call `setRememberMeCookie` when the client requests “remember me”.  

Replace the placeholder authentication (`db.authenticate`) and secret with your production values. The code is ready to run with `npm install express cookie-parser`.

```js
// rememberMe.js
// Express middleware that issues a signed remember‑me cookie on login
// and restores req.user from that cookie on subsequent requests.

const express = require('express');
const cookieParser = require('cookie-parser');
const db = require('./db'); // db.getUserById(id) → Promise<User>

const app = express();

// use cookie‑parser with a secret to sign the cookie
app.use(cookieParser('your‑secret‑here'));

// -------------------------------------------------------------------
// 1️⃣ Middleware to restore req.user from the signed remember_me cookie
// -------------------------------------------------------------------
app.use(async (req, res, next) => {
  try {
    // If the request already has a user (e.g., session auth) skip
    if (req.user) return next();

    const userId = req.signedCookies.remember_me;
    if (!userId) return next();

    // Retrieve the user from the DB
    const user = await db.getUserById(userId);
    if (user) {
      req.user = user;               // attach user to the request
      // (optional) refresh cookie expiration on each hit
      res.cookie('remember_me', userId, {
        maxAge: 30 * 24 * 60 * 60 * 1000, // 30 days
        httpOnly: true,
        signed: true,
        sameSite: 'lax',
      });
    }
    next();
  } catch (err) {
    // On DB errors we just continue without a user
    next(err);
  }
});

// -------------------------------------------------------------------
// 2️⃣ Helper to set the remember‑me cookie after a successful login
// -------------------------------------------------------------------
function setRememberMeCookie(res, userId) {
  res.cookie('remember_me', userId, {
    maxAge: 30 * 24 * 60 * 60 * 1000, // 30 days
    httpOnly: true,
    signed: true,
    sameSite: 'lax',
  });
}

// -------------------------------------------------------------------
// 3️⃣ Example login route (replace with your actual auth logic)
// -------------------------------------------------------------------
app.post('/login', express.json(), async (req, res) => {
  const { username, password } = req.body;

  // ----> Replace with real authentication ----
  const user = await db.authenticate(username, password);
  // -------------------------------------------

  if (!user) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  // Set req.user for this request
  req.user = user;

  // Issue the remember‑me cookie
  setRememberMeCookie(res, user.id);

  res.json({ message: 'Logged in', userId: user.id });
});

// -------------------------------------------------------------------
// 4️⃣ Example logout route – clears the cookie
// -------------------------------------------------------------------
app.post('/logout', (req, res) => {
  res.clearCookie('remember_me');
  req.user = null;
  res.json({ message: 'Logged out' });
});

// -------------------------------------------------------------------
// 5️⃣ Protected route example
// -------------------------------------------------------------------
app.get('/profile', (req, res) => {
  if (!req.user) return res.status(401).json({ error: 'Not authenticated' });
  res.json({ profile: req.user });
});

