const COOKIE_MAX_AGE = 30 * 24 * 60 * 60 * 1000; // 30 days in ms

/* -------------------------------------------------------------
   Middleware: restore user from remember‑me cookie (if any)
   ------------------------------------------------------------- */
async function rememberMeMiddleware(req, res, next) {
  // If user is already authenticated, skip
  if (req.user) return next();

  // Look for a signed cookie containing the user id
  const signedId = req.signedCookies[REMEMBER_ME_COOKIE];
  if (!signedId) return next();

  try {
    const user = await db.getUserById(signedId);
    if (user) {
      req.user = user; // attach user to request
    }
  } catch (err) {
    // If DB lookup fails, just ignore – user stays unauthenticated
    console.error('Remember‑me lookup error:', err);
  }
  next();
}

/* -------------------------------------------------------------
   Helper: set remember‑me cookie after successful login
   ------------------------------------------------------------- */
function setRememberMeCookie(res, userId) {
  // Store the raw user id in a signed cookie (httpOnly for safety)
  res.cookie(REMEMBER_ME_COOKIE, userId, {
    maxAge: COOKIE_MAX_AGE,
    httpOnly: true,
    signed: true,
    sameSite: 'lax',
    // secure: true, // enable when using HTTPS
  });
}

/* -------------------------------------------------------------
   Example login route – replace with your real auth logic
   ------------------------------------------------------------- */
app.post('/login', async (req, res) => {
  const { username, password, rememberMe } = req.body;

  // ---- fake authentication for illustration ----
  const user = await db.authenticate(username, password); // returns user or null
  // ---------------------------------------------

  if (!user) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  // Attach user to request (session, JWT, etc. – omitted here)
  req.user = user;

  // If the client asked for "remember me", set the long‑lived cookie
  if (rememberMe) {
    setRememberMeCookie(res, user.id);
  }

  res.json({ message: 'Logged in' });
});

/* -------------------------------------------------------------
   Apply the remember‑me restoration middleware to all routes
   ------------------------------------------------------------- */
