// Express middleware for "remember me" functionality.
// Uses cookie-parser (must be registered before this middleware).

const cookieParser = require('cookie-parser');
const crypto = require('crypto');

// 30 days in milliseconds
const COOKIE_MAX_AGE = 30 * 24 * 60 * 60 * 1000;

// Name of the remember‑me cookie
const COOKIE_NAME = 'remember_me';

// ----------------------------------------------------------------------
// Helper: generate a random token to store in the cookie.
// In a real app you would also store this token (or a hash of it) in the DB
// to allow revocation, but for simplicity we just store the user id.
function generateToken(userId) {
  // Here we simply encode the user id; you could also encrypt/sign it.
  const payload = `${userId}:${Date.now()}`;
  return Buffer.from(payload).toString('base64url');
}

// Helper: decode token back to userId
function decodeToken(token) {
  try {
    const decoded = Buffer.from(token, 'base64url').toString('utf8');
    const [userId] = decoded.split(':');
    return userId;
  } catch (_) {
    return null;
  }
}

// ----------------------------------------------------------------------
// Middleware to read the remember‑me cookie and populate req.user
async function rememberMeMiddleware(req, res, next) {
  // If user is already authenticated, skip
  if (req.user) return next();

  const token = req.signedCookies[COOKIE_NAME];
  if (!token) return next();

  const userId = decodeToken(token);
  if (!userId) return next();

  try {
    const user = await db.getUserById(userId);
    if (user) {
      req.user = user; // restore logged‑in user
    }
  } catch (err) {
    console.error('Remember‑me error:', err);
  }

  next();
}

// ----------------------------------------------------------------------
// Call this after a successful login to set the remember‑me cookie
