// rememberMe.js
// Express middleware + helper to manage a 30‑day "remember‑me" cookie.
// Requires: npm i express cookie-parser
// Assumes a DB helper: db.getUserById(id) => Promise<User|null>

const cookieParser = require('cookie-parser');
const crypto = require('crypto');

// Secret used to sign the cookie (change to a strong, env‑based value)
const COOKIE_SECRET = process.env.COOKIE_SECRET || 'change_this_secret';

// Name of the remember‑me cookie
const COOKIE_NAME = 'remember_me';

// Duration: 30 days (in milliseconds)
const COOKIE_MAX_AGE = 30 * 24 * 60 * 60 * 1000;

/**
 * Middleware to parse cookies and restore req.user from the remember‑me cookie.
 * Place this after `app.use(cookieParser(COOKIE_SECRET))`.
 */
async function rememberMeMiddleware(req, res, next) {
  // If user already authenticated (e.g., via session), skip.
  if (req.user) return next();

  const token = req.signedCookies[COOKIE_NAME];
  if (!token) return next();

  // Token format: base64(userId):hmac
  const [encodedId, sentHmac] = token.split(':');
  if (!encodedId || !sentHmac) return next();

  const userId = Buffer.from(encodedId, 'base64').toString('utf8');

  // Verify HMAC to prevent tampering
  const expectedHmac = crypto
    .createHmac('sha256', COOKIE_SECRET)
    .update(encodedId)
    .digest('hex');

  if (!crypto.timingSafeEqual(Buffer.from(sentHmac), Buffer.from(expectedHmac))) {
    // Invalid token – clear cookie
    res.clearCookie(COOKIE_NAME);
    return next();
  }

  try {
    const user = await db.getUserById(userId);
    if (user) {
      req.user = user; // restore authenticated user on the request
    } else {
      // User not found – clear stale cookie
      res.clearCookie(COOKIE_NAME);
    }
  } catch (err) {
    // DB error – just pass through, don't crash
    console.error('Remember‑me DB error:', err);
  }

  return next();
}

/**
 * Call after successful login to set the remember‑me cookie.
 * @param {Response} res Express response object
 * @param {string|number} userId ID of the authenticated user
 */
function setRememberMeCookie(res, userId) {
  const encodedId = Buffer.from(String(userId), 'utf8').toString('base64');
  const hmac = crypto.createHmac('sha256', COOKIE_SECRET).update(encodedId).digest('hex');
  const token = `${encodedId}:${hmac}`;

  res.cookie(COOKIE_NAME, token, {
    maxAge: COOKIE_MAX_AGE,
    httpOnly: true,
    signed: true,
    sameSite: 'lax', // adjust to 'strict' or 'none' as needed
    // secure: true, // uncomment when serving over HTTPS
  });
}

/**
 * Call after logout or when the user disables remember‑me.
 * @param {Response} res Express response object
 */
function clearRememberMeCookie(res) {
  res.clearCookie(COOKIE_NAME);
}

// Export everything needed by the app
module.exports = {
  rememberMeMiddleware,
  setRememberMeCookie,
  clearRememberMeCookie,
};
