// apiKeyService.js
// Simple service for generating and validating API keys using PostgreSQL (pg).

const crypto = require('crypto');
const { Pool } = require('pg');

// ---------- PostgreSQL connection ----------
const pool = new Pool({
  // Adjust connection settings to your environment
  user: 'your_pg_user',
  host: 'your_pg_host',
  database: 'your_pg_db',
  password: 'your_pg_password',
  port: 5432,
});

// ---------- Helper: create a secure random key ----------
/**
 * Generates a URL‑safe base64 string (43 characters ≈ 256‑bit entropy).
 */
function createRandomKey() {
  // 32 bytes = 256 bits
  return crypto.randomBytes(32).toString('base64url');
}

// ---------- Public API ----------

/**
 * Generates a new API key for a given customer, stores its hash in the DB,
 * and returns the plain key (shown only once to the customer).
 *
 * @param {string|number} customerId - Identifier of the customer.
 * @returns {Promise<string>} The newly generated API key.
 */
async function generateApiKey(customerId) {
  const plainKey = createRandomKey();

  // Store only a hash of the key for security.
  const keyHash = crypto.createHash('sha256').update(plainKey).digest('hex');

  const query = `
    INSERT INTO api_keys (customer_id, key_hash, created_at)
    VALUES ($1, $2, NOW())
    RETURNING id
  `;

  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    await client.query(query, [customerId, keyHash]);
    await client.query('COMMIT');
    return plainKey; // Show this once to the customer.
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release();
  }
}

/**
 * Checks whether a presented API key exists (and is valid) in the DB.
 *
 * @param {string} presentedKey - The API key supplied by the client.
 * @returns {Promise<boolean>} True if the key is valid, otherwise false.
 */
async function isApiKeyValid(presentedKey) {
  const keyHash = crypto.createHash('sha256').update(presentedKey).digest('hex');

  const query = `
    SELECT 1 FROM api_keys
    WHERE key_hash = $1
    LIMIT 1
  `;

  const { rows } = await pool.query(query, [keyHash]);
  return rows.length > 0;
}

// ---------- Export ----------
module.exports = {
  generateApiKey,
  isApiKeyValid,
};
