// rememberMe.js
// Express middleware that sets a 30‑day remember‑me cookie on login
// and restores req.user from the cookie on subsequent requests.

const cookieParser = require('cookie-parser'); // npm i cookie-parser
const db = require('./db'); // db.getUserById(id) → Promise<User>

const COOKIE_NAME = 'remember_me';
const COOKIE_OPTS = {
  maxAge: 30 * 24 * 60 * 60 * 1000, // 30 days (ms)
  httpOnly: true,
  signed: true,                     // requires a secret in cookieParser()
  // secure: true,                  // enable in production (HTTPS only)
};

/**
 * Call after a successful login to issue the remember‑me cookie.
 * @param {Response} res
 * @param {string|number} userId
 */
function issueRememberMeCookie(res, userId) {
  res.cookie(COOKIE_NAME, userId, COOKIE_OPTS);
}

/**
 * Middleware that checks for a signed remember‑me cookie.
 * If present, loads the user from the DB and attaches it to req.user.
 */
async function rememberMeMiddleware(req, res, next) {
  // If the request is already authenticated, skip.
  if (req.user) return next();

  const token = req.signedCookies[COOKIE_NAME];
  if (!token) return next();

  try {
    const user = await db.getUserById(token);
    if (user) {
      req.user = user;               // restore authentication
      // Refresh the cookie expiration on each hit
      issueRememberMeCookie(res, user.id);
    }
  } catch (err) {
    console.error('Remember‑Me error:', err);
    // ignore errors – treat as unauthenticated
  }
  next();
}

/**
 * Helper to plug cookie‑parser + remember‑me into an Express app.
 * @param {Express} app
 * @param {string} secret – secret for signed cookies
 */
function applyRememberMe(app, secret) {
  app.use(cookieParser(secret));      // must be before the middleware
  app.use(rememberMeMiddleware);
}

module.exports = {
  applyRememberMe,
  issueRememberMeCookie,
  rememberMeMiddleware,
};
