// Node.js service for generating and verifying API keys using PostgreSQL (pg)

const { Pool } = require('pg');
const crypto = require('crypto');

// ---- PostgreSQL connection pool ----
const pool = new Pool({
  user: 'your_pg_user',
  host: 'your_pg_host',
  database: 'your_pg_db',
  password: 'your_pg_password',
  port: 5432, // default PostgreSQL port
});

// ---- Helper: hash an API key ----
// Store only a hash in the database for security.
function hashKey(key) {
  // SHA‑256 is sufficient for this purpose.
  return crypto.createHash('sha256').update(key).digest('hex');
}

// ---- Generate a new API key for a customer ----
// Returns the plain key (to be shown to the customer once) and stores its hash.
async function generateApiKey(customerId) {
  // 32 random bytes → 256‑bit key, encoded as URL‑safe Base64
  const rawKey = crypto.randomBytes(32).toString('base64url');

  const keyHash = hashKey(rawKey);

  const client = await pool.connect();
  try {
    await client.query(
      `INSERT INTO api_keys (customer_id, key_hash, created_at)
       VALUES ($1, $2, NOW())
       ON CONFLICT (customer_id) DO UPDATE
         SET key_hash = EXCLUDED.key_hash,
             created_at = EXCLUDED.created_at`,
      [customerId, keyHash]
    );
  } finally {
    client.release();
  }

  // Return the plain key only once – the caller should display it to the customer.
  return rawKey;
}

// ---- Verify a presented API key ----
// Returns the matching row (or null) if the key is valid.
async function verifyApiKey(presentedKey) {
  const keyHash = hashKey(presentedKey);

  const { rows } = await pool.query(
    `SELECT * FROM api_keys WHERE key_hash = $1`,
    [keyHash]
  );

  // If a row is found the key is valid; otherwise it's invalid.
  return rows[0] || null;
}

// ---- Export the functions ----
module.exports = {
  generateApiKey,
  verifyApiKey,
};
