// Node.js service for generating and validating API keys using PostgreSQL (pg)

const { Pool } = require('pg');
const crypto = require('crypto');

// PostgreSQL connection pool – configure via environment variables
const pool = new Pool({
  connectionString: process.env.DATABASE_URL, // e.g. postgres://user:pw@host:5432/db
});

// Length of the generated key (bytes). 32 bytes → 64‑hex chars.
const KEY_BYTE_LENGTH = 32;

/**
 * Generates a new API key for a given customer, stores it in the `api_keys` table,
 * and returns the plain key (shown to the customer only once).
 *
 * Table schema example:
 *   CREATE TABLE api_keys (
 *     id SERIAL PRIMARY KEY,
 *     customer_id INTEGER NOT NULL,
 *     api_key_hash TEXT NOT NULL,
 *     created_at TIMESTAMP WITH TIME ZONE DEFAULT now()
 *   );
 *
 * @param {number} customerId - ID of the customer who will own the key.
 * @returns {Promise<string>} The newly generated API key (plain text).
 */
async function generateApiKey(customerId) {
  // 1️⃣ Create a cryptographically‑secure random key.
  const plainKey = crypto.randomBytes(KEY_BYTE_LENGTH).toString('hex');

  // 2️⃣ Hash the key before storing (prevents leakage if DB is compromised).
  const keyHash = crypto.createHash('sha256').update(plainKey).digest('hex');

  // 3️⃣ Insert the hash into the database.
  const query = `
    INSERT INTO api_keys (customer_id, api_key_hash)
    VALUES ($1, $2)
    RETURNING id
  `;
  const values = [customerId, keyHash];

  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    await client.query(query, values);
    await client.query('COMMIT');
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release();
  }

  // 4️⃣ Return the plain key (only shown once to the caller).
  return plainKey;
}

/**
 * Checks whether a presented API key exists in the `api_keys` table.
 *
 * @param {string} presentedKey - The API key supplied by a client.
 * @returns {Promise<{valid: boolean, customerId?: number}>}
 *          An object indicating validity and, if valid, the associated customer ID.
 */
async function checkApiKey(presentedKey) {
  // Hash the presented key in the same way as during generation.
  const keyHash = crypto.createHash('sha256').update(presentedKey).digest('hex');

  const query = `
    SELECT customer_id
    FROM api_keys
    WHERE api_key_hash = $1
    LIMIT 1
  `;
  const values = [keyHash];

  const { rows } = await pool.query(query, values);
  if (rows.length === 0) {
    return { valid: false };
  }
  return { valid: true, customerId: rows[0].customer_id };
}

// Export functions for use elsewhere in the application
module.exports = {
  generateApiKey,
  checkApiKey,
};
