// apiKeyService.js
// Simple API‑key generator & validator using PostgreSQL (pg) and Node.js crypto.
// Stores only a SHA‑256 hash of the key for security.

const { Pool } = require('pg');
const crypto = require('crypto');

// ---- PostgreSQL connection -------------------------------------------------
const pool = new Pool({
  connectionString: process.env.DATABASE_URL, // e.g. postgres://user:pw@host/db
  // ssl: { rejectUnauthorized: false }, // uncomment if using Heroku/Postgres SSL
});

// ---- Helper: hash an API key ------------------------------------------------
function hashKey(key) {
  // SHA‑256 is fast; for production consider a slower KDF (bcrypt, argon2, etc.)
  return crypto.createHash('sha256').update(key).digest('hex');
}

// ---- Generate a new API key for a customer ---------------------------------
/**
 * Creates a new API key, stores its hash in `api_keys`, and returns the plain key.
 * @param {number|string} customerId - Identifier of the customer.
 * @returns {Promise<string>} The newly generated API key (plain text).
 */
async function generateApiKey(customerId) {
  // 32 random bytes → 64‑hex‑char string (256‑bit key)
  const plainKey = crypto.randomBytes(32).toString('hex');
  const keyHash = hashKey(plainKey);

  const query = `
    INSERT INTO api_keys (customer_id, key_hash, created_at)
    VALUES ($1, $2, NOW())
    RETURNING id
  `;

  await pool.query(query, [customerId, keyHash]); // ignore returned id for now
  return plainKey; // give the plain key to the customer only once
}

// ---- Validate a presented API key ------------------------------------------
/**
 * Checks whether a supplied API key exists in the database.
 * @param {string} presentedKey - API key provided by the caller.
 * @returns {Promise<{valid: boolean, customerId?: number}>}
 *          `valid` is true when the key matches; `customerId` is returned if valid.
 */
async function checkApiKey(presentedKey) {
  const keyHash = hashKey(presentedKey);

  const query = `
    SELECT customer_id
    FROM api_keys
    WHERE key_hash = $1
    LIMIT 1
  `;

  const { rows } = await pool.query(query, [keyHash]);

  if (rows.length === 0) {
    return { valid: false };
  }
  return { valid: true, customerId: rows[0].customer_id };
}

// ---- Export functions --------------------------------------------------------
module.exports = {
  generateApiKey,
  checkApiKey,
};
