function getProductList(mysqli $db): array
{
    // ----- 1. Read & validate input -------------------------------------------------
    $page       = isset($_GET['page']) && ctype_digit($_GET['page']) ? (int)$_GET['page'] : 1;
    $sortField  = $_GET['sort'] ?? 'id';
    $searchTerm = $_GET['search'] ?? '';

    // Allow only specific columns for sorting to prevent injection.
    $allowedSort = ['id', 'name', 'price', 'created_at'];
    if (!in_array($sortField, $allowedSort, true)) {
        $sortField = 'id';
    }

    $pageSize = 20;                     // rows per page
    $offset   = ($page - 1) * $pageSize;

    // ----- 2. Build the base SQL ----------------------------------------------------
    $sql = "SELECT id, name, price, created_at
            FROM products
            WHERE 1";

    $params = [];
    $types  = '';

    // Add search condition if a term is provided
    if ($searchTerm !== '') {
        $sql .= " AND name LIKE ?";
        $params[] = '%' . $searchTerm . '%';
        $types   .= 's';
    }

    // Append ordering, limit and offset
    $sql .= " ORDER BY $sortField ASC LIMIT ? OFFSET ?";
    $params[] = $pageSize;
    $params[] = $offset;
    $types   .= 'ii';

    // ----- 3. Prepare & execute ------------------------------------------------------
    $stmt = $db->prepare($sql);
    if ($stmt === false) {
        // In production you might log this error instead of exposing it.
        throw new RuntimeException('Database error: ' . $db->error);
    }

    // Bind parameters dynamically
    if ($params) {
        $stmt->bind_param($types, ...$params);
    }

    $stmt->execute();
    $result = $stmt->get_result();

    // ----- 4. Fetch rows -------------------------------------------------------------
    $rows = $result->fetch_all(MYSQLI_ASSOC);

    // Clean up
    $stmt->close();

    return $rows;
}
