import re
from flask import current_app, render_template, render_template_string
from jinja2 import TemplateNotFound

def _user_to_context(user):
    """
    Convert a user object or dict into a plain dict for Jinja2.
    """
    if isinstance(user, dict):
        return user
    # Fallback: expose public attributes (no callables, no private attrs)
    return {
        attr: getattr(user, attr)
        for attr in dir(user)
        if not attr.startswith('_')
        and not callable(getattr(user, attr))
    }

def _is_safe_template_name(name: str) -> bool:
    """
    Allow only alphanumerics, hyphens and underscores to avoid path traversal.
    """
    return bool(re.fullmatch(r'[\w-]+', name))

def render_email(template_name: str, user, custom_template: str = None) -> str:
    """
    Render an email template.

    - If ``custom_template`` is provided, it is rendered directly (admin override).
    - Otherwise the function loads ``templates/emails/<template_name>.html``.
    - ``user`` can be a dict or an object; its public fields become the template context.
    """
    if not _is_safe_template_name(template_name):
        raise ValueError(f'Invalid template name: {template_name!r}')

    context = _user_to_context(user)

    # Admin‑provided raw template string takes precedence
    if custom_template is not None:
        return render_template_string(custom_template, **context)

    # Load the file‑based template from the Flask templates folder
    try:
        # Assuming email templates are stored under a subfolder "emails"
        return render_template(f'emails/{template_name}.html', **context)
    except TemplateNotFound as exc:
        # Convert Jinja2's exception to a more generic, app‑level error
        raise FileNotFoundError(f'Email template "{template_name}" not found') from exc
