//   verify(query) → true if signature is valid and not expired.

const crypto = require('crypto');

// Secret used for HMAC – set via env var in production.
const SECRET = process.env.URL_SIGNING_SECRET || 'change_this_secret';

/**
 * Create a signed query string for a download URL.
 * @param {string} path        – Resource path (e.g. "/files/report.pdf").
 * @param {number|Date} expiresAt – Expiry time (Unix seconds or Date).
 * @returns {string} Query string (no leading '?').
 */
function sign(path, expiresAt) {
  const expires = typeof expiresAt === 'number'
    ? expiresAt
    : Math.floor(new Date(expiresAt).getTime() / 1000);

  const data = `${path}:${expires}`;
  const sig = crypto.createHmac('sha256', SECRET).update(data).digest('hex');

  const params = new URLSearchParams({ path, expires: expires.toString(), sig });
  return params.toString(); // e.g. "path=/file&expires=1735689600&sig=..."
}

/**
 * Verify a signed query string.
 * @param {string} query – The raw query string (with or without leading '?').
 * @returns {boolean} True if signature matches and not expired.
 */
function verify(query) {
  // Strip leading '?' if present.
  const cleanQuery = query.startsWith('?') ? query.slice(1) : query;
  const params = new URLSearchParams(cleanQuery);

  const path = params.get('path');
  const expires = params.get('expires');
  const sig = params.get('sig');

  if (!path || !expires || !sig) return false;

  const now = Math.floor(Date.now() / 1000);
  if (now > Number(expires)) return false; // expired

  const data = `${path}:${expires}`;
  const expected = crypto.createHmac('sha256', SECRET).update(data).digest('hex');

  // Use timing‑safe comparison.
  const bufSig = Buffer.from(sig, 'hex');
  const bufExp = Buffer.from(expected, 'hex');
  if (bufSig.length !== bufExp.length) return false;

  return crypto.timingSafeEqual(bufSig, bufExp);
}

module.exports = { sign, verify };
