  const now = Date.now();
  if (now > Number(exp)) return false;

  // Re‑create the signature
  const data = `path=${encodeURIComponent(path)}&exp=${exp}`;
  const expectedSig = crypto.createHmac('sha256', SECRET).update(data).digest('hex');

