```js
// app.js
// Express server with a file‑upload route using multer.
// Accepts PDF and Word documents, stores them in ./uploads, and returns the saved file name.

const express = require('express');
const multer  = require('multer');
const path    = require('path');
const fs      = require('fs');

const app = express();
const PORT = process.env.PORT || 3000;

// Ensure the upload directory exists
const uploadDir = path.join(__dirname, 'uploads');
if (!fs.existsSync(uploadDir)) {
  fs.mkdirSync(uploadDir);
}

// Multer storage configuration – keep original name (or you can generate a unique name)
const storage = multer.diskStorage({
  destination: (req, file, cb) => cb(null, uploadDir),
  filename: (req, file, cb) => {
    // Optionally prepend a timestamp to avoid name collisions
    const timestamp = Date.now();
    const cleanName = file.originalname.replace(/\s+/g, '_');
    cb(null, `${timestamp}_${cleanName}`);
  }
});

// File filter – only allow PDF and Word docs
const fileFilter = (req, file, cb) => {
  const allowed = [
    'application/pdf',
    // Word 2007+ (docx) and older (doc)
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    'application/msword'
  ];
  if (allowed.includes(file.mimetype)) {
    cb(null, true);
  } else {
    cb(new Error('Only PDF and Word documents are allowed'), false);
  }
};

const upload = multer({ storage, fileFilter });

// Route: POST /upload
app.post('/upload', upload.single('document'), (req, res) => {
  // If multer threw an error, it would be caught by the error‑handling middleware below.
  if (!req.file) {
    return res.status(400).json({ error: 'No file uploaded' });
  }
  // Return the stored file name (you could also return the full path or a URL)
  res.json({ filename: req.file.filename });
});

// Basic error‑handling middleware for multer errors
app.use((err, req, res, next) => {
  if (err instanceof multer.MulterError || err.message) {
    return res.status(400).json({ error: err.message });
  }
  next(err);
});

app.listen(PORT, () => {
  console.log(`Server listening on http://localhost:${PORT}`);
});
