    Triggers ./deploy.sh <branch> only for pushes to the main branch.
    """
    payload = await request.json()

    # Ensure this is a push event
    if payload.get("hook") is None and payload.get("ref") is None:
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail="Invalid GitHub webhook payload",
        )

    ref = payload.get("ref", "")
    # GitHub ref format: refs/heads/<branch>
    branch = ref.split("/")[-1] if ref.startswith("refs/heads/") else None

    # Only deploy for the main branch
    if branch != "main":
        return JSONResponse(
            {"message": f"Ignored push to branch '{branch}'"},
            status_code=status.HTTP_200_OK,
        )

    # Run the deployment script with the branch name as argument
    try:
        result = subprocess.run(
            ["./deploy.sh", branch],
            check=True,
            capture_output=True,
            text=True,
        )
        return JSONResponse(
            {
                "message": f"Deployment triggered for branch '{branch}'",
                "stdout": result.stdout,
                "stderr": result.stderr,
            },
            status_code=status.HTTP_202_ACCEPTED,
        )
    except subprocess.CalledProcessError as e:
        # Deployment script failed
        return JSONResponse(
            {
                "message": f"Deployment failed for branch '{branch}'",
                "stdout": e.stdout,
                "stderr": e.stderr,
            },
            status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,
        )
