from typing import Dict, Any

def _mask_secret(value: str) -> str:
    """Mask a secret value, leaving only the first/last character visible."""
    if not value:
        return ""
    # Show first and last character, replace the rest with asterisks
    return f"{value[0]}{'*' * (len(value) - 2)}{value[-1]}" if len(value) > 2 else "***"

def _collect_env_vars() -> Dict[str, Any]:
    """Collect environment variables, masking likely secrets."""
    masked_keys = {"PASSWORD", "SECRET", "TOKEN", "KEY", "API_KEY", "DB_PASS"}
    env = {}
    for key, val in os.environ.items():
        # If the key name contains any of the masked keywords, mask its value
        if any(mask_word in key.upper() for mask_word in masked_keys):
            env[key] = _mask_secret(val)
        else:
            env[key] = val
    return env

def _collect_db_settings() -> Dict[str, Any]:
    """Extract common DB settings from the environment."""
    # Typical DB env vars – adjust names to match your deployment
    db_keys = ["DB_HOST", "DB_PORT", "DB_NAME", "DB_USER", "DB_PASS"]
    db_cfg = {}
    for key in db_keys:
        val = os.getenv(key)
        if val is not None:
            # Mask password
            if "PASS" in key:
                db_cfg[key] = _mask_secret(val)
            else:
                db_cfg[key] = val
    return db_cfg

def _collect_api_settings() -> Dict[str, Any]:
    """Extract third‑party API settings from the environment."""
    api_keys = ["API_BASE_URL", "API_KEY", "API_TOKEN"]
    api_cfg = {}
    for key in api_keys:
        val = os.getenv(key)
        if val is not None:
            # Mask API keys/tokens
            if any(secret in key for secret in ("KEY", "TOKEN")):
                api_cfg[key] = _mask_secret(val)
            else:
                api_cfg[key] = val
    return api_cfg

def get_runtime_config() -> str:
    """
    Return a JSON string containing the current runtime configuration.
    Includes:
      • All environment variables (with secrets masked)
      • Database connection settings
      • Third‑party API settings
    """
    config = {
        "environment": _collect_env_vars(),
        "database": _collect_db_settings(),
        "third_party_apis": _collect_api_settings(),
    }
    # Ensure ASCII characters are escaped for safe JSON transport
    return json.dumps(config, indent=2, ensure_ascii=False)

