    Simple mask for secret values (e.g., passwords, tokens).
    Shows only the first and last character, replaces the rest with '*'.
    """
    if not value or len(value) <= 2:
        return '*' * len(value)
    return f"{value[0]}{'*' * (len(value) - 2)}{value[-1]}"


def _gather_config() -> dict:
    """
    Collect runtime configuration:
    - Selected environment variables
    - Flask app config (DB & third‑party API settings)
    Sensitive values are masked.
    """
