        "SQLALCHEMY_DATABASE_URI": _filter_secret(
            current_app.config.get("SQLALCHEMY_DATABASE_URI", "")
        ),
        "SQLALCHEMY_ECHO": current_app.config.get("SQLALCHEMY_ECHO", False),
