// index.js
// Simple Express server that connects to MongoDB and provides a /health endpoint.
// Run locally with defaults: PORT=3000, MONGO_URI=mongodb://localhost:27017/healthdb

const express = require('express');
const { MongoClient } = require('mongodb');

// ----- Configuration -----
const PORT = process.env.PORT || 3000;
const MONGO_URI = process.env.MONGO_URI || 'mongodb://localhost:27017/healthdb';
const DB_NAME = process.env.DB_NAME || 'healthdb';

// ----- Initialize Express -----
const app = express();

// ----- MongoDB connection -----
let dbClient;

async function connectToMongo() {
  try {
    const client = new MongoClient(MONGO_URI, {
      useNewUrlParser: true,
      useUnifiedTopology: true,
    });
    await client.connect();
    dbClient = client;
    console.log(`✅ Connected to MongoDB at ${MONGO_URI}`);
    console.log(`   Database: ${DB_NAME}`);
  } catch (err) {
    console.error('❌ Failed to connect to MongoDB:', err);
    process.exit(1);
  }
}

// ----- Health endpoint -----
app.get('/health', async (req, res) => {
  // Simple check: is the DB client alive?
  const mongoStatus = dbClient && dbClient.isConnected() ? 'up' : 'down';
  res.json({
    status: 'ok',
    mongo: mongoStatus,
    timestamp: new Date().toISOString(),
  });
});

// ----- Start server after DB connection -----
(async () => {
  await connectToMongo();

  app.listen(PORT, () => {
    console.log(`🚀 Express server listening on http://localhost:${PORT}`);
    console.log('   /health endpoint ready');
  });
})();

// ----- Graceful shutdown -----
process.on('SIGINT', async () => {
  console.log('\n🛑 Shutting down...');
  if (dbClient) await dbClient.close();
  process.exit(0);
});
