import json
from dataclasses import dataclass, asdict, fields, is_dataclass
from datetime import datetime, date
from typing import Any, Dict, List, Union

# ----------------------------------------------------------------------
# Example custom dataclass that may appear inside the preferences object.
# ----------------------------------------------------------------------
@dataclass
class Preference:
    name: str
    enabled: bool
    threshold: float = 0.0


# ----------------------------------------------------------------------
# JSON encoder that knows how to turn dates and Preference objects into
# a JSON‑serialisable form.
# ----------------------------------------------------------------------
class _PrefsEncoder(json.JSONEncoder):
    def default(self, o: Any) -> Any:
        # Serialize datetime/date as ISO strings with a type hint.
        if isinstance(o, (datetime, date)):
            return {"__type__": "datetime", "value": o.isoformat()}

        # Serialize Preference dataclass as a dict with a type hint.
        if isinstance(o, Preference):
            data = asdict(o)
            data["__type__"] = "Preference"
            return data

        # Let the base class raise the TypeError for anything else.
        return super().default(o)


# ----------------------------------------------------------------------
# Helper to recursively restore objects that were tagged by the encoder.
# ----------------------------------------------------------------------
def _restore(obj: Any) -> Any:
    if isinstance(obj, dict):
        # Detect our custom type markers.
        type_tag = obj.get("__type__")
        if type_tag == "datetime":
            return datetime.fromisoformat(obj["value"])
        if type_tag == "Preference":
            # Build a Preference instance from the remaining fields.
            field_names = {f.name for f in fields(Preference)}
            init_kwargs = {k: v for k, v in obj.items() if k in field_names}
            return Preference(**init_kwargs)

        # Otherwise walk the dict recursively.
        return {k: _restore(v) for k, v in obj.items()}

    if isinstance(obj, list):
        return [_restore(item) for item in obj]

    # Primitive types are returned unchanged.
    return obj


# ----------------------------------------------------------------------
# Public API ------------------------------------------------------------
# ----------------------------------------------------------------------
def save_user_settings(obj: Any) -> bytes:
    """
    Serialize a preferences object (nested dicts/lists, dates, Preference
    instances) into a JSON byte string suitable for storage in a cookie.
    """
    json_str = json.dumps(obj, cls=_PrefsEncoder, separators=(",", ":"))
    return json_str.encode("utf-8")


def load_user_settings(blob: bytes) -> Any:
    """
    Deserialize a JSON byte string (produced by ``save_user_settings``)
    back into the original Python object, reconstructing dates and
    Preference instances.
    """
    json_str = blob.decode("utf-8")
    raw = json.loads(json_str)
    return _restore(raw)


# ----------------------------------------------------------------------
# Example usage (remove or comment out in production) -------------------
# ----------------------------------------------------------------------
if __name__ == "__main__":
    example = {
        "theme": "dark",
        "last_login": datetime.utcnow(),
        "prefs": [
            Preference(name="auto_save", enabled=True, threshold=0.75),
            Preference(name="notifications", enabled=False),
        ],
        "nested": {"date_list": [date(2023, 1, 1), date(2024, 12, 31)]},
    }

    blob = save_user_settings(example)
    restored = load_user_settings(blob)

    assert restored == example  # sanity check
    print("Serialization round‑trip succeeded.")
