import json
import base64
from dataclasses import dataclass, asdict, fields, is_dataclass
from datetime import datetime
from typing import Any, Dict, List, Union

# ----------------------------------------------------------------------
# Example custom dataclass that may appear in the preferences object
# ----------------------------------------------------------------------
@dataclass
class Preference:
    name: str
    value: Any
    enabled: bool = True


# ----------------------------------------------------------------------
# JSON encoder/decoder helpers
# ----------------------------------------------------------------------
def _encode_obj(obj: Any) -> Any:
    """Convert Python objects to JSON‑serialisable structures."""
    if isinstance(obj, datetime):
        # Mark datetimes so they can be restored
        return {"__type__": "datetime", "value": obj.isoformat()}
    if is_dataclass(obj):
        # Store the class name and its fields
        data = asdict(obj)
        data["__type__"] = obj.__class__.__name__
        return data
    if isinstance(obj, (list, tuple)):
        return [_encode_obj(item) for item in obj]
    if isinstance(obj, dict):
        return {key: _encode_obj(val) for key, val in obj.items()}
    # Primitive types are returned unchanged
    return obj


def _decode_obj(dct: Dict) -> Any:
    """Re‑create Python objects from the JSON structures."""
    if "__type__" not in dct:
        return dct
    typ = dct.pop("__type__")
    if typ == "datetime":
        return datetime.fromisoformat(dct["value"])
    if typ == "Preference":
        # Re‑construct the Preference dataclass
        field_names = {f.name for f in fields(Preference)}
        init_kwargs = {k: v for k, v in dct.items() if k in field_names}
        return Preference(**init_kwargs)
    # Unknown custom type – return as‑is (or raise)
    dct["__type__"] = typ
    return dct


# ----------------------------------------------------------------------
# Public API
# ----------------------------------------------------------------------
def save_user_settings(obj: Any) -> bytes:
    """
    Serialise a user‑settings object (nested dicts/lists, dates,
    Preference instances) to a bytes blob suitable for a cookie.
    """
    # Convert to a JSON‑serialisable structure, then dump as UTF‑8 JSON
    serialisable = _encode_obj(obj)
    json_str = json.dumps(serialisable, separators=(",", ":"))
    # Cookies expect ASCII; base64‑encode the UTF‑8 payload
    return base64.urlsafe_b64encode(json_str.encode("utf-8"))


def load_user_settings(blob: bytes) -> Any:
    """
    Restore a user‑settings object from the bytes blob produced by
    ``save_user_settings``.
    """
    # Decode the base64 payload and parse JSON with our custom hook
    json_str = base64.urlsafe_b64decode(blob).decode("utf-8")
    return json.loads(json_str, object_hook=_decode_obj)
