    """
    Parse a YAML string describing a job and return a Job instance.
    Expected fields: name, schedule, command, env (optional).
    """
    try:
        data = yaml.safe_load(yaml_str) or {}
    except yaml.YAMLError as e:
        raise ValueError(f"Invalid YAML: {e}")

    # Basic validation
    required = ["name", "schedule", "command"]
    missing = [field for field in required if field not in data]
    if missing:
        raise ValueError(f"Missing required job fields: {', '.join(missing)}")

    name = str(data["name"])
    schedule = str(data["schedule"])

    # command can be a string or a list; ensure we store a list for subprocess
    raw_cmd = data["command"]
    if isinstance(raw_cmd, str):
        command = raw_cmd.strip().split()
    elif isinstance(raw_cmd, list):
        command = [str(part) for part in raw_cmd]
    else:
        raise ValueError("command must be a string or a list of strings")

    env = {}
    if "env" in data:
        if not isinstance(data["env"], dict):
            raise ValueError("env must be a mapping of key/value strings")
        env = {str(k): str(v) for k, v in data["env"].items()}

    return Job(name=name, schedule=schedule, command=command, env=env)
