    except yaml.YAMLError as e:
        raise ValueError(f"Invalid YAML: {e}")

    # Validate required fields
    for field_name in ("name", "schedule", "command"):
        if field_name not in data:
            raise ValueError(f"Missing required field: {field_name}")

    # Ensure env is a dict if provided
    env = data.get("env") or {}
    if not isinstance(env, dict):
        raise ValueError("Field 'env' must be a mapping of strings")

    # Tokenise command string for subprocess (handles quoting)
    command_str = data["command"]
    if not isinstance(command_str, str):
        raise ValueError("Field 'command' must be a string")
    command_list = shlex.split(command_str)

