// corsMiddleware.js
// Express middleware for CORS with credentials.
// Allows origins from a configurable list (partners) and handles
// OPTIONS pre‑flight requests.

const DEFAULT_MAX_AGE = 86400; // 24h in seconds

/**
 * Create a CORS middleware.
 * @param {Object} options
 * @param {string[]} options.allowedOrigins - List of origins that are allowed.
 * @param {string[]} [options.allowedMethods=['GET','POST','PUT','PATCH','DELETE','OPTIONS']]
 * @param {string[]} [options.allowedHeaders=['Content-Type','Authorization']]
 * @param {number}   [options.maxAge=DEFAULT_MAX_AGE]
 * @returns {function} Express middleware
 */
function corsMiddleware({
  allowedOrigins,
  allowedMethods = ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
  allowedHeaders = ['Content-Type', 'Authorization'],
  maxAge = DEFAULT_MAX_AGE,
}) {
  // Convert the array to a Set for O(1) look‑ups.
  const originSet = new Set(allowedOrigins);

  return function (req, res, next) {
    const requestOrigin = req.headers.origin;

    // If the request has an Origin header and it is in the whitelist,
    // echo it back. Otherwise, do not set CORS headers (browser will block).
    if (requestOrigin && originSet.has(requestOrigin)) {
      res.setHeader('Access-Control-Allow-Origin', requestOrigin);
      // Must be true when credentials are used.
      res.setHeader('Access-Control-Allow-Credentials', 'true');
    }

    // Always expose these headers (optional, adjust as needed).
    res.setHeader('Access-Control-Expose-Headers', 'Authorization,Content-Length');

    // Handle pre‑flight request.
    if (req.method === 'OPTIONS') {
      // If origin is not allowed, just respond 403.
      if (!requestOrigin || !originSet.has(requestOrigin)) {
        return res.sendStatus(403);
      }

      res.setHeader('Access-Control-Allow-Methods', allowedMethods.join(','));
      res.setHeader('Access-Control-Allow-Headers', allowedHeaders.join(','));
      res.setHeader('Access-Control-Max-Age', String(maxAge));
      // No body needed for pre‑flight.
      return res.sendStatus(204);
    }

    // For non‑OPTIONS requests, continue down the middleware chain.
    next();
  };
}

module.exports = corsMiddleware;

