// corsMiddleware.js
// Express middleware for CORS with credentials and dynamic partner origins.

module.exports = function createCorsMiddleware(options = {}) {
  // Array of allowed origins (e.g., ['https://partner1.com', 'https://partner2.com'])
  const allowedOrigins = Array.isArray(options.allowedOrigins)
    ? options.allowedOrigins
    : [];

  // Helper to decide if an origin is allowed
  const isOriginAllowed = (origin) =>
    allowedOrigins.includes('*') || allowedOrigins.includes(origin);

  return function corsMiddleware(req, res, next) {
    const origin = req.headers.origin;

    // If the request's Origin header matches an allowed partner, set CORS headers
    if (origin && isOriginAllowed(origin)) {
      res.setHeader('Access-Control-Allow-Origin', origin); // reflect origin
      res.setHeader('Access-Control-Allow-Credentials', 'true');
    }

    // Handle preflight OPTIONS requests
    if (req.method === 'OPTIONS') {
      // Echo requested method(s) and header(s) back to the client
      const reqMethod = req.headers['access-control-request-method'];
      const reqHeaders = req.headers['access-control-request-headers'];

      if (reqMethod) {
