// Express middleware that supports CORS with credentials.
// Allows dynamic configuration of permitted origins (e.g., our web app + partner sites).

/**
 * @param {Object} opts
 * @param {string[]} opts.allowedOrigins - List of origins that are allowed to access the API.
 * @param {string[]} [opts.allowedMethods] - HTTP methods allowed for CORS (default: common verbs).
 * @param {string[]} [opts.allowedHeaders] - Request headers allowed for CORS (default: common headers).
 * @param {number}   [opts.maxAge] - Seconds browsers may cache the preflight response (default: 86400).
 * @returns {function} Express middleware.
 */
function createCorsMiddleware(opts) {
  const {
    allowedOrigins = [],
    allowedMethods = ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
    allowedHeaders = ['Content-Type', 'Authorization', 'X-Requested-With'],
    maxAge = 86400,
  } = opts || {};

  // Helper to test if a request origin is permitted.
  const isOriginAllowed = (origin) => {
    if (!origin) return false;
    // exact match or wildcard "*"
    return allowedOrigins.includes(origin);
  };

  return function corsMiddleware(req, res, next) {
    const requestOrigin = req.headers.origin;

    // If the request's Origin header is allowed, set the CORS headers.
    if (isOriginAllowed(requestOrigin)) {
      res.setHeader('Access-Control-Allow-Origin', requestOrigin);
      // Must be true when credentials are used.
      res.setHeader('Access-Control-Allow-Credentials', 'true');
    }

    // Always expose these headers (optional, adjust as needed).
    res.setHeader('Access-Control-Expose-Headers', 'Content-Length, X-Request-Id');

    // Handle preflight (OPTIONS) requests.
    if (req.method === 'OPTIONS') {
      // If the origin is not allowed, simply return 403.
      if (!isOriginAllowed(requestOrigin)) {
        res.sendStatus(403);
        return;
      }

      res.setHeader('Access-Control-Allow-Methods', allowedMethods.join(','));
      res.setHeader('Access-Control-Allow-Headers', allowedHeaders.join(','));
      res.setHeader('Access-Control-Max-Age', String(maxAge));

      // No body needed for preflight response.
      res.sendStatus(204);
      return;
    }

    // For non‑OPTIONS requests, continue down the middleware chain.
    next();
  };
}

