 * @param {number} [opts.maxAge] - Max‑age for preflight cache (seconds)
 * @returns {Function} Express middleware
 */
function corsMiddleware(opts = {}) {
  const {
    allowedOrigins = [],                 // e.g. ['https://myapp.com', 'https://partner.com']
    allowedMethods = ['GET','HEAD','POST','PUT','PATCH','DELETE','OPTIONS'],
    allowedHeaders = null,               // null → use request's Access-Control-Request-Headers
    maxAge = 86400,                      // 24h
  } = opts;

  // Helper to test if an origin is permitted
  const isOriginAllowed = typeof allowedOrigins === 'function'
    ? allowedOrigins
    : (origin) => allowedOrigins.includes(origin);

  return function (req, res, next) {
    const origin = req.headers.origin;

    // If no Origin header, skip CORS handling (e.g., same‑origin requests)
    if (!origin) return next();

    // Only set CORS headers for allowed origins
    if (isOriginAllowed(origin)) {
      res.setHeader('Access-Control-Allow-Origin', origin);
      res.setHeader('Vary', 'Origin');               // Ensure caches vary by Origin
      res.setHeader('Access-Control-Allow-Credentials', 'true');

      // Preflight handling
      if (req.method === 'OPTIONS') {
        // Access-Control-Request-Method header is required for a valid preflight
        const requestMethod = req.headers['access-control-request-method'];
        if (requestMethod) {
          res.setHeader('Access-Control-Allow-Methods', allowedMethods.join(','));
          const requestHeaders = req.headers['access-control-request-headers'];
          if (allowedHeaders) {
            res.setHeader('Access-Control-Allow-Headers', allowedHeaders.join(','));
          } else if (requestHeaders) {
            // Echo back requested headers (must be a comma‑separated list)
            res.setHeader('Access-Control-Allow-Headers', requestHeaders);
          }
          res.setHeader('Access-Control-Max-Age', String(maxAge));
        }
        // No body for preflight response
        return res.sendStatus(204);
      }
    }

    // For disallowed origins we simply continue without CORS headers
    next();
  };
}

