// corsMiddleware.js
// Express middleware for CORS with credentials.
// Allows dynamic configuration of partner origins and handles OPTIONS preflight.

const defaultOptions = {
  // Array of allowed origins (e.g. ['https://example.com', 'https://partner.com'])
  // Use '*' to allow any origin (not recommended with credentials).
  allowedOrigins: [],

  // HTTP methods that are allowed for CORS requests.
  methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],

  // Headers that the client may send.
  allowedHeaders: ['Content-Type', 'Authorization', 'X-Requested-With'],

  // Headers exposed to the browser.
  exposedHeaders: [],

  // Max age for preflight cache (seconds).
  maxAge: 86400,
};

/**
 * Create a CORS middleware.
 * @param {Object} opts Configuration options (see defaultOptions).
 * @returns {Function} Express middleware.
 */
function corsMiddleware(opts = {}) {
  const config = { ...defaultOptions, ...opts };

  // Helper to determine if an origin is allowed.
  const isOriginAllowed = (origin) => {
    if (!origin) return false;
    if (config.allowedOrigins.includes('*')) return true;
    return config.allowedOrigins.includes(origin);
  };

  return function (req, res, next) {
    const requestOrigin = req.headers.origin;

    // If the request origin is allowed, set the appropriate CORS headers.
    if (isOriginAllowed(requestOrigin)) {
      res.setHeader('Access-Control-Allow-Origin', requestOrigin);
      // Must be true when credentials are used.
      res.setHeader('Access-Control-Allow-Credentials', 'true');
    }

    // Always set the Vary header so caches differentiate by Origin.
    res.setHeader('Vary', 'Origin');

    // Handle preflight (OPTIONS) requests.
    if (req.method === 'OPTIONS') {
      // If the origin is not allowed, simply end the request with 204.
      if (!isOriginAllowed(requestOrigin)) {
        return res.sendStatus(204);
      }

      res.setHeader('Access-Control-Allow-Methods', config.methods.join(','));
      res.setHeader(
        'Access-Control-Allow-Headers',
        config.allowedHeaders.join(',')
      );

      if (config.exposedHeaders.length) {
        res.setHeader(
          'Access-Control-Expose-Headers',
          config.exposedHeaders.join(',')
        );
      }

      if (config.maxAge) {
        res.setHeader('Access-Control-Max-Age', String(config.maxAge));
      }

      // No body needed for preflight response.
      return res.sendStatus(204);
    }

    // For non‑OPTIONS requests just continue.
    next();
  };
}

module.exports = corsMiddleware;

