// corsMiddleware.js
// Express middleware that handles CORS with credentials.
//   • Accepts a list of allowed origins (partners) that can be updated at runtime.
//   • Sets the proper Access‑Control headers.
//   • Responds to OPTIONS preflight requests with 204 No Content.

const DEFAULT_OPTIONS = {
  // HTTP methods your API supports
  methods: ['GET', 'HEAD', 'PUT', 'POST', 'PATCH', 'DELETE'],
  // Headers the client may send (use '*' to allow any)
  allowedHeaders: '*',
  // Max age for preflight cache (seconds)
  maxAge: 86400,
};

/**
 * Create a CORS middleware.
 *
 * @param {Object} config
 * @param {string[]} config.allowedOrigins - Array of origins that are allowed.
 * @param {string[]} [config.methods]       - HTTP methods to allow (defaults to DEFAULT_OPTIONS.methods).
 * @param {string|string[]} [config.allowedHeaders] - Headers to allow (defaults to '*').
 * @param {number} [config.maxAge]         - Preflight cache time in seconds.
 * @returns {Function} Express middleware.
 */
function createCorsMiddleware(config) {
  const {
    allowedOrigins = [],
    methods = DEFAULT_OPTIONS.methods,
    allowedHeaders = DEFAULT_OPTIONS.allowedHeaders,
    maxAge = DEFAULT_OPTIONS.maxAge,
  } = config || {};

  // Use a Set for O(1) origin look‑ups and allow dynamic updates.
  const originSet = new Set(allowedOrigins);

  // Helper to check if an origin is permitted.
  const isOriginAllowed = (origin) => origin && originSet.has(origin);

  // The actual middleware function.
  return function corsMiddleware(req, res, next) {
    const requestOrigin = req.headers.origin;

    // If the origin is allowed, set the required CORS headers.
    if (isOriginAllowed(requestOrigin)) {
      res.setHeader('Access-Control-Allow-Origin', requestOrigin);
      res.setHeader('Access-Control-Allow-Credentials', 'true');
      res.setHeader('Vary', 'Origin'); // Ensure caches vary by Origin.
    }

    // Always expose the allowed methods & headers for preflight handling.
    if (req.method === 'OPTIONS') {
      // Preflight requests may include Access-Control-Request-Method/Header.
      // We simply echo the configured values.
      if (isOriginAllowed(requestOrigin)) {
        res.setHeader('Access-Control-Allow-Methods', methods.join(','));
        // If allowedHeaders is '*', mirror the request's Access-Control-Request-Headers.
        if (allowedHeaders === '*') {
          const requestHeaders = req.headers['access-control-request-headers'];
          if (requestHeaders) {
            res.setHeader('Access-Control-Allow-Headers', requestHeaders);
          }
        } else {
          res.setHeader('Access-Control-Allow-Headers', Array.isArray(allowedHeaders)
            ? allowedHeaders.join(',')
            : allowedHeaders);
        }
        res.setHeader('Access-Control-Max-Age', String(maxAge));
      }
      // End preflight without passing to further handlers.
      return res.sendStatus(204);
    }

    // For non‑OPTIONS requests continue the chain.
    next();
  };
}

/**
 * Utility to add or remove origins at runtime.
 *
 * @param {Function} middleware - The middleware returned by createCorsMiddleware.
 * @param {string[]} add    - Origins to add.
 * @param {string[]} remove - Origins to remove.
 */
function updateOrigins(middleware, { add = [], remove = [] } = {}) {
  if (!middleware || !middleware.originSet) return;
  add.forEach((o) => middleware.originSet.add(o));
  remove.forEach((o) => middleware.originSet.delete(o));
}

// Export both the factory and the updater.
module.exports = {
  createCorsMiddleware,
  updateOrigins,
};
