 * @param {Iterable<string>} [options.origins] - Initial list of partner origins.
 * @param {string[]} [options.methods] - Allowed HTTP methods.
 * @param {string[]} [options.allowedHeaders] - Allowed request headers.
 * @param {number} [options.maxAge] - Pre‑flight cache duration in seconds.
