// corsMiddleware.js
// Express middleware for CORS with credentials.
// Allows dynamic configuration of partner origins and handles OPTIONS preflight.

const DEFAULT_METHODS = 'GET,HEAD,PUT,PATCH,POST,DELETE';
const DEFAULT_HEADERS = 'Origin, X-Requested-With, Content-Type, Accept, Authorization';

function createCorsMiddleware(initialOrigins = []) {
  // Set of allowed origins – using a Set makes add/remove O(1)
  const allowedOrigins = new Set(initialOrigins);

  // Middleware function
  const cors = (req, res, next) => {
    const origin = req.headers.origin;

    // If the request origin is in the whitelist, echo it back
    if (origin && allowedOrigins.has(origin)) {
      res.setHeader('Access-Control-Allow-Origin', origin);
      // Must be true when credentials are used
      res.setHeader('Access-Control-Allow-Credentials', 'true');
    }

    // Always expose these headers (optional, adjust as needed)
    res.setHeader('Access-Control-Expose-Headers', 'Content-Length, X-Kuma-Revision');

    // Handle preflight requests
    if (req.method === 'OPTIONS') {
      // Allow the same origin as above (or skip if not whitelisted)
      if (origin && allowedOrigins.has(origin)) {
        res.setHeader('Access-Control-Allow-Methods', DEFAULT_METHODS);
        // Allow any header the client asks for, or fall back to defaults
        const requestHeaders = req.headers['access-control-request-headers'];
        res.setHeader(
          'Access-Control-Allow-Headers',
          requestHeaders || DEFAULT_HEADERS
        );
        // Some browsers expect a max age for caching the preflight response
        res.setHeader('Access-Control-Max-Age', '86400'); // 24 hours
      }
      // End the preflight request with 204 No Content
      return res.sendStatus(204);
    }

    // For non‑OPTIONS requests, continue down the stack
    next();
  };

  // Helper to add a new partner origin at runtime
  cors.addOrigin = (origin) => {
    if (origin) allowedOrigins.add(origin);
  };

  // Helper to remove an origin (e.g., if a partner leaves)
  cors.removeOrigin = (origin) => {
    allowedOrigins.delete(origin);
  };

  // Expose the current list (read‑only) for debugging / admin UI
  cors.getOrigins = () => Array.from(allowedOrigins);

  return cors;
}

module.exports = { createCorsMiddleware };
